 p_id=>wwv_flow_imp.id(308164825200529835.4001)
,p_plugin_id=>wwv_flow_imp.id(356678515020447691.4001)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>3
,p_display_sequence=>30
,p_prompt=>'URL'
,p_attribute_type=>'TEXT'
,p_is_required=>true
