,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select p.id,',
'       p.flow_id the_flow,',
'       name,',
'       tab_set,',
'       p.id||'' - ''||name icon_text,',
'       last_updated_on updated,',
'       lower(last_updated_by) last_updated_by,',
'       created_on,',
'       lower(created_by) created_by,',
'       case ',
'         when p.page_mode = ''NORMAL'' and page_component_map <> 14 then',
'           wwv_flow_page_api.get_url (',
'               p_page    => ''RUN_PAGE'',',
'               p_request => ''BRANCH_TO_PAGE_ACCEPT'',',
'               p_items   => ''FB_FLOW_PAGE_ID,FB_FLOW_ID'',',
'               p_values  => p.id||'',''||p.flow_id )',
'         else null',
'       end as run_link,',
'       decode(',
'           l.locked_by,',
'           null,',
'           wwv_flow_page_api.get_url (',
'               p_page        => 444,',
'               p_clear_cache => 444,',
'               p_items       => ''P337_ID,FB_FLOW_PAGE_ID,P444_LOCK_PAGES'',',
'               p_values      => p.id||'',''||p.id||'',''||p.id),',
'           wwv_flow_page_api.get_url (',
'               p_page        => 337,',
'               p_clear_cache => 337,',
'               p_items       => ''P337_ID,FB_FLOW_PAGE_ID'',',
'               p_values      => l.id||'',''||p.id)) as lock_link,',
'       case ',
'         when l.locked_by is null then wwv_flow_lang.system_message( ''BU.UNLOCKED'' )',
'         else wwv_flow_lang.system_message( ''BU.LOCKED'' )',
'       end as lock_label,',
'       case ',
'         when l.locked_by is null then ''icon-unlock''',
'         when l.locked_by = :APP_USER then ''icon-lock-s''',
'         else ''icon-lock-user''',
'       end as lock_icon,',
'       decode(',
'           l.locked_by,',
'           null, sm.t_no,',
'           sm.t_yes) page_is_locked,',
'       nvl( g.group_name,sm.t_unassigned ) group_name,',
'       decode(',
'           g.group_name,',
'           null,',
'           wwv_flow_page_api.get_url (',
'               p_page        => 520,',
'               p_clear_cache => 520),',
'           wwv_flow_page_api.get_url (',
'               p_page        => 521,',
'               p_clear_cache => ''521,RP,RIR'',',
'               p_items       => ''P521_ID'',',
'               p_values      => g.id)',
'           ) group_link,',
'       p.page_type,',
'       p.page_mode,',
'       -- icon columns',
'       decode(substr(nvl(page_component_map,''00''),1,2),',
'             ''01'',''icon-page-form-tabular'',',
'             ''02'',''icon-page-form'',',
'             ''03'',''icon-page-report'',',
'             ''04'',''icon-page-chart'',',
'             ''05'',''icon-page-webservice'',',
'             ''06'',''icon-page-nav'',',
'             ''07'',''icon-page-tree'',',
'             ''08'',''icon-page-calendar'',',
'             ''09'',''icon-page-url'',',
'             ''10'',''icon-page-dynamic'',',
'             ''11'',''icon-page-static'',',
'             ''12'',''icon-page-login'',',
'             ''13'',''icon-page-home'',',
'             ''14'',''icon-page-global'',',
'             ''15'','' '',',
'             ''16'',''icon-page-dynamic-form'',',
'             ''17'',''icon-page-wizard'',',
'             ''18'',''icon-page-ir'',',
'             ''19'',''icon-page-map'',',
'             ''20'',''icon-page-tree'',',
'             ''21'',''icon-page-report'',',
'             ''22'',''icon-page-faceted-search'',',
'             ''23'',''icon-page-cards'',',
'             ''24'',''icon-page-smart-filters'',',
'             ''25'',''icon-page-dynamic'',',
'             ''26'',''icon-page-search'',',
'             ''27'',''icon-page-tmpl-report'',',
'             ''28'',''icon-page-pattern'',',
'             '' '') page_type_class,',
'       wwv_flow_page_api.get_url (',
'               p_page   => 4500,',
'               p_items  => ''FB_FLOW_ID,FB_FLOW_PAGE_ID'',',
'               p_values => p.flow_id||'',''||p.id) edit_page_url,',
'       lower(alias) alias,',
'       step_title Page_title,',
'       decode(',
'           first_item,',
'           ''NO_FIRST_ITEM'', sm.t_no,',
'           ''AUTO_FIRST_ITEM'', sm.auto_first_item,',
'           sm.t_no) first_item,',
'       decode(',
'           include_apex_css_js_yn,',
'           ''Y'', sm.t_yes,',
'           ''N'', sm.t_no,',
'           include_apex_css_js_yn ) include_apex_css_js,',
'       help_text,',
'       footer_text,',
'       welcome_text header_text,',
'       ( select name from wwv_flow_templates t where p.STEP_TEMPLATE = t.id and t.security_group_id in ( :WORKSPACE_ID, 11, 12 ) ) page_template,',
'       case',
'         when p.required_role = ''MUST_NOT_BE_PUBLIC_USER'' then',
'             t_must_not_be_public_user',
'         else (select case when p.required_role like ''!%'' then ''{'' end||',
'                      max(name) ||',
'                      case when p.required_role like ''!%'' then ''}'' end',
'                 from wwv_flow_security_schemes s',
'                where s.flow_id = p.flow_id and to_char(s.id) = ltrim(p.REQUIRED_ROLE,''!''))',
'       end authorization_scheme,',
'       (select patch_name',
'          from wwv_flow_patches bo',
'         where bo.id = p.required_patch) build_option,',
'       html_page_header,',
'       html_page_onload,',
'       decode(',
'           allow_duplicate_submissions,',
'           ''Y'', sm.t_yes,',
'           ''N'', sm.t_no,',
'           sm.t_yes) allow_duplicate_submissions,',
'       on_dup_submission_goto_url,',
'       decode(',
'           page_is_public_y_n,',
'           ''Y'', sm.t_yes,',
'           ''N'', sm.t_no,',
'           page_is_public_y_n) page_is_public,',
'       decode(',
'           protection_level,',
'           ''D'', sm.no_url_access,',
'           ''N'', sm.unrestricted,',
'           ''U'', sm.no_arguments_allowed,',
'           ''C'', sm.arguments_must_have_checksum,',
'           sm.unrestricted ) protection_level,',
'       error_notification_text,',
'       decode(',
'           cache_mode,',
'           ''NOCACHE'', sm.t_no,',
'           sm.t_yes) cache_page,',
'       cache_timeout_seconds,',
'       page_comment,',
'       sm.edit,',
'       --',
'       null as actions',
'  from wwv_flow_pages_dev p,',
'       wwv_flow_lock_page l,',
'       (select wwv_flow_lang.system_message(''EDIT'') edit,',
'               wwv_flow_lang.system_message(''F4000.YES'') t_yes,',
'               wwv_flow_lang.system_message(''F4000.NO'') t_no,',
'               wwv_flow_lang.system_message(''AUTO_FIRST_ITEM'') auto_first_item,',
'               wwv_flow_lang.system_message(''NO_URL_ACCESS'') NO_URL_ACCESS,',
'               wwv_flow_lang.system_message(''UNRESTRICTED'') unrestricted,',
'               wwv_flow_lang.system_message(''NO_ARGUMENTS_ALLOWED'') no_arguments_allowed,',
'               wwv_flow_lang.system_message(''ARGUMENTS_MUST_HAVE_CHECKSUM'') arguments_must_have_checksum,',
'               wwv_flow_lang.system_message(''Unassigned'') t_unassigned,',
'               wwv_flow_lang.system_message(''MUST_NOT_BE_PUBLIC_USER'') t_must_not_be_public_user',
'          from sys.dual) sm,',
'       wwv_flow_page_groups g',
' where p.flow_id           = :fb_flow_id',
'   and p.security_group_id = :flow_security_group_id',
'   and p.flow_id           = l.flow_id   (+)',
'   and p.id                = l.object_id (+)',
'   and p.group_id          = g.id        (+)'))
,p_plug_source_type=>'NATIVE_IR'
,p_plug_query_show_nulls_as=>' - '
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_prn_output_show_link=>'Y'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
,p_prn_page_header_font_color=>'#000000'
,p_prn_page_header_font_family=>'Helvetica'
,p_prn_page_header_font_weight=>'normal'
,p_prn_page_header_font_size=>'12'
,p_prn_page_footer_font_color=>'#000000'
,p_prn_page_footer_font_family=>'Helvetica'
,p_prn_page_footer_font_weight=>'normal'
,p_prn_page_footer_font_size=>'12'
,p_prn_header_bg_color=>'#9bafde'
,p_prn_header_font_color=>'#ffffff'
,p_prn_header_font_family=>'Helvetica'
,p_prn_header_font_weight=>'normal'
,p_prn_header_font_size=>'10'
,p_prn_body_bg_color=>'#efefef'
,p_prn_body_font_color=>'#000000'
