wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(1447983026818614.4001)
,p_process_sequence=>60
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Init Refresh Theme'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    c_universal_theme            constant varchar2(15) := ''UNIVERSAL_THEME'';',
'    l_version_current_ut                  wwv_flow_themes.version_identifier%type;',
'    l_version_latest_ut                   wwv_flow_themes.version_identifier%type;',
'    l_version_current_ut_numeric          number;',
'    l_version_latest_ut_numeric           number;',
'begin',
'    select t.id,',
'           case when ts.theme_roller_config is not null then ''Y'' else ''N'' end,',
'           t.version_identifier',
'      into :P1_SUBSCRIBING_THEME_ID,',
'           :P1_HAS_CUSTOM_STYLE,',
'           l_version_current_ut',
'      from wwv_flows f,',
'           wwv_flow_themes t,',
'           wwv_flow_themes mt,',
'           wwv_theme_styles ts',
'     where f.id                  = :FB_FLOW_ID',
'       and f.security_group_id   = :WORKSPACE_ID',
'       and t.flow_id             = f.id',
'       and t.theme_id            = f.theme_id   ',
'       and t.security_group_id   = f.security_group_id',
'       and t.theme_internal_name = c_universal_theme',
'       and mt.id                 = t.reference_id',
'       and mt.security_group_id  = 12 -- only show this when subscribed to central UT',
'       and ts.id             (+) = t.current_theme_style_id;',
'',
'    select version_identifier',
'      into l_version_latest_ut',
'      from wwv_flow_themes',
'     where theme_internal_name = c_universal_theme',
'       and security_group_id   = 12',
'       and flow_id            != 8842 -- except legacy UT',
'    order by flow_id desc',
'    fetch first row only;',
'',
'    -- extract the theme number from the current theme',
'    l_version_current_ut_numeric := to_number(',
'                                        l_version_current_ut,',
'                                        ''90D9'',',
'                                        ''NLS_NUMERIC_CHARACTERS=''''.,'''''' );',
'',
'    -- extract the theme number from the central theme',
'    l_version_latest_ut_numeric := to_number(',
'                                       l_version_latest_ut,',
'                                       ''90D9'',',
'                                       ''NLS_NUMERIC_CHARACTERS=''''.,'''''' );',
'',
'    -- only show the refresh region if there is a UT version to upgrade to',
'    if l_version_current_ut_numeric >= l_version_latest_ut_numeric then',
'        :P1_SUBSCRIBING_THEME_ID := null;',
'        :P1_HAS_CUSTOM_STYLE     := null;',
'    end if;',
'',
'exception ',
'    when others then',
'        :P1_SUBSCRIBING_THEME_ID := null;',
'        :P1_HAS_CUSTOM_STYLE     := null;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>1447983026818614.4001
);
