,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Las definiciones de objeto de soporte se pueden exportar de manera opcional con la aplicaci\00F3n. Se incluyen todas las opciones de configuraci\00F3n y todos los scripts.</p>'),
'<ul>',
'<li>',
unistr('<strong>S\00ED</strong> incluye las definiciones de objeto de soporte en la exportaci\00F3n de la aplicaci\00F3n. No carga autom\00E1ticamente objetos de soporte de cuando se llaman desde una l\00EDnea de comandos.'),
'<li>',
'<li>',
unistr('<strong>No</strong> no incluye las definiciones de objeto de soporte en la exportaci\00F3n.'),
'</li>',
'<li>',
unistr('<strong>S\00ED e Instalar al Importar Autom\00E1ticamente</strong> incluye definiciones de objeto soporte y una llamada para instalar los objetos de soporte en la exportaci\00F3n de la aplicaci\00F3n. Esta opci\00F3n solo es v\00E1lida para instalaciones de la l\00EDnea de coma')
||unistr('ndos. Cuando la aplicaci\00F3n importa desde la l\00EDnea de comandos, instala o actualiza autom\00E1ticamente los objetos de soporte.'),
'</li>',
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'based_on', 'PLSQL',
  'format', 'PLAIN',
  'pl_sql_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'sys.htp.p( ''<a title="'' || wwv_flow_escape.html( wwv_flow_lang.system_message( p_name => ''F4000.P2.UPDATE_EXPORT_SETTINGS'' ) ) ||',
    '           ''" href="'' ||',
    '           wwv_flow_utilities.prepare_url( ''f?p=&APP_ID.:633:'' || :APP_SESSION ) ||',
    '           ''">'' || wwv_flow_escape.html( wwv_flow_item.text_from_lov( p_value => :P2_INCLUDE_IN_EXPORT,',
    '                                                                      p_lov   => ''EXPORT_SUP_OBJ_OPTIONS'' ) ) ||',
    '           ''</a>'' );')),
  'send_on_page_submit', 'N',
  'show_line_breaks', 'N')).to_clob
);
