prompt --application/pages/page_00006
begin
wwv_flow_imp_page.create_page(
 p_id=>6.4001
,p_name=>'Refrescar suscripciones'
,p_alias=>'REFRESH-SUBSCRIPTIONS'
,p_page_mode=>'MODAL'
,p_step_title=>'Refrescar suscripciones'
,p_autocomplete_on_off=>'OFF'
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(4412344688904126.4001)
,p_plug_name=>'Suscripciones que es necesario refrescar'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(646287526247383209.4001)
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select component_type,',
'       component_id id,',
'       reference_id,',
'       master_application_id,',
'       component_name,',
'       subscription_status',
'  from wwv_flow_subscribed_comp_dev',
' where component_type = :P6_COMPONENT_TYPE',
