,p_plug_display_sequence=>10
,p_plug_source=>unistr('<big>El dise\00F1ador de p\00E1ginas es un entorno de desarrollo integrado (IDE) global que se utiliza para mantener y mejorar p\00E1ginas en las aplicaciones de &PRODUCT_NAME..</big>')
