,p_plug_display_sequence=>150
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Ha solicitado la sustituci\00F3n del plugin existente en <strong>&P4450_DISPLAY_NAME. (&P4450_NAME.)</strong>, en la'),
