,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(29434107863295859.4001)
,p_plug_display_sequence=>20
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>La aplicaci\00F3n que se va a sustituir tiene procesos de p\00E1gina con ejecuciones en segundo plano activadas. &P48_BG_EXECS_COUNT_TEXT!RAW.</p>'),
'<ul>',
unistr('    <li>Utilice el bot\00F3n <strong>Desactivar ejecuci\00F3n en segundo plano</strong> para <em>evitar que se inicien nuevas ejecuciones</em> (debe definir el atributo <strong>m\00E1ximo de trabajos de programador</strong> en cero) y vuelva a esta p\00E1gina.</li>'),
unistr('    <li>Utilice el bot\00F3n <strong>Sustituir aplicaci\00F3n</strong> para instalar ahora la aplicaci\00F3n importada. Las ejecuciones en segundo plano en curso se terminar\00E1n y las ejecuciones en espera se suprimir\00E1n.</li>'),
'</ul>'))
,p_plug_display_condition_type=>'EXPRESSION'
,p_plug_display_when_condition=>':P48_HAS_BG_PROCESSES = ''Y'' and nvl( :P48_MAX_SCHEDULER_JOBS, 1 ) != 0'
