,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'createApplication'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_theme    wwv_flow_create_app_v3.t_theme;',
'begin',
'    -- default theme to UT',
'    l_theme.id          := 42;',
'    l_theme.theme_type  := ''UT'';',
'    l_theme.theme_style := ''Vita'';',
'',
'    wwv_flow_create_app_v3.create_app(',
'        -- required parameters',
'        p_app_id              => :P56_APP_ID,',
'        p_app_name            => :P56_APP_NAME,',
'        p_parsing_schema      => wwv_flow_user_api.get_default_schema,',
'        p_app_language        => :BROWSER_LANGUAGE,',
'        p_theme               => l_theme,',
'        -- build icon parameters',
'        p_app_icon_class      => :P56_APP_ICON_CLASS,',
'        p_app_color_class     => :P56_APP_COLOR_CLASS,',
