wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(1596644594608873.4001)
,p_process_sequence=>30
,p_process_point=>'AFTER_FOOTER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Unset flow IDs'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
':FB_FLOW_ID := null;',
':FB_FLOW_PAGE_ID := null;',
':F4000_P1_FLOW := null;',
':F4000_P1_PAGE := null;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select id from wwv_flows ',
' where id = :FB_FLOW_ID ',
'   and build_status = ''RUN_ONLY''',
'   and security_group_id = :flow_security_group_id'))
,p_process_when_type=>'EXISTS'
,p_internal_uid=>1596644594608873.4001
