);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(687105780636946470.4001)
,p_plug_name=>'Grupos de Opciones de Plantilla'
,p_region_template_options=>'#DEFAULT#:a-Region--noPadding:a-Region--accessibleHeader'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4001)
,p_plug_display_sequence=>10
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select tog.id,',
'       tog.flow_id,',
'       tog.theme_id,',
'       tog.name,',
'       tog.display_name,',
'       tog.display_sequence,',
'       tog.template_types,',
'       tog.help_text,',
'       tog.null_text,',
'       tog.is_advanced',
'  from wwv_flow_template_opt_groups tog',
' where ( tog.flow_id, tog.theme_id, tog.security_group_id ) in',
'       (',
'        ( :FB_FLOW_ID, :P81_THEME_ID, :WORKSPACE_ID ),',
'        ( ( select wwv_flow_theme_manager.get_central_application_id( :FB_FLOW_ID, :P81_THEME_ID ) from sys.dual ),',
'          ( select wwv_flow_theme_manager.get_central_theme_id( :FB_FLOW_ID, :P81_THEME_ID ) from sys.dual ),',
'          ( select wwv_flow_theme_manager.get_central_workspace_id( :FB_FLOW_ID, :P81_THEME_ID ) from sys.dual ) )',
'       )',
'   and tog.template_types = coalesce( :P81_TEMPLATE_TYPE, tog.template_types )'))
,p_plug_source_type=>'NATIVE_IG'
,p_ajax_items_to_submit=>'P81_TEMPLATE_TYPE'
,p_plug_read_only_when_type=>'EXISTS'
,p_plug_read_only_when=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select 1',
'  from wwv_flow_themes',
' where security_group_id = :WORKSPACE_ID',
'   and flow_id           = :FB_FLOW_ID',
'   and theme_id          = :P81_THEME_ID',
'   and reference_id      is not null'))
,p_prn_output_show_link=>'Y'
