,p_prompt=>'Antes de Etiqueta'
,p_source=>'TEMPLATE_BODY1'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'PLUGIN_COM.ORACLE.APEX.CODE_EDITOR'
,p_cSize=>100
,p_cMaxlength=>4000
,p_cHeight=>6
,p_tag_attributes=>'onchange="htmldb_item_change(this)"'
,p_field_template=>wwv_flow_imp.id(561549638722251517.4001)
,p_item_template_options=>'#DEFAULT#'
,p_escape_on_http_input=>'Y'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<div class="htmldbInfoBodyP">Introduzca el HTML que aparecer\00E1 antes de una etiqueta de elemento.</div>'),
unistr('<div class="htmldbInfoBodyP">Nota: la etiqueta aparecer\00E1 autom\00E1ticamente despu\00E9s del HTML en esta regi\00F3n. Por lo tanto, al abrir una etiqueta &lt;a&gt;, por ejemplo, se debe cerrar en la regi\00F3n Despu\00E9s de Etiqueta.</div>'),
unistr('<div class="htmldbInfoBodyP">Las siguientes cadenas de sustituci\00F3n est\00E1n disponibles para este atributo:'),
'<ul class="noIndent">',
'<li>#CURRENT_FORM_ELEMENT#</li>',
'<li>#CURRENT_ITEM_ID#</li>',
'<li>#CURRENT_ITEM_NAME#</li>',
'<li>#CURRENT_ITEM_HELP_TEXT#</li>',
'<li>#LABEL_ID#</li>',
'<li>#LABEL_COLUMN_SPAN_NUMBER#</li>',
'<li>#LABEL_COLUMN_SPAN_ALPHA#</li>',
'<li>#LABEL_COLUMN_SPAN_WORD#</li>',
'<li>#LABEL_COLUMN_SPAN_PLURAL#</li>',
'</ul>',
'</div>',
