,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'IS_NAME_TAKEN'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- pass 1 or more file names in the f01 array',
'declare',
'    l_is_name_taken boolean         := false;',
'    l_directory     varchar2(4000)  := wwv_flow_file_api.clean_dirname( :P118_DIRECTORY );',
'    l_file_name     varchar2(4000);',
'begin',
'    for i in 1 .. wwv_flow.g_f01.count loop',
'',
'        l_file_name := wwv_flow_file_api.get_file_name( l_directory, wwv_flow.g_f01( i ) );',
'',
'        if l_file_name is not null and',
'           wwv_flow_file_editor_dev.file_name_is_taken (',
'                p_scope     => :P118_SCOPE,',
'                p_app_id    => :P118_APP_ID,',
'                p_plugin_id => :P118_PLUGIN_ID,',
'                p_theme_id  => :P118_THEME_ID,',
'                p_ignore_id => :P118_ID,',
'                p_name      => l_file_name )',
'        then',
'            l_is_name_taken := true;',
'            exit;',
'        end if;',
'    end loop;',
'',
'    wwv_flow_json.open_object;',
'    wwv_flow_json.write( ''isNameTaken'', l_is_name_taken );',
'    wwv_flow_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>36741959531433204.4001
);
end;
