 p_id=>wwv_flow_imp.id(36099000144565166.4001)
,p_validation_name=>'nothing to copy'
,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'  for i in 1..wwv_flow.g_f01.count loop',
'    if wwv_flow.g_f03(i) in (''Y'',''SUBSCRIBE'') then',
'      return true;',
'    end if;',
'  end loop;',
'  return false;',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>'No hay ninguna lista de valores para copiar.'
,p_when_button_pressed=>wwv_flow_imp.id(202846810302732194.4001)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(291077815324830905.4001)
,p_validation_name=>'No duplicate names - Copy'
,p_validation_sequence=>20
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_found_name varchar2(4000);',
'begin',
'    for i in 1..wwv_flow.g_f01.count',
'    loop',
'        continue when wwv_flow.g_f03(i) != ''Y'';',
'        ',
'        for c1 in ( select curr.lov_name',
'                      from wwv_flow_lists_of_values$ curr',
'                     where curr.flow_id           = :FB_FLOW_ID',
'                       and curr.security_group_id = :WORKSPACE_ID',
'                       and curr.lov_name          = wwv_flow.g_f02(i) ) ',
'        loop',
'            if l_found_name is null then ',
'                l_found_name := c1.lov_name;',
'            else ',
'                l_found_name := l_found_name||'', ''||c1.lov_name;',
'            end if;              ',
'        end loop;',
'    end loop;',
'    ',
'    if l_found_name is not null then ',
'        return wwv_flow_lang.system_message( ''F4000_LOV_NAME_EXISTS'', l_found_name );',
'    end if;',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_when_button_pressed=>wwv_flow_imp.id(202846810302732194.4001)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(1820684102305506.4001)
,p_validation_name=>'No duplicate names - Subscribe'
,p_validation_sequence=>30
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_found_name varchar2(4000);',
'begin',
'    for i in 1..wwv_flow.g_f01.count',
'    loop',
'        continue when wwv_flow.g_f03(i) != ''SUBSCRIBE'';',
'        ',
'        for c1 in ( select curr.lov_name',
'                      from wwv_flow_lists_of_values$ curr,',
'                           wwv_flow_lists_of_values$ mast',
'                     where curr.flow_id           = :FB_FLOW_ID',
'                       and curr.security_group_id = :WORKSPACE_ID',
'                       and mast.security_group_id = :WORKSPACE_ID',
'                       and mast.id                = wwv_flow.g_f01(i)',
'                       and mast.lov_name          = curr.lov_name ) ',
'        loop',
'            if l_found_name is null then ',
'                l_found_name := c1.lov_name;',
'            else ',
'                l_found_name := l_found_name||'', ''||c1.lov_name;',
'            end if;              ',
'        end loop;',
'    end loop;',
'    ',
'    if l_found_name is not null then ',
'        return wwv_flow_lang.system_message( ''F4000_LOV_NAME_EXISTS_SUBSCRIPTION'', l_found_name );',
'    end if;',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_when_button_pressed=>wwv_flow_imp.id(202846810302732194.4001)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(1820507174305505.4001)
,p_validation_name=>'No duplicate subscription'
,p_validation_sequence=>40
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_found_name varchar2(4000);',
'begin',
'    for i in 1..wwv_flow.g_f01.count',
'    loop',
'        continue when wwv_flow.g_f03(i) != ''SUBSCRIBE'';',
'        ',
'        for c1 in ( select mast.lov_name',
'                      from wwv_flow_lists_of_values$ mast',
'                     where mast.security_group_id = :WORKSPACE_ID',
'                       and mast.id                = wwv_flow.g_f01(i)',
'                       and exists (',
'                           select 1',
'                             from wwv_flow_lists_of_values$ curr',
'                            where curr.flow_id           = :FB_FLOW_ID',
'                              and curr.security_group_id = :WORKSPACE_ID',
'                              and curr.reference_id      = mast.id ) ) ',
'        loop',
'            if l_found_name is null then ',
'                l_found_name := c1.lov_name;',
'            else ',
'                l_found_name := l_found_name||'', ''||c1.lov_name;',
'            end if;              ',
'        end loop;',
'    end loop;',
'    ',
'    if l_found_name is not null then ',
'        return wwv_flow_lang.system_message( ''F4000_LOV_SUBSCRIPTIONS_EXISTS'', l_found_name );',
'    end if;',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_when_button_pressed=>wwv_flow_imp.id(202846810302732194.4001)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
