wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(202854401582740437.4001)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Copy LOV'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_lov_id number;',
'begin',
'    for i in 1..wwv_flow.g_f03.count loop',
'        l_lov_id := wwv_flow_id.next_val;',
'      ',
'        if wwv_flow.g_f03(i) in (''Y'',''SUBSCRIBE'') then',
'            wwv_flow_lov_dev.copy_named_lov(',
'                p_copy_from_flow_id => :F4000_P138_COPY_FROM_FLOW_ID,',
'                p_flow_id           => :fb_flow_id,',
'                p_lov_id_from       => wwv_flow.g_f01(i),',
'                p_lov_name_to       => wwv_flow.g_f02(i),',
'                p_lov_id_to         => l_lov_id,',
'                p_subscribe         => wwv_flow.g_f03(i) = ''SUBSCRIBE'' );',
'        end if;',
'    end loop;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'Error al copiar listas de valores.'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(202846810302732194.4001)
,p_process_success_message=>'Listas de valores copiadas.'
,p_internal_uid=>202854401582740437.4001
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(574038084178616911.4001)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_CLOSE_WINDOW'
,p_process_name=>'Close Dialog'
,p_attribute_01=>'FB_FLOW_ID,FB_FLOW_PAGE_ID'
,p_attribute_02=>'N'
