,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>No se ha podido instalar la aplicaci\00F3n porque ya existe en otro espacio de trabajo. Si desea instalar la aplicaci\00F3n, realice lo siguiente:</p>'),
