wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(186970910581820894.4001)
,p_name=>'F4000_P188_CACHING'
,p_item_sequence=>90
,p_item_plug_id=>wwv_flow_imp.id(186970606141820893.4001)
,p_use_cache_before_default=>'NO'
,p_item_default=>'BY_USER_BY_SESSION'
,p_prompt=>unistr('Validar Esquema de Autorizaci\00F3n:')
,p_source=>'CACHING'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_RADIOGROUP'
,p_named_lov=>'AUTH_SCHEME_CACHING'
,p_lov=>'.'||wwv_flow_imp.id(84860700520374929)||'.'
,p_field_template=>wwv_flow_imp.id(561547836135222071.4001)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_escape_on_http_output=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('Los esquemas de autorizaci\00F3n se eval\00FAan en el primer uso de una sesi\00F3n.'),
unistr('El atributo <em>Validar Esquema de Autorizaci\00F3n</em> controla si las utilizaciones futuras generan nuevas evaluaciones y cu\00E1ndo se puede tomar en su lugar un resultado memorizado.'),
'La siguiente lista describe las opciones disponibles:',
'</p>',
'<ul>',
unistr('<li><strong>Una Vez por Sesi\00F3n:</strong> evaluar solo una vez y utilizar siempre el resultado memorizado posteriormente.</li>'),
unistr('<li><strong>Una Vez por Vista de P\00E1gina:</strong> evaluar una vez para cada solicitud que se procesa. Utilizar el resultado memorizado si se hace referencia al esquema de autorizaci\00F3n en m\00E1s de un componente en la p\00E1gina.</li>'),
unistr('<li><strong>Una Vez por Componente:</strong> evaluar una vez para cada componente que hace referencia al esquema de autorizaci\00F3n, pero guardar el resultado en la sesi\00F3n. Las dem\00E1s solicitudes para presentar o procesar el esquema utilizan el resultado')
||' memorizado.</li>',
unistr('<li><strong>Siempre (Sin Almacenamiento en Cach\00E9):</strong> el esquema de autorizaci\00F3n se evaluar\00E1 siempre.</li>'),
'</ul>',
'<p>',
unistr('El valor por defecto <em>Una Vez por Sesi\00F3n</em> es el m\00E1s eficiente.'),
unistr('Debe seleccionar otro valor si la comprobaci\00F3n de autorizaci\00F3n depende del cambio de estado de la sesi\00F3n u otros factores que no son consistentes en una sesi\00F3n completa.'),
unistr('Las opciones <em>Una Vez por Componente</em> y <em>Siempre (Sin Almacenamiento en Cach\00E9)</em> proporcionan informaci\00F3n adicional sobre el componente que se protege mediante el esquema de autorizaci\00F3n.'),
unistr('En los plugins de autorizaci\00F3n, puede utilizar los atributos <em>component.type</em>, <em>component.id</em> y <em>component.name</em> del par\00E1metro <em>t_authorization</em>.'),
unistr('Para los tipos de esquema <em>Consulta SQL Exists</em> y <em>Funci\00F3n PL/SQL</em> incorporados, hay disponibles variables de enlace <em>:APP_COMPONENT_TYPE</em>, <em>:APP_COMPONENT_ID</em> y <em>:APP_COMPONENT_NAME</em> equivalentes.'),
'</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'number_of_columns', '1',
  'page_action_on_selection', 'NONE')).to_clob
);
