'with central_theme as (',
'    select wwv_flow_theme_manager.get_central_application_id( :FB_FLOW_ID, :P218_THEME ) as application_id,',
'           wwv_flow_theme_manager.get_central_theme_id( :FB_FLOW_ID, :P218_THEME )       as theme_id,',
'           wwv_flow_theme_manager.get_central_workspace_id( :FB_FLOW_ID, :P218_THEME )   as workspace_id',
'      from sys.dual',
')',
'',
'select 1',
'  from wwv_flow_button_templates bt,',
'       central_theme ct',
' where ( bt.flow_id, bt.theme_id, bt.security_group_id ) in',
'       (',
'          ( :FB_FLOW_ID, :P218_THEME, :WORKSPACE_ID ),',
'          ( ct.application_id, ct.theme_id, ct.workspace_id )',
'       )',
'   and bt.template_name = :P218_NAME'))
