,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with central_theme as (',
'    select wwv_flow_theme_manager.get_central_application_id( :F4000_P219_COPY_FROM_FLOW_ID, :P413_COPY_FROM_THEME ) as application_id,',
'           wwv_flow_theme_manager.get_central_theme_id( :F4000_P219_COPY_FROM_FLOW_ID, :P413_COPY_FROM_THEME )       as theme_id,',
'           wwv_flow_theme_manager.get_central_workspace_id( :F4000_P219_COPY_FROM_FLOW_ID, :P413_COPY_FROM_THEME )   as workspace_id',
'      from sys.dual',
')',
'',
'select bt.id,',
'       case',
'           when bt.security_group_id in ( 11, 12 ) then m.theme_repository',
'           else to_char( bt.flow_id )',
'       end flow_id,',
'       bt.template_name from_name,',
'       wwv_flow_lang.system_message(''F4000.P158.COPY_OF'',bt.template_name) to_name,',
'       ''N'' Sub',
'  from wwv_flow_button_templates bt,',
'       ( select wwv_flow_lang_dev.builder_message( ''SUBSCRIBED_FROM.THEME_REPOSITORY'' ) theme_repository',
'           from sys.dual ) m,',
'       central_theme ct',
' where ( bt.flow_id, bt.theme_id, bt.security_group_id ) in',
'       (',
'        ( :F4000_P219_COPY_FROM_FLOW_ID, :P413_COPY_FROM_THEME, :WORKSPACE_ID ),',
'        ( ct.application_id, ct.theme_id, ct.workspace_id )',
