wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(142984030433945447.4001)
,p_name=>'P253_INSTALL_OPTION'
,p_item_sequence=>70
,p_item_plug_id=>wwv_flow_imp.id(47632929379498968.4001)
,p_use_cache_before_default=>'NO'
,p_item_default=>'CREATE'
,p_display_as=>'NATIVE_HIDDEN'
,p_display_when=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select 1 ',
'  from wwv_flow_themes ',
' where flow_id = :P253_NEW_FLOW_ID ',
'   and security_group_id = :WORKSPACE_ID',
'   and theme_id = :P253_ORIGINAL_THEME_ID ',
'   and :p253_original_theme_id != ( select nvl(theme_id,-1) from wwv_flows where id = :P253_NEW_FLOW_ID )'))
,p_display_when_type=>'EXISTS'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Al refrescar un tema, se actualizan el tema y la definici\00F3n de plantilla del tema actual con la definici\00F3n del tema importado. Para que ocurra, es necesario que ambos temas sean compatibles y utilicen los mismos identificadores de tema y plantilla')
||'s.</p>',
'<p>Al crear un nuevo tema, se instala el tema importado junto con el tema actual, lo que permite cambiar del tema antiguo al nuevo y asignar manualmente las plantillas.</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'value_protected', 'Y')).to_clob
