wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(2346347639058255.4001)
,p_name=>'F4000_P258_ROW_TEMPLATE1'
,p_item_sequence=>140
,p_item_plug_id=>wwv_flow_imp.id(2346347660092590.4001)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Plantilla de Columna 1'
,p_source=>'ROW_TEMPLATE1'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'PLUGIN_COM.ORACLE.APEX.CODE_EDITOR'
,p_cSize=>90
,p_cMaxlength=>32767
,p_cHeight=>4
,p_tag_attributes=>'onchange="htmldb_item_change(this)"'
,p_field_template=>wwv_flow_imp.id(561549638722251517.4001)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<div class="htmldbInfoBodyP">Define la plantilla de columna. Aqu\00ED puede utilizar las siguientes cadenas de sustituci\00F3n:'),
'<ul class="noIndent">',
unistr('<li>#COLUMN_VALUE#: se sustituir\00E1 por el valor de una columna</li>'),
unistr('<li>#ALIGNMENT#: especificada por el usuario, determina la alineaci\00F3n de una columna</li>'),
unistr('<li>#COLNUM#: n\00FAmero de columna actual</li>'),
'<li>#COLUMN_HEADER#: cabecera de columna</li>',
unistr('<li>#COLCOUNT#: n\00FAmero de columnas</li>'),
unistr('<li>#ROWNUM#: n\00FAmero de fila actual</li>'),
'<li>#ACCESSIBLE_HEADERS#: agrega las cabeceras de fila y columna para la celda</li>',
'</ul>',
'</div>',
unistr('<div class="htmldbInfoBodyP">Un ejemplo t\00EDpico ser\00EDa:</div>'),
'<pre>&lt;td #ALIGNMENT#&gt;#COLUMN_VALUE#&lt;/td&gt;</pre>',
'',
'<div class="instructiontext">Puede definir hasta cuatro plantillas de columna, las cuales pueden ser condicionales. Por ejemplo, puede tener colores de fondo diferentes para las filas pares y las impares, o bien resaltar las filas que cumplan una con'
||unistr('dici\00F3n definida PL/SQL.</div>')))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'HTMLMIXED',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
);
