wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(121204124843870496.4001)
,p_name=>'Compatibilidad de Temas'
,p_template=>wwv_flow_imp.id(174794400314076650.4001)
,p_display_sequence=>30
,p_region_template_options=>'#DEFAULT#:a-Region--noTopBorder:a-Region--noPadding:a-Region--hideHeader'
,p_component_template_options=>'#DEFAULT#:a-Report--stretch'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with central_theme as (',
'    select wwv_flow_theme_manager.get_central_application_id( :FB_FLOW_ID, :P179_NEW_THEME ) as application_id,',
'           wwv_flow_theme_manager.get_central_theme_id( :FB_FLOW_ID, :P179_NEW_THEME )       as theme_id,',
'           wwv_flow_theme_manager.get_central_workspace_id( :FB_FLOW_ID, :P179_NEW_THEME )   as workspace_id',
'      from sys.dual )',
'',
'select   decode(temp_type,',
'  ''PAGE'',wwv_flow_lang.system_message_lit(''F4000.PAGE''),',
'  ''REGION'',wwv_flow_lang.system_message_lit(''F4000.REGION''),',
'  ''LABEL'',wwv_flow_lang.system_message_lit(''LABEL''),',
'  ''LIST'',wwv_flow_lang.system_message_lit(''F4000.LIST_INITCAP''),',
'  ''POPUP_LOV'',wwv_flow_lang.system_message_lit(''F4000.P371.POPUP_LOV''),',
'  ''CALENDAR'',wwv_flow_lang.system_message_lit(''LEGACY_CALENDAR''),',
'  ''MENU'',wwv_flow_lang.system_message_lit(''F4000.MENU''),',
'  ''BUTTON'',wwv_flow_lang.system_message_lit(''F4000.BUTTON''),',
'  ''REPORT'',wwv_flow_lang.system_message_lit(''REPORT''),',
'  ''POPUP_LOV'',wwv_flow_lang.system_message_lit(''F4000.P371.POPUP_LOV''),',
'  ''trans-''||temp_type) temp_type, ',
'       theme_class_id ,',
'       from_template, ',
'       case',
'         when to_counter  > 1 then',
'             htmldb_item.hidden(1,id)||',
'             htmldb_item.hidden(2,temp_type)||',
'             htmldb_item.select_list_from_query(',
'                 /*p_idx        =>*/ 3,',
'                 /*p_value      =>*/ wwv_flow_templates_util.get_default_template_id(',
'                                         p_flow_id       => :FB_FLOW_ID,',
'                                         p_theme_id      => :P179_NEW_THEME,',
'                                         p_template_type => temp_type ),',
'                 /*p_query      =>*/ ''with central_theme as (',
'                                          select wwv_flow_theme_manager.get_central_application_id( :FB_FLOW_ID, :P179_NEW_THEME ) as application_id,',
'                                                 wwv_flow_theme_manager.get_central_theme_id( :FB_FLOW_ID, :P179_NEW_THEME )       as theme_id,',
'                                                 wwv_flow_theme_manager.get_central_workspace_id( :FB_FLOW_ID, :P179_NEW_THEME )   as workspace_id',
'                                            from sys.dual )',
'                                      select ta.name,',
'                                             ta.id',
'                                        from wwv_flow_templates_all ta,',
'                                             central_theme ct',
'                                       where ( ta.flow_id, ta.theme_id, ta.security_group_id ) in',
'                                             (',
'                                                ( :FB_FLOW_ID, :P179_NEW_THEME, :WORKSPACE_ID ),',
'                                                ( ct.application_id, ct.theme_id, ct.workspace_id )',
'                                             )',
'                                         and (:P179_MATCHING_TEMPLATES_ONLY = ''''N''''',
'                                              or ta.theme_class_id = '' || u.theme_class_id || '')'' ||',
'                                       '' and ta.temp_type = '''''' || u.temp_type || '''''''',',
'                 /*p_attributes =>*/ ''title="'' || wwv_flow_lang.system_message( ''F4000.P622.TO_TEMPLATE'' ) || ''"'',',
'                 /*p_show_null  =>*/ ''NO'',',
'                 /*p_null_value =>*/ ''%null%'',',
'                 /*p_null_text  =>*/ ''%'',',
'                 /*p_item_id    =>*/ null,',
'                 /*p_item_label =>*/ null,',
'                 /*p_show_extra =>*/ ''NO'' )',
'         when to_counter = 1 then',
'             htmldb_item.hidden(1,id)||',
'             htmldb_item.hidden(2,temp_type)||',
'             htmldb_item.select_list_from_query(',
'                 /*p_idx        =>*/ 3,',
'                 /*p_value      =>*/ (select ta.id',
'                                        from wwv_flow_templates_all ta,',
'                                             central_theme ct',
'                                       where ( ta.flow_id, ta.theme_id, ta.security_group_id ) in',
'                                             (',
'                                                ( :FB_FLOW_ID, :P179_NEW_THEME, :WORKSPACE_ID ),',
'                                                ( ct.application_id, ct.theme_id, ct.workspace_id )',
'                                             )',
'                                         and ta.theme_class_id = u.theme_class_id',
'                                         and ta.temp_type      = u.temp_type',
'                                         and rownum         = 1 ),',
'                 /*p_query      =>*/ ''with central_theme as (',
'                                          select wwv_flow_theme_manager.get_central_application_id( :FB_FLOW_ID, :P179_NEW_THEME ) as application_id,',
'                                                 wwv_flow_theme_manager.get_central_theme_id( :FB_FLOW_ID, :P179_NEW_THEME )       as theme_id,',
'                                                 wwv_flow_theme_manager.get_central_workspace_id( :FB_FLOW_ID, :P179_NEW_THEME )   as workspace_id',
'                                            from sys.dual )',
'                                      select ta.name,',
'                                             ta.id',
'                                        from wwv_flow_templates_all ta,',
'                                             central_theme ct',
'                                       where ( ta.flow_id, ta.theme_id, ta.security_group_id ) in',
'                                             (',
'                                                ( :FB_FLOW_ID, :P179_NEW_THEME, :WORKSPACE_ID ),',
'                                                ( ct.application_id, ct.theme_id, ct.workspace_id )',
'                                             )',
'                                         and ( :P179_MATCHING_TEMPLATES_ONLY=''''N''''',
'                                               or ta.theme_class_id = '' || u.theme_class_id || '')'' ||',
'                                       '' and ta.temp_type = '''''' || u.temp_type || '''''''',',
'                 /*p_attributes =>*/ ''title="'' || wwv_flow_lang.system_message( ''F4000.P622.TO_TEMPLATE'' ) || ''"'',',
'                 /*p_show_null  =>*/ ''NO'',',
'                 /*p_null_value =>*/ ''%null%'',',
'                 /*p_null_text  =>*/ ''%'',',
'                 /*p_item_id    =>*/ null,',
'                 /*p_item_label =>*/ null,',
'                 /*p_show_extra =>*/ ''NO'' )',
'         when to_counter = 0 then',
'             htmldb_item.hidden(1,id)||',
'             htmldb_item.hidden(2,temp_type)||',
'             HTMLDB_ITEM.SELECT_LIST_FROM_QUERY(',
'                 /*p_idx        =>*/ 3,',
'                 /*p_value      =>*/ wwv_flow_templates_util.get_default_template_id(',
'                                         p_flow_id       => :FB_FLOW_ID,',
'                                         p_theme_id      => :P179_NEW_THEME,',
'                                         p_template_type => temp_type',
'                                     ),',
'                 /*p_query      =>*/ ''with central_theme as (',
'                                          select wwv_flow_theme_manager.get_central_application_id( :FB_FLOW_ID, :P179_NEW_THEME ) as application_id,',
'                                                 wwv_flow_theme_manager.get_central_theme_id( :FB_FLOW_ID, :P179_NEW_THEME )       as theme_id,',
'                                                 wwv_flow_theme_manager.get_central_workspace_id( :FB_FLOW_ID, :P179_NEW_THEME )   as workspace_id',
'                                            from sys.dual )',
'                                      select ta.name,',
'                                             ta.id',
'                                        from wwv_flow_templates_all ta,',
'                                             central_theme ct',
'                                       where ( ta.flow_id, ta.theme_id, ta.security_group_id ) in',
'                                             (',
'                                                ( :FB_FLOW_ID, :P179_NEW_THEME, :WORKSPACE_ID ),',
'                                                ( ct.application_id, ct.theme_id, ct.workspace_id )',
'                                             )',
'                                         and ta.temp_type = '''''' || u.temp_type || '''''''',',
'                 /*p_attributes =>*/ ''title="'' || wwv_flow_lang.system_message( ''F4000.P622.TO_TEMPLATE'' ) || ''"'',',
'                 /*p_show_null  =>*/ ''NO'',',
'                 /*p_null_value =>*/ ''%null%'',',
'                 /*p_null_text  =>*/ ''%'',',
'                 /*p_item_id    =>*/ null,',
'                 /*p_item_label =>*/ null,',
'                 /*p_show_extra =>*/ ''NO'' )',
'       end lov, ',
'       CASE',
'         when to_counter > 1 then',
'             wwv_flow_lang.system_message_lit(''WARNING_MULTIPLE_MATCHES'')',
'         when to_counter = 1 then',
'           ''<span class="a-Icon icon-check"></span><span class="u-VisuallyHidden">''||wwv_flow_lang.system_message(''THEME.COMPATIBLE'')||''</span>''',
'         when to_counter = 0 then',
'             wwv_flow_lang.system_message_lit(''WARNING_MISSING_CLASS'')',
'       end status',
' from ',
'( select distinct u.id,',
'                  u.temp_type,',
'                  u.theme_class_id ,',
'                  u.name from_template,',
'                  ( select count(*) xx',
'                      from wwv_flow_templates_all ta,',
'                           central_theme ct',
'                     where ( ta.flow_id, ta.theme_id, ta.security_group_id ) in',
'                           (',
'                            ( :FB_FLOW_ID, :P179_NEW_THEME, :WORKSPACE_ID ),',
'                            ( ct.application_id, ct.theme_id, ct.workspace_id )',
'                           )',
'                       and ta.theme_class_id = u.theme_class_id',
'                       and ta.temp_type = u.TEMP_TYPE ) to_counter',
'    from wwv_flow_templates_used u',
'   where u.flow_id  = :FB_FLOW_ID',
'     and u.theme_id = :P179_OLD_THEME',
') u'))
,p_ajax_enabled=>'Y'
,p_fixed_header=>'NONE'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(123728124628276646.4001)
