||unistr('ace necesario que &PRODUCT_NAME. determine la preferencia de idioma adecuada en cada conexi\00F3n del usuario. </li>'),
unistr('<li><strong>Sesi\00F3n</strong>: determina el idioma de la aplicaci\00F3n traducida a partir del valor de sesi\00F3n. El idioma de sesi\00F3n de &PRODUCT_NAME. se puede definir mediante el procedimiento <code>APEX_UTIL.SET_SESSION_LANG</code> o con el par\00E1metro P_LA')
||'NG del procedimiento <code>F</code> en la URL.</li>',
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
