wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(7010248774227202.4001)
,p_event_id=>wwv_flow_imp.id(7010180680227201.4001)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'Y'
,p_name=>'Show aspect ratio (if needed)'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'const getAspectRatio = (image) => {',
'    return (image.naturalWidth / image.naturalHeight).toFixed(2);',
'}; ',
'',
'setTimeout(() => {',
'    const images = $(".a-PWAScreenshot-preview").get();',
'    const ratios = images.map(image => getAspectRatio(image));',
'    const allEqual = ratios.every(v => v === ratios[0]);',
'    if (!allEqual) {',
'        $(apex.region("ScreenshotsRatio")?.element).show();',
'        images.forEach((image) => {',
'            let ratioEl = $(image).closest("tr").find(".a-PWAScreenshot-preview--ratio");',
'            ratioEl.html(`<span class="a-Alert-icon a-Icon icon-warning"></span> <span class="">${image.naturalWidth}x${image.naturalHeight} (${getAspectRatio(image)})</span>`)',
'        });',
'    } else {',
'        $(apex.region("ScreenshotsRatio")?.element).hide();',
'        $(".a-PWAScreenshot-preview--ratio").html("");',
'    }',
'}, 1000);'))
);
