wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1875072844167005.4001)
,p_name=>'P509_AUTH_CONFIG_PROCEDURE'
,p_item_sequence=>110
,p_item_plug_id=>wwv_flow_imp.id(107178726415706930.4001)
,p_use_cache_before_default=>'NO'
,p_prompt=>unistr('Procedimiento de configuraci\00F3n')
,p_source=>'AUTH_CONFIG_PROCEDURE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>32
,p_cMaxlength=>255
,p_field_template=>wwv_flow_imp.id(561547836135222071.4001)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Introduzca el nombre de un procedimiento que configure la autenticaci\00F3n en el tiempo de ejecuci\00F3n.'),
unistr('El c\00F3digo siguiente es para una aplicaci\00F3n que implementa multi-arrendamiento y soporta'),
unistr('diferentes variaciones de <em>inicio de sesi\00F3n en medios sociales</em> para los inquilinos.'),
unistr('Utiliza el nombre de dominio en la URL para recuperar datos de configuraci\00F3n (Las URL son, por ejemplo: '),
'https://cust-01.example.com, https://cust-02.example.com, ...):',
'</p><pre><code>',
'procedure my_auth_config (',
'    p_conf in out nocopy apex_authentication.t_configuration )',
'is',
'    l_host varchar2(32767) := sys.owa_util.get_cgi_env(''HTTP_HOST'');',
'begin',
'    for i in ( select discovery_url,',
'                      auth_scheme_name,',
'                      credential,',
'                      tenant_id',
'                 from customer_tenants',
'                where hostname = l_host )',
'    loop',
'        p_conf.authentication_name := i.auth_scheme_name;',
'        p_conf.substitutions := apex_t_varchar2 (',
'                                    ''DISCOVERY_URL''       , i.discovery_url,',
'                                    ''CREDENTIAL_STATIC_ID'', i.credential );',
'        p_conf.tenant_id := i.tenant_id;',
'    end loop;',
'end my_auth_config;',
'</code></pre><p>',
unistr('El procedimiento puede cambiar tres atributos del par\00E1metro de entrada/salida <code>p_conf</code>,'),
'de los cuales todos son opcionales:',
'<ul>',
'    <li><code>authentication_name</code>:',
unistr('    Asigne el nombre de un esquema de autenticaci\00F3n de su aplicaci\00F3n,'),
unistr('    que se usar\00E1 en lugar del esquema por defecto.'),
unistr('    Tenga en cuenta que la opci\00F3n <em>Cambiar en sesi\00F3n</em> debe estar activada para dicho esquema.'),
'    </li><li><code>substitutions</code>:',
'    Asigne pares de nombre/valor usando <code>apex_t_varchar2</code>.',
'    &PRODUCT_NAME. sustituye cada <code>#NAME#</code> en los atributos de esquema de',
unistr('    autenticaci\00F3n por el valor asociado.'),
unistr('    El esquema <em>Inicio de sesi\00F3n en medios sociales</em> usa <code>CREDENTIAL_STATIC_ID</code>'),
unistr('    para usar el almac\00E9n de credenciales correspondiente en lugar del que fuera configurado '),
'    en el esquema.',
'    </li><li><code>tenant_id</code>:',
unistr('    Defina este inquilino en la sesi\00F3n (vea <code>apex_session.set_tenant_id</code>).'),
'    </li>',
'</ul>',
'</p><p>',
unistr('En aplicaciones con un procedimiento de configuraci\00F3n de autenticaci\00F3n,'),
unistr('el esquema de autenticaci\00F3n no se puede cambiar mediante la URL (p. ej., <code>f?p=100:1:1234:APEX_AUTHENTICATION=myauth</code>).'),
'</p><p>',
unistr('El procedimiento de configuraci\00F3n de autenticaci\00F3n se ejecuta al menos una vez por sesi\00F3n, en la primera solicitud.    '),
'Sin embargo, es posible que &PRODUCT_NAME. necesite realizar llamada al mismo en otras ocasiones.',
'En estos casos, debe definir los mismos valores en cada llamada.',
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'TEXT',
  'trim_spaces', 'BOTH')).to_clob
);
