wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(3017034838375337.4001)
,p_name=>'P509_MLE_ENV'
,p_item_sequence=>20
,p_item_plug_id=>wwv_flow_imp.id(107179319972706932.4001)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Entorno del MLE'
,p_source=>'MLE_ENVIRONMENT'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select object_name d,',
'       object_name r',
'  from (',
'         select case when o.owner != :P509_OWNER then o.owner || ''.'' end || object_name as object_name',
'          from ( select o.owner, o.owner as grantee, o.object_type, o.object_name',
'                   from sys.dba_objects o',
'                  union',
'                 select p.owner, p.grantee, p.type, p.table_name',
'                   from sys.dba_tab_privs p ) o',
'         where o.object_type = ''MLE ENVIRONMENT''',
'           and o.grantee in ( :P509_OWNER, ''PUBLIC'' )',
'       )',
'order by object_name'))
,p_lov_display_null=>'YES'
