wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(107203001185706981.4001)
,p_name=>'P509_PAGE_PROTECTION_ENABLED'
,p_item_sequence=>200
,p_item_plug_id=>wwv_flow_imp.id(107273213161009008.4001)
,p_use_cache_before_default=>'NO'
,p_item_default=>'N'
,p_prompt=>unistr('Protecci\00F3n de Estado de la Sesi\00F3n')
,p_source=>'PAGE_PROTECTION_ENABLED_Y_N'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'ENABLED_DISABLED_RETURNS_Y_OR_N'
,p_lov=>'.'||wwv_flow_imp.id(91439803955181562)||'.'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071.4001)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_escape_on_http_input=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<div class="htmldbInfoBodyP">Al seleccionar <strong>Activado</strong>, esta funci\00F3n utiliza el atributo de p\00E1gina Protecci\00F3n de Acceso a P\00E1gina y los atributos de elemento Protecci\00F3n de Estado de la Sesi\00F3n junto con los totales de control colocados e')
||unistr('n las direcciones URL f?p=. Al activar esta funci\00F3n se impide la manipulaci\00F3n de direcciones URL y el acceso no autorizado al estado de la sesi\00F3n, as\00ED como su modificaci\00F3n.</div>'),
'',
unistr('<div class="htmldbInfoBodyP">Al seleccionar <strong>Desactivado</strong>, el motor de &PRODUCT_NAME. no tendr\00E1 en cuenta los atributos de p\00E1gina Protecci\00F3n de Acceso a P\00E1gina o los atributos de elemento Protecci\00F3n de Estado de la Sesi\00F3n durante la ej')
||unistr('ecuci\00F3n de la aplicaci\00F3n y no incluir\00E1 totales de control en la secci\00F3n f?p=  de las direcciones URL.</div>'),
'',
unistr('<div class="htmldbInfoBodyP">Si este atributo se define en <strong>Activado</strong>, al cambiarlo a <strong>Desactivado</strong>, se desactivar\00E1 la Protecci\00F3n de Estado de la Sesi\00F3n, pero se mantendr\00E1 el valor de todos los atributos de p\00E1gina Protec')
||unistr('ci\00F3n de Acceso a P\00E1gina y todos los atributos de elemento Protecci\00F3n de Estado de la Sesi\00F3n.'),
'',
unistr('<div class="htmldbInfoBodyP">Si el atributo se define en <strong>Desactivado</strong>, al cambiarlo a <strong>Activado</strong>, se activar\00E1 la Protecci\00F3n de Estado de la Sesi\00F3n y se mantendr\00E1n todos los atributos de p\00E1gina Protecci\00F3n de Acceso a P\00E1g')
||unistr('ina y todos los atributos de elemento Protecci\00F3n de Estado de la Sesi\00F3n, que se respetar\00E1n durante la ejecuci\00F3n de la aplicaci\00F3n.</div>'),
'',
unistr('<div class="htmldbInfoBodyP">Una excepci\00F3n a la regla general sobre los atributos de elemento Protecci\00F3n de Estado de la Sesi\00F3n que tienen s\00F3lo efecto cuando la Protecci\00F3n de Estado de la Sesi\00F3n es <strong>Activado</strong>, es que si un atributo de ')
||unistr('elemento se define en <strong>Protegido</strong>, dicho estado siempre est\00E1 activo. Es decir, los elementos protegidos no se pueden definir a partir de la direcci\00F3n URL, independientemente del valor Activado o Desactivado de Protecci\00F3n de Estado de l')
||unistr('a Sesi\00F3n.</div>')))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
