,p_use_cache_before_default=>'NO'
,p_item_default=>'N'
,p_prompt=>'Volver a Unir Sesiones'
,p_source=>'REJOIN_EXISTING_SESSIONS'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'REJOIN_EXISTING_SESSIONS'
,p_lov=>'.'||wwv_flow_imp.id(492680965578161495)||'.'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071.4001)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('Utilice este atributo para controlar si &PRODUCT_NAME. debe soportar URL de aplicaci\00F3n que no contenga ID de sesi\00F3n.'),
unistr('Cuando la opci\00F3n Volver a Entrar en Sesiones est\00E1 activada, &PRODUCT_NAME. intenta utilizar la cookie de sesi\00F3n para entrar en una sesi\00F3n existente'),
unistr('cuando una URL no contiene un ID de sesi\00F3n.'),
'</p>',
'<p>',
unistr('Un valor de nivel de instancia m\00E1s restrictivo sustituye este valor de nivel de p\00E1gina.'),
'</p>',
'<p>',
'    <strong>Nota:</strong>',
unistr('La activaci\00F3n de Volver a Entrar en Sesiones expone la aplicaci\00F3n a posibles incumplimientos de seguridad, ya que puede permitir a usuarios no autorizados tomar posesi\00F3n de las sesiones de usuario final existentes. Para obtener m\00E1s informaci\00F3n, consu')
||unistr('lte las secciones sobre c\00F3mo volver a entrar en sesiones en "Gesti\00F3n de seguridad de aplicaciones" en Application Builder User''s Guide.'),
'</p>',
'',
'<p>',
'Entre las opciones disponibles se incluyen:    ',
'</p>',
'<ul>',
unistr('    <li><strong>Valor por defecto de la aplicaci\00F3n</strong> - '),
unistr('    Se aplica el valor del nivel de aplicaci\00F3n.'),
'    </li>',
'    <li><strong>Desactivado</strong> - ',
unistr('    Si la URL no contiene un ID de sesi\00F3n, &PRODUCT_NAME. crea una nueva sesi\00F3n.'),
'    </li>',
unistr('    <li><strong>Activado para sesiones p\00FAblicas</strong> - '),
unistr('    Si la URL va a una p\00E1gina p\00FAblica y no contiene un ID de sesi\00F3n,'),
unistr('    &PRODUCT_NAME. intenta utilizar la cookie de sesi\00F3n existente establecida para dicha aplicaci\00F3n.'),
unistr('    Para aplicaciones con p\00E1ginas autenticadas y p\00FAblicas, un ID de sesi\00F3n se define tras la autenticaci\00F3n del usuario final.'),
unistr('    &PRODUCT_NAME. solo entra con la cookie cuando la sesi\00F3n no se ha autenticado todav\00EDa.'),
'    </li>',
'    <li><strong>Activado para todas las sesiones</strong> - ',
unistr('    Si la URL no contiene un ID de sesi\00F3n, &PRODUCT_NAME. intenta utilizar la cookie de sesi\00F3n existente establecida para dicha aplicaci\00F3n,'),
'    siempre que se cumplan las siguientes condiciones:',
'    <ul>',
'        <li>',
unistr('        Protecci\00F3n de estado de la sesi\00F3n est\00E1 activada para la aplicaci\00F3n y la URL incluye un total de control v\00E1lido.'),
unistr('        Para marcadores p\00FAblicos,'),
unistr('        la protecci\00F3n de nivel de elemento m\00E1s restrictiva debe ser <em>No restringido</em> o <em>Total de control necesario: Nivel de aplicaci\00F3n</em>.'),
'        </li>',
'        <li>',
unistr('        O la URL no contiene carga \00FAtil (un par\00E1metro de solicitud, borrado de cach\00E9 o pares de valores de datos).'),
'        </li>',
'    </ul>',
unistr('    Este valor tambi\00E9n requiere que Incluir en marcos se defina en Permitir del mismo origen o en Denegar para la aplicaci\00F3n.'),
'    </li>',
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
