,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071.4001)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('Con este atributo se define lo que &PRODUCT_NAME. env\00EDa en la cabecera de la respuesta HTTP <code>Referrer-Policy</code>.'),
unistr('Con <code>Referrer-Policy</code> se controla lo que el explorador env\00EDa a los servidores en las '),
'cabeceras de solicitudes <code>Referer</code> y <code>Origin</code>,',
unistr('cuando los usuarios hacen clic en los enlaces o en las p\00E1ginas Enviar.'),
unistr('Esta informaci\00F3n suele incluir la URL completa, incluidos los ID de sesi\00F3n de &PRODUCT_NAME.,'),
'que los terceros no deben ver.',
'En las aplicaciones nuevas se debe utilizar el valor <code>strict-origin</code>,',
unistr('a menos que existan requisitos espec\00EDficos en la compa\00F1\00EDa para usar otro valor.'),
'</p><p>',
unistr('Consulte la documentaci\00F3n de'),
'<a rel="noopener noreferrer" href="https://www.w3.org/TR/referrer-policy/" referrerpolicy="no-referrer" target="_blank">',
'sobre la cabecera Referrer-Policy y sus valores disponibles',
'</a>',
unistr('para obtener m\00E1s informaci\00F3n.'),
'</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
