,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p />',
unistr('Indica si la protecci\00F3n de estado de la sesi\00F3n est\00E1 activada o desactivada. Si est\00E1 activada, utiliza los atributos de p\00E1gina <i>Protecci\00F3n de Acceso a P\00E1gina</i> y los atributos de elemento <i>Protecci\00F3n de Estado de la Sesi\00F3n</i> junto con los tota')
||unistr('les de control colocados en las direcciones URL "f?p=". Esta funci\00F3n impide la manipulaci\00F3n de direcciones URL y el acceso no autorizado al estado de la sesi\00F3n, as\00ED como su modificaci\00F3n. '),
'<p />',
unistr('Si est\00E1 desactivada, los atributos de elemento y de p\00E1gina relacionadas con la protecci\00F3n de estado de la sesi\00F3n se ignoran y los totales de control no se incluyen en las direcciones URL "f?p=" generadas.')))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'based_on', 'LOV',
  'format', 'PLAIN',
  'send_on_page_submit', 'N',
  'show_line_breaks', 'N')).to_clob
);
end;
