,p_field_template=>wwv_flow_imp.id(561549638722251517.4001)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_escape_on_http_output=>'N'
,p_help_text=>unistr('Las opciones de creaci\00F3n de la aplicaci\00F3n se enumeran a continuaci\00F3n, junto con el valor actual de cada una de ellas. Active la casilla situada junto a una opci\00F3n de creaci\00F3n para permitir a un usuario que instala la aplicaci\00F3n cambiar el valor como ')
