,p_lov_display_extra=>'NO'
,p_escape_on_http_input=>'N'
,p_escape_on_http_output=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('La activaci\00F3n de la protecci\00F3n de estado de la sesi\00F3n es un proceso de dos pasos:'),
'<ol>',
unistr('<li>Activar la funci\00F3n</li>'),
unistr('<li>Configurar los atributos de seguridad de p\00E1gina y de elemento</li>'),
'</ol>',
unistr('Para Seleccionar Acci\00F3n, seleccione una de las siguientes opciones y haga clic en <strong>Siguiente</strong>:'),
'<ul>',
unistr('<li><strong>Desactivar</strong>: Desactiva la protecci\00F3n de estado de la sesi\00F3n. Tenga en cuenta que la desactivaci\00F3n de la protecci\00F3n de estado de la sesi\00F3n no afectar\00E1 a los atributos de seguridad de p\00E1gina y de elemento configurados anteriormente.'),
unistr('<li><strong>Activar</strong>: Activa la protecci\00F3n de estado de la sesi\00F3n. Si est\00E1 activada, utiliza los atributos de p\00E1gina <i>Protecci\00F3n de Acceso a P\00E1gina</i> y los atributos de elemento Protecci\00F3n de Estado de la Sesi\00F3n junto con los totales de c')
||unistr('ontrol colocados en las direcciones URL "f?p=" para impedir la manipulaci\00F3n de direcciones URL y el acceso no autorizado al estado de la sesi\00F3n, as\00ED como su modificaci\00F3n. '),
unistr('<li><strong>Configurar</strong>: Configure los atributos de seguridad de p\00E1gina y de elemento y apl\00EDquelos a todas las p\00E1ginas y elementos de la aplicaci\00F3n.'),
unistr('<p><strong>Nota:</strong> Tambi\00E9n puede ajustar manualmente los atributos de seguridad de p\00E1gina y de elemento. Seleccione <strong>Activar</strong>, vuelva a la p\00E1gina Protecci\00F3n de Estado de la Sesi\00F3n y haga clic en el icono adecuado.</li>'),
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'number_of_columns', '1',
  'page_action_on_selection', 'NONE')).to_clob
);
