wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(209196315059496725.4001)
,p_process_sequence=>10
,p_process_point=>'AFTER_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'determine page import company action'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_build_status wwv_flows.build_status%type;',
'begin',
'    begin',
'      select build_status ',
'        into l_build_status from wwv_flows ',
'       where id = :P598_NEW_FLOW_ID',
'         and security_group_id = :WORKSPACE_ID;',
'    exception when no_data_found then',
'        :P67_INSTALL := ''N'';',
'    end;',
'',
'    if l_build_status = ''RUN_ONLY'' then',
'      :P598_INSTALL := ''RUN_ONLY'';',
'    else',
'      :P598_INSTALL := ''Y'';',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>209196315059496725.4001
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(209196524386496728.4001)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'install components'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_security_group_id number  := wwv_flow_imp_parser.get_security_group_id(:p49_file_id);',
'    l_flow_id           number  := wwv_flow_imp_parser.get_flow_id(p_file_id => :p49_file_id);',
'    l_adjust_offset     boolean := :flow_security_group_id <> l_security_group_id ',
'                                   or :FB_FLOW_ID <> l_flow_id;',
'begin',
'    wwv_flow_imp_parser.parse(',
'        p_file_id          => :P598_FILE_ID,',
'        p_parse_as_schema  => :P598_PARSE_AS,',
'        p_install_as_flow  => :P598_NEW_FLOW_ID,',
'        p_original_flow_id => l_flow_id,',
'        p_adjust_offset    => l_adjust_offset',
'    );',
'',
'    -- get imported component id to redirect to the new component',
'    :FB_FLOW_ID := :P598_NEW_FLOW_ID;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>unistr('Error al instalar componentes de aplicaci\00F3n.')
,p_process_when=>'INSTALL:REPLACE'
,p_process_when_type=>'REQUEST_IN_CONDITION'
,p_process_success_message=>unistr('Componentes de aplicaci\00F3n instalados.')
,p_internal_uid=>209196524386496728.4001
);
end;
