'from wwv_flow_templates t,',
'  (select wwv_flow_lang.system_message(''YES'') y,',
'            wwv_flow_lang.system_message(''NO'') n',
'   from dual) m',
'where security_group_id = :flow_security_group_id and',
'    flow_id = :fb_flow_id',
'order by 1'))
,p_footer=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Una plantilla de p\00E1gina mostrar\00E1 <strong>separadores est\00E1ndar</strong> si su atributo <strong>Cuerpo de Plantilla</strong> incluye la cadena de sustituci\00F3n <strong>#TAB_CELLS#</strong>.</p>'),
