 p_id=>wwv_flow_imp.id(205852217711540402.4001)
,p_plug_name=>unistr('Componentes de Aplicaci\00F3n')
,p_region_name=>'APP_COMPONENTS'
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(646287526247383209.4001)
,p_plug_display_sequence=>110
,p_include_in_reg_disp_sel_yn=>'Y'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select',
'       case when sel.id is null then',
'           WWV_FLOW_ITEM.CHECKBOX(',
'               1,',
'               comps.id || '':'' || comps.type_name || '':'' || rawtohex(sys.utl_raw.cast_to_raw(comps.name)),',
'               '''',',
'               '''',',
'               '''',',
'               ''f01_'' || lpad(to_char(rownum), 4, ''0''),',
'               wwv_flow_lang.system_message(''COMPONENT_NAME_LABEL'', wwv_flow_escape.html(comps.name))',
'           )',
'           else '' ''',
'       end as id,',
'       comps.type_name,',
'       comps.name,',
'       wwv_flow_string.join( comps.used_on_pages, '','' ) used_on_pages,',
'       comps.last_updated_on last_updated_on,',
'       comps.last_updated_by',
'  from wwv_flow_appl_export_comps comps,',
'       ( select type_name,',
'                id',
'           from wwv_multi_component_export',
'          where flow_id = nvl(:FB_FLOW_ID, :P688_APPLICATION) ) sel',
' where (comps.application_id = nvl(:FB_FLOW_ID, :P688_APPLICATION) or comps.application_id is null)',
'   and comps.workspace_id    = :FLOW_SECURITY_GROUP_ID',
'   and comps.type_name       = sel.type_name (+)',
'   and comps.id              = sel.id        (+)'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P688_APPLICATION'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
