wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(228937206800547250.4001)
,p_plug_name=>unistr('Estado de Opci\00F3n de Creaci\00F3n')
,p_region_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(646287526247383209.4001)
,p_plug_display_sequence=>130
,p_include_in_reg_disp_sel_yn=>'Y'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select',
'       case when exp.component_id is null then',
'           WWV_FLOW_ITEM.CHECKBOX(',
'               1,',
'               p.id || '':BUILD_OPTION_STATUS:''||rawtohex(sys.utl_raw.cast_to_raw(p.patch_name)),',
'               '''',',
'               '''',',
'               '''',',
'               ''f01_'' ||',
'                   lpad(to_char(rownum), 4, ''0''),',
'               wwv_flow_lang.system_message(''BUILD_OPTION_LABEL'',',
'                   wwv_flow_escape.html(p.patch_name))',
'           )',
'           else '' ''',
'       end as id,',
'       p.patch_name as build_option,',
'       p.patch_status as build_option_status',
'  from wwv_flow_patches p,',
'       (',
'           select id as component_id',
'             from wwv_multi_component_export',
'            where type_name = ''BUILD_OPTION_STATUS''',
'              and flow_id = nvl(:FB_FLOW_ID, :P688_APPLICATION)',
'       ) exp',
'where p.id = exp.component_id (+)',
'  and p.security_group_id = :FLOW_SECURITY_GROUP_ID',
'  and p.flow_id = nvl(:FB_FLOW_ID, :P688_APPLICATION)',
'order by p.patch_name'))
,p_plug_source_type=>'NATIVE_IR'
,p_ajax_items_to_submit=>'P688_APPLICATION'
