'select p.builder_name                                         as template_name,',
'       p.id                                                   as template_id,',
'       pg.name                                                as page_name,',
'       r.plug_name                                            as region,',
'       r.page_id                                              as page,',
'       wwv_flow_lang.system_message(''F4000.REGION'')         as object_type,',
'       to_char(null)                                          as object_name',
'  from wwv_theme_template_components    p,',
'       wwv_flow_page_plugs           r,',
'       wwv_flow_steps                pg',
' where p.theme_id           is not null',
'   and r.flow_id            = p.flow_id',
'   and r.security_group_id  = p.security_group_id',
'   and r.plug_source_type   = p.used_name',
'   and pg.flow_id           = r.flow_id',
'   and pg.id                = r.page_id',
'   and pg.security_group_id = r.security_group_id',
'   and (    :P707_FIND                                  is null ',
'         or instr(upper(r.plug_name),upper(:P707_FIND)) > 0',
'         or instr(r.page_id,:P707_FIND)                 > 0 )',
'union all',
'select p.builder_name                                         as template_name,',
'       p.id                                                   as template_id,',
'       pg.name                                                as page_name,',
'       r.plug_name                                            as region,',
'       c.page_id                                              as page,',
'       wwv_flow_lang.system_message(''F4000.REPORT_COLUMN'')    as object_type,',
'       c.db_column_name                                       as object_name',
