wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(90472917919261593.4001)
,p_name=>'Referencias de plantilla de lista'
,p_template=>wwv_flow_imp.id(174794400314076650.4001)
,p_display_sequence=>50
,p_region_template_options=>'#DEFAULT#:a-Region--noTopBorder:a-Region--noPadding:a-Region--noBorder:a-Region--accessibleHeader'
,p_component_template_options=>'#DEFAULT#:a-Report--stretch'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select application_id, template_name, id, region_name, page_id, list_name, list_id, referenced_from',
'from ',
'(',
'select ',
'  l.flow_id application_id,',
'  l.list_template_name template_name,',
'  l.id,',
'  p.plug_name region_name,',
'  p.page_id page_id,',
'  null list_name,',
'  null list_id,',
'  m.m referenced_from',
'from ',
'  wwv_flow_list_templates l,',
'  wwv_flow_page_plugs p,',
' (select wwv_flow_lang.system_message(''REGIONS_LIST_TEMPLATE_OVERRIDE'') m from sys.dual) m',
' where l.id                =  :P707_TEMPLATE',
'   and l.security_group_id in ( :WORKSPACE_ID, 11, 12 )',
'   and p.list_template_id  =  l.id',
'   and p.flow_id           =  :FB_FLOW_ID',
'   and p.security_group_id =  :WORKSPACE_ID',
'   and :P707_TEMPLATE_TYPE =  ''LIST''',
') x',
'where',
'(',
':P707_FIND is null or ',
'instr(upper(region_name),upper(:P707_FIND)) > 0 or',
'instr(upper(list_name),upper(:P707_FIND)) > 0 or',
'instr(page_id,:P707_FIND) > 0',
')'))
,p_display_when_condition=>'P707_TEMPLATE_TYPE'
,p_display_when_cond2=>'LIST'
,p_display_condition_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
,p_header=>unistr('<div class="padding-md">Este informe muestra todas las listas que hacen referencia a la plantilla seleccionada, as\00ED como cualquier regi\00F3n de p\00E1gina que sustituye la plantilla de lista por defecto.</div>')
