wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(446121406081960368.4001)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Update Report Columns'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'   l_comma2     number;',
'   l_comma3     number;',
'   l_rc_type    varchar2(2);',
'   l_rc_id      number;',
'   l_column_id  number;',
'   l_region_id  number;',
'begin',
'   for i in 1..wwv_flow.g_f01.count loop',
'',
'      l_comma2    := instr(wwv_flow.g_f01(i),'','',1,2);',
'      l_comma3    := instr(wwv_flow.g_f01(i),'','',1,3);',
'      l_rc_type   := substr(wwv_flow.g_f01(i),1,2);',
'      l_rc_id     := substr(wwv_flow.g_f01(i),4,l_comma2-4);',
'      l_column_id := substr(wwv_flow.g_f01(i),l_comma2+1,l_comma3-l_comma2-1);',
'      l_region_id := substr(wwv_flow.g_f01(i),l_comma3+1);',
'',
'      if l_rc_type = ''CR'' and instr(:P922_INCLUDE_IN_UPDATE,''label'') > 0 then',
'         wwv_flow_hint.update_cr_ht_from_ad(',
'            p_application_id  => :FB_FLOW_ID,',
'            p_page_id         => :FB_FLOW_PAGE_ID,',
'            p_region_id       => l_region_id);',
'      end if;',
'',
'      if l_rc_type = ''CR'' then',
'         wwv_flow_hint.update_cr_from_ad(',
'            p_application_id  => :FB_FLOW_ID,',
'            p_page_id         => :FB_FLOW_PAGE_ID,',
'            p_region_id       => l_region_id,',
'            p_rc_id           => l_rc_id,',
'            p_column_id       => l_column_id,',
'            p_attr_to_include => :P922_INCLUDE_IN_UPDATE );',
'      elsif l_rc_type = ''IR'' then',
'         wwv_flow_hint.update_ir_from_ad(',
'            p_application_id  => :FB_FLOW_ID,',
'            p_rc_id           => l_rc_id,',
'            p_column_id       => l_column_id,',
'            p_attr_to_include => :P922_INCLUDE_IN_UPDATE );',
'      end if;',
'',
'   end loop;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'Fallo al actualizar las columnas del informe.'
,p_process_when_button_id=>wwv_flow_imp.id(446119503950960343.4001)
,p_process_success_message=>'Columnas de informe actualizadas.'
,p_internal_uid=>446121406081960368.4001
);
end;
