wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(4401248646857651.4001)
,p_process_sequence=>70
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Consolidate Item Values'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    procedure clear_web_source is',
'    begin',
'        :P1117_EXTERNAL_FILTER_EXPR := null;',
'        :P1117_WEB_SRC_FUNCTION     := null;',
'        :P1117_POST_PROC_TYPE       := null;',
'        :P1117_WEB_SRC_MODULE_ID    := null;',
'    end clear_web_source;',
'',
'    procedure clear_unused_query_params is',
'    begin',
'        if :P1117_QUERY_TYPE  = ''TABLE'' then',
'            :P1117_QUERY_SQL          := null;',
'            :P1117_QUERY_FUNC_LANG    := null;',
'            :P1117_OPTIMIZER_HINT     := null;',
'            :P1117_PQL_COLUMNS_CLAUSE := null;',
'            :P1117_PQL_MATCH_CLAUSE   := null;',
'',
'        elsif :P1117_QUERY_TYPE = ''GRAPH'' then',
'            :P1117_QUERY_SQL          := null;',
'            :P1117_QUERY_FUNC_LANG    := null;',
'            :P1117_OPTIMIZER_HINT     := null;',
'        else',
'            :P1117_QUERY_TABLE        := null;',
'            :P1117_QUERY_OWNER        := null;',
'            :P1117_QUERY_WHERE        := null;',
'            :P1117_QUERY_ORDER_BY     := null;',
'            :P1117_PQL_COLUMNS_CLAUSE := null;',
'            :P1117_PQL_MATCH_CLAUSE   := null;',
'',
'            if :P1117_QUERY_TYPE = ''SQL'' then ',
'                :P1117_QUERY_FUNC_LANG := null; ',
'            end if;',
'        end if;',
'',
'    end clear_unused_query_params;',
'',
'    procedure clear_remote_source is',
'    begin',
'        :P1117_REMOTE_SERVER_ID    := null;',
'    end clear_remote_source;',
'begin',
'    ',
'    if :P1117_LOCATION = ''LOCAL'' then',
'    ',
'        :P1117_QUERY_TYPE      := coalesce( :P1117_QUERY_TYPE, ''TABLE'' );',
'        :P1117_QUERY_SQL       := case :P1117_QUERY_TYPE',
'                                      when ''SQL''                     then :P1117_QUERY_SQL',
'                                      when ''FUNC_BODY_RETURNING_SQL'' then :P1117_QUERY_FUNC_BODY ',
'                                  end;',
'        :P1117_QUERY_FUNC_LANG := case ',
'                                      when :P1117_QUERY_TYPE = ''FUNC_BODY_RETURNING_SQL'' then :P1117_QUERY_FUNC_LANG ',
'                                  end;',
'',
'        if :P1117_QUERY_TYPE = ''GRAPH'' then',
'            :P1117_QUERY_TABLE     := :P1117_GRAPH_NAME;',
'            :P1117_QUERY_WHERE     := :P1117_PQL_WHERE_CLAUSE;',
'        end if;',
'',
'        clear_unused_query_params;',
'        clear_remote_source;',
'        clear_web_source;',
'',
'    elsif :P1117_LOCATION = ''REMOTE'' then',
'',
'        :P1117_REMOTE_SOURCE_TYPE := coalesce( :P1117_REMOTE_SOURCE_TYPE, ''TABLE'' );',
'        --',
'        :P1117_QUERY_TYPE          := :P1117_REMOTE_SOURCE_TYPE;',
'        :P1117_QUERY_ORDER_BY      := :P1117_REMOTE_ORDER_BY;',
'        ',
'        if :P1117_REMOTE_SOURCE_TYPE = ''TABLE'' then',
'            :P1117_QUERY_OWNER     := :P1117_REMOTE_TABLE_OWNER;',
'            :P1117_QUERY_TABLE     := :P1117_REMOTE_TABLE_NAME;',
'            :P1117_QUERY_WHERE     := :P1117_REMOTE_WHERE;',
'        else',
'            :P1117_QUERY_SQL       := case :P1117_REMOTE_SOURCE_TYPE',
'                                          when ''SQL''                     then :P1117_REMOTE_SQL',
'                                          when ''FUNC_BODY_RETURNING_SQL'' then :P1117_REMOTE_FUNC_BODY ',
'                                      end;',
'            :P1117_QUERY_FUNC_LANG := case ',
'                                          when :P1117_REMOTE_SOURCE_TYPE = ''FUNC_BODY_RETURNING_SQL'' then :P1117_REMOTE_FUNC_BODY_LANG ',
'                                      end;',
'        end if;',
'',
'        clear_unused_query_params;',
'        clear_web_source;',
'            ',
'    elsif :P1117_LOCATION = ''WEB_SOURCE'' then',
'        :P1117_ARRAY_COLUMN_ID        := :P1117_WEB_SRC_ARRAY_COL_ID;',
'        :P1117_SOURCE_POST_PROCESSING := nullif ( :P1117_POST_PROC_TYPE, ''NONE'' );',
'        :P1117_DOCUMENT_SOURCE_ID     := null;',
'',
'        if :P1117_OLD_WEB_SRC_MODULE_ID = :P1117_WEB_SRC_MODULE_ID then',
'            if :P1117_POST_PROC_TYPE = ''WHERE_ORDER_BY_CLAUSE'' then',
'                :P1117_QUERY_WHERE     := :P1117_POST_PROC_WHERE;',
'                :P1117_QUERY_ORDER_BY  := :P1117_POST_PROC_ORDER_BY;',
'                :P1117_QUERY_FUNC_LANG := null;',
'            elsif :P1117_POST_PROC_TYPE = ''SQL'' then',
'                :P1117_QUERY_SQL       := :P1117_POST_PROC_SQL;',
'                :P1117_QUERY_FUNC_LANG := null;',
'            elsif :P1117_POST_PROC_TYPE = ''FUNC_BODY_RETURNING_SQL'' then',
'                :P1117_QUERY_SQL       := :P1117_POST_PROC_FUNC_BODY;',
'                :P1117_QUERY_FUNC_LANG := :P1117_POST_PROC_FUNC_LANG;',
'            end if;',
'        else',
'             :P1117_POST_PROC_TYPE  := null;',
'             :P1117_QUERY_FUNC_LANG := null;',
'        end if;',
'        :P1117_QUERY_TYPE := null;',
'        clear_remote_source;',
'',
'    elsif :P1117_LOCATION = ''DUALITY_VIEW'' then',
'        :P1117_ARRAY_COLUMN_ID        := :P1117_DV_ARRAY_COL_ID;',
'        :P1117_SOURCE_POST_PROCESSING := nullif ( :P1117_DVPOST_TYPE, ''NONE'' );',
'        :P1117_DOCUMENT_SOURCE_ID     := :P1117_DUALITY_VIEW_ID;',
'        :P1117_WEB_SRC_MODULE_ID      := null;',
'',
'        if :P1117_DVPOST_TYPE = ''WHERE_ORDER_BY_CLAUSE'' then',
'            :P1117_QUERY_WHERE     := :P1117_DVPOST_WHERE;',
'            :P1117_QUERY_ORDER_BY  := :P1117_DVPOST_ORDER_BY;',
'            :P1117_QUERY_FUNC_LANG := null;',
'        elsif :P1117_DVPOST_TYPE = ''SQL'' then',
'            :P1117_QUERY_SQL       := :P1117_DVPOST_SQL;',
'            :P1117_QUERY_FUNC_LANG := null;',
'        elsif :P1117_DVPOST_TYPE = ''FUNC_BODY_RETURNING_SQL'' then',
'            :P1117_QUERY_SQL       := :P1117_DVPOST_FUNC_BODY;',
'            :P1117_QUERY_FUNC_LANG := :P1117_DVPOST_FUNC_LANG;',
'        end if;',
'        :P1117_QUERY_TYPE := null;',
'        clear_remote_source;        ',
'       ',
'    elsif :P1117_LOCATION = ''JSON_COLLECTION'' then',
'        :P1117_ARRAY_COLUMN_ID        := :P1117_JS_ARRAY_COL_ID;',
'        :P1117_SOURCE_POST_PROCESSING := nullif ( :P1117_JSPOST_TYPE, ''NONE'' );',
'        :P1117_DOCUMENT_SOURCE_ID     := :P1117_JSON_SOURCE_ID;',
'        :P1117_WEB_SRC_MODULE_ID      := null;',
'',
