'            :P1117_QUERY_WHERE     := :P1117_JSPOST_WHERE;',
'            :P1117_QUERY_ORDER_BY  := :P1117_JSPOST_ORDER_BY;',
'            :P1117_QUERY_FUNC_LANG := null;',
'        elsif :P1117_JSPOST_TYPE = ''SQL'' then',
'            :P1117_QUERY_SQL       := :P1117_JSPOST_SQL;',
'            :P1117_QUERY_FUNC_LANG := null;',
'        elsif :P1117_JSPOST_TYPE = ''FUNC_BODY_RETURNING_SQL'' then',
