'            :P1117_QUERY_FUNC_LANG := :P1117_JSPOST_FUNC_LANG;',
'        end if;',
'        :P1117_QUERY_TYPE := null;',
'        clear_remote_source;            ',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
