 p_id=>wwv_flow_imp.id(2011075214979408.4001)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Update Report Query'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'wwv_flow_report_query_dev.merge_collection_member(',
'    p_seq                       => :P1119_SEQ_ID,',
'    p_collection_name           => ''REPORT_QUERIES'',',
'    p_name                      => :P1119_NAME,',
'    p_location                  => :P1119_LOCATION,',
'    -- Local',
'    p_source_type               => :P1119_SOURCE_TYPE,',
'    p_table_owner               => :P1119_TABLE_OWNER,',
'    p_table_name                => :P1119_TABLE_NAME,',
'    p_sql_query                 => :P1119_SQL,',
'    p_function_body_language    => :P1119_FUNC_BODY_LANG,',
'    p_function_body             => :P1119_FUNC_BODY,',
'    p_graph_name                => :P1119_GRAPH_NAME,',
'    p_match_clause              => :P1119_PQL_MATCH_CLAUSE,',
'    p_columns_clause            => :P1119_PQL_COLUMNS_CLAUSE,',
'    -- REST data source',
'    p_document_source_id        => case :P1119_LOCATION',
'                                       when wwv_flow_exec_api.c_location_duality_view    then :P1119_DUALITY_VIEW_ID',
'                                       when wwv_flow_exec_api.c_location_json_source     then :P1119_JSON_SOURCE_ID',
'                                   end,',
'    p_web_src_module_id         => :P1119_WEB_SRC_MODULE_ID,',
'     ',
'    p_array_column_id           => case :P1119_LOCATION',
'                                       when wwv_flow_exec_api.c_location_duality_view    then :P1119_DV_ARRAY_COL_ID',
'                                       when wwv_flow_exec_api.c_location_json_source     then :P1119_JS_ARRAY_COL_ID',
'                                       when wwv_flow_exec_api.c_location_web_source      then :P1119_WEB_SRC_ARRAY_COL_ID',
'                                   end,',
