unistr('<p>Esta funci\00F3n ya existe en su aplicaci\00F3n. Si desea reinstalarla, primero debe eliminar las p\00E1ginas existentes, los componentes compartidos y la opci\00F3n de creaci\00F3n <strong>&P1317_BUILD_OPTION.</strong>. Para eliminar los componentes, siga estos paso')
||'s:',
'<ol>',
'  <li>Vaya a Componentes compartidos.</li>',
unistr('  <li>Vaya a L\00F3gica de aplicaci\00F3n , Opciones de creaci\00F3n.</li>'),
'  <li>Haga clic en <strong>&P1317_BUILD_OPTION.</strong>.</li>',
'  <li>Haga clic en <strong>Eliminar componentes</strong>.<br>',
unistr('    &nbsp;&nbsp;Marque la casilla de verificaci\00F3n <em>S\00ED: eliminar componentes</em>.<br>'),
'    &nbsp;&nbsp;Haga clic en <strong>Eliminar componentes</strong>.</li>',
unistr('  <li>En la opci\00F3n de creaci\00F3n Crear/editar, haga clic en <strong>Suprimir</strong>.<br>'),
unistr('    &nbsp;&nbsp;Haga clic en <strong>Suprimir opci\00F3n de creaci\00F3n</strong>.</li>'),
'</ol>',
'</p>',
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
