,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Los dise\00F1os de informe se pueden utilizar con una regi\00F3n o consulta de informe para representar los datos en versi\00F3n para impresora soportada por el servidor de impresi\00F3n. En funci\00F3n del tipo de servidor de impresi\00F3n remoto, un dise\00F1o de informe s')
||unistr('e puede dise\00F1ar mediante:'),
'<ul>',
'<li>el plugin Template Builder Word y se puede cargar como un archivo de tipo RTF o XSL-FO.</li>',
'<li> un documento de Word mediante el uso de una sintaxis de plantilla especial.</li>',
'</ul>',
'</p>  ',
unistr('<p>Tenga en cuenta que, para usar esta funci\00F3n, su aplicaci\00F3n debe utilizar un servidor de impresi\00F3n remoto.</p>'),
unistr('<p><a target="_blank" href="&SYSTEM_HELP_URL.">M\00E1s informaci\00F3n...</a></p>')))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
