wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(3367384134004646.4001)
,p_name=>'P1621_VALID_FOR_URLS'
,p_item_sequence=>230
,p_item_plug_id=>wwv_flow_imp.id(308592151420746764.4001)
,p_use_cache_before_default=>'NO'
,p_prompt=>unistr('V\00E1lido para URL')
,p_source=>'VALID_FOR_URLS'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXTAREA'
,p_cSize=>64
,p_cHeight=>5
,p_field_template=>wwv_flow_imp.id(561547836135222071.4001)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>&PRODUCT_NAME. comprobar\00E1 si la URL, para la que se va a utilizar la credencial en tiempo de ejecuci\00F3n, coincide con una de las URL de esta lista. Si la URL no coincide, &PRODUCT_NAME. emitir\00E1 un error.</p>'),
unistr('<p>Introduzca cada URL en una l\00EDnea nueva. El punto final de URL que se est\00E1 utilizando debe comenzar con una de las URL proporcionadas aqu\00ED.</p>'),
'<p>Por ejemplo:</p>',
'<pre>',
'https://www.example.com/restapis/my-protected-api',
'https://www.example.com/allowed-urls',
'</pre>',
'<p>Si la credencial se utiliza para llamar a un servicio REST en <strong>https://www.example.com/restapis/my-protected-api/restendpoint</strong> o <strong>https://www.example.com/allowed-urls/page1</strong>, se puede utilizar la credencial y la llama'
||unistr('da se producir\00E1 correctamente.</p>'),
unistr('<p>Si la credencial se utiliza para llamar a un servicio REST en <strong>https://localhost/myapis/test</strong> o <strong>https://dev.example.com/myapis/test</strong>, <em>no se puede</em> utilizar la credencial y &PRODUCT_NAME. emitir\00E1 un error.</p>'),
'<p>Ejemplo:</p>',
'<pre>',
'ldap://ldap.mycompany.com',
'ldaps://ldap.mycompany.com:389',
'</pre>',
'<p>ldap:// y ldaps:// son el "protocolo" que especifica las URL permitidas de un servidor LDAP.</p>',
'<p>Tenga en cuenta que, para cambiar este valor, es necesario volver a introducir el secreto del cliente.</p>'))
,p_inline_help_text=>'Tenga en cuenta que, para cambiar este valor, es necesario volver a introducir el secreto de cliente.'
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'auto_height', 'N',
  'character_counter', 'N',
  'resizable', 'Y',
  'trim_spaces', 'BOTH')).to_clob
);
wwv_flow_imp_page.create_page_item(
