,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Los permisos representados por el token de acceso en los t\00E9rminos de OAuth 2.0 se conocen como \00E1mbitos. El par\00E1metro de \00E1mbito permite a la aplicaci\00F3n expresar el \00E1mbito deseado de la solicitud de acceso. '),
'</p>',
'<p>',
unistr('    Si su servidor de autenticaci\00F3n requiere que se especifique un \00E1mbito para la solicitud de token de acceso, proporci\00F3nelo aqu\00ED. El token de acceso de OAuth2 se pedir\00E1 con el siguiente cuerpo de solicitud:'),
'<pre>',
unistr('grant_type=client_credentials&amp;scope=<strong>{\00E1mbito}</strong>'),
'</pre>',
'</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
