,p_item_plug_id=>wwv_flow_imp.id(308592151420746764.4001)
,p_use_cache_before_default=>'NO'
,p_item_default=>'BASIC'
,p_prompt=>unistr('Tipo de autenticaci\00F3n')
,p_source=>'AUTHENTICATION_TYPE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'CREDENTIALS_TYPE'
,p_lov=>'.'||wwv_flow_imp.id(154078822199034715)||'.'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071.4001)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Especifique el tipo de autenticaci\00F3n aqu\00ED. &PRODUCT_NAME. soporta los siguientes tipos de autenticaci\00F3n:</p>'),
'<ul>',
unistr('    <li><strong>Autenticaci\00F3n b\00E1sica</strong>: env\00EDa un nombre de usuario y una contrase\00F1a en forma de codificaci\00F3n Base64 como la cabecera de la solicitud de <strong>autorizaci\00F3n</strong>.'),
'    </li>',
unistr('    <li><strong>Credenciales de cliente de OAuth2</strong>: &PRODUCT_NAME. intercambia el ID de cliente y el secreto de cliente por un <strong>token de acceso</strong> utilizando una URL de servidor de token. A continuaci\00F3n, se utiliza el token de ac')
||unistr('ceso para realizar la solicitud real. Si el token de acceso caduca, &PRODUCT_NAME. solicitar\00E1 uno nuevo de forma transparente.</li>'),
unistr('    <li><strong>Autenticaci\00F3n nativa de OCI</strong>: &PRODUCT_NAME. firma solicitudes de la API de REST de <em>Oracle Cloud Infrastructure (OCI)</em>, como se describe en la <a rel="noopener noreferrer" href="https://docs.cloud.oracle.com/en-us/iaas')
||unistr('/Content/API/Concepts/signingrequests.htm">documentaci\00F3n de OCI</a>. Este tipo solo est\00E1 disponible en Oracle Database 18c y posteriores.</li>'),
'    <li><strong>Cabecera HTTP</strong>: la credencial se agrega a la solicitud de REST como una cabecera HTTP. El nombre de la credencial es el nombre de la cabecera HTTP, el secreto de la credencial es el valor de la cabecera HTTP. &PRODUCT_NAME. no'
||unistr(' agrega estos secretos al log de depuraci\00F3n ni a ning\00FAn otro log.</li>'),
unistr('    <li><strong>Cadena de consulta de URL</strong>: la credencial se agrega a la URL de la solicitud de REST como un par\00E1metro de <em>cadena de consulta</em> (por ejemplo: <strong>?name=value</strong>). Esta opci\00F3n puede ser \00FAtil para las claves de A')
||unistr('PI. &PRODUCT_NAME. no agrega estos secretos al log de depuraci\00F3n ni a ning\00FAn otro log. Sin embargo, el proxy web u otros servidores intermediarios registrar\00E1n estas credenciales en sus archivos de log.</li>'),
unistr('    <li><strong>Par de claves</strong>: una credencial de par de claves est\00E1 formada por una clave p\00FAblica, que se comparte abiertamente para cifrar datos, y una clave privada, que se mantiene secreta para cifrar datos. Juntas, garantizan el intercam')
||'bio de datos seguro.</li>',
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
