wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(537042170469394614.4001)
,p_validation_name=>'Delete only unused credentials'
,p_validation_sequence=>50
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select 1',
'  from wwv_credentials c',
' where c.security_group_id = :flow_security_group_id',
'   and c.id                = :p1621_id',
'   and exists(',
'           select 1',
'             from wwv_flow_web_credential_usage cu',
'            where cu.security_group_id = :flow_security_group_id',
'              and cu.credential_id     = c.id',
'       )'))
,p_validation_type=>'NOT_EXISTS'
,p_error_message=>unistr('La credencial est\00E1 en uso y no se puede suprimir. Revise el uso de la credencial en la p\00E1gina <strong>Utilizaci\00F3n</strong>.')
,p_when_button_pressed=>wwv_flow_imp.id(154599745454686565.4001)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
