,p_plug_display_column=>1
,p_plug_display_point=>'REGION_POSITION_03'
,p_plug_item_display_point=>'BELOW'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    La <strong>Definici\00F3n de carga de datos</strong> permite a los desarrolladores agregar la funcionalidad de <em>Carga de datos</em> '),
unistr('    a una aplicaci\00F3n de Oracle APEX.'),
'</p>',
'<p>',
unistr('    Una Definici\00F3n de carga de datos consiste en informaci\00F3n sobre d\00F3nde almacenar los datos '),
unistr('    cargados, as\00ED como los detalles sobre el m\00E9todo de carga, por ejemplo, si los datos se deben '),
'    <em>sumar</em> o si se deben <em>reemplazar</em> los datos existentes. ',
unistr('    Se puede hacer referencia a esta definici\00F3n en los procesos de la p\00E1gina de <strong>Carga de datos</strong>, '),
unistr('    as\00ED como en el paquete PL/SQL de <code>APEX_DATA_LOADING</code>.'),
'</p>',
'<p>',
unistr('    El <strong>Perfil de datos</strong> contiene informaci\00F3n sobre '),
'    la estructura de los datos cargados y las columnas adicionales',
unistr('     en funci\00F3n de la Expresi\00F3n SQL, la Consulta SQL, las Consultas o las Reglas de transformaci\00F3n.'),
'</p>',
'<p>',
unistr('    Despu\00E9s de crear la Definici\00F3n de carga de datos, el asistente le permite agregar una '),
unistr('    p\00E1gina de Carga de datos a su aplicaci\00F3n. La p\00E1gina creada se puede personalizar '),
unistr('    luego para ajustarse a las necesidades de su aplicaci\00F3n.'),
'</p>'))
,p_plug_query_headings_type=>'QUERY_COLUMNS'
,p_plug_query_show_nulls_as=>' - '
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
