 p_id=>wwv_flow_imp.id(242268510007871834.4001)
,p_plug_name=>'Operaciones'
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4001)
,p_plug_display_sequence=>10
,p_plug_display_point=>'REGION_POSITION_03'
,p_plug_item_display_point=>'BELOW'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr(' Una <strong>operaci\00F3n</strong> de origen de REST contiene la informaci\00F3n real sobre el manejador de servicio web externo. Para los servicios REST, se realiza una operaci\00F3n mediante la combinaci\00F3n de un patr\00F3n de URL y un verbo HTTP (GET, POST). Un o')
||'rigen de datos de REST puede contener varias operaciones.',
' </p>',
unistr(' <p>Las operaciones se pueden asignar a <strong>operaciones de base de datos</strong>, lo que permite que los componentes &PRODUCT_NAME. seleccionen la operaci\00F3n correcta. Los informes, informes interactivos o calendarios de CSS seleccionar\00E1n la oper')
||unistr('aci\00F3n asignada a la operaci\00F3n de base de datos <em>Recuperar filas</em>.</p>'),
'<p>',
unistr('La configuraci\00F3n definida en el nivel de m\00F3dulo se comparte en todas las operaciones del origen de datos de REST. La configuraci\00F3n en el nivel de operaci\00F3n se aplica solo a esta operaci\00F3n.</p>')))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(249280093175575814.4001)
,p_plug_name=>unistr('Origen de REST de JSON heredado de ORDS: tama\00F1o de p\00E1gina fijo desconocido')
,p_region_template_options=>'#DEFAULT#:a-Alert--danger:a-Alert--horizontal'
,p_plug_template=>wwv_flow_imp.id(770240542605907344.4001)
,p_plug_display_sequence=>20
,p_plug_source=>unistr('<p>Este origen de REST de ORDS utiliza la <em>sintaxis JSON heredada</em>; los datos se devuelven seg\00FAn la p\00E1gina, con un tama\00F1o de p\00E1gina fijo que determina el servidor. Para representar correctamente los componentes de &PRODUCT_NAME., &PRODUCT_NAME')
||unistr('. debe conocer el <em>tama\00F1o de p\00E1gina</em>. Navegue a la secci\00F3n <strong>Avanzado</strong> y defina el tama\00F1o de la p\00E1gina seg\00FAn corresponda. P\00F3ngase en contacto con el administrador del servicio REST para obtener esa informaci\00F3n.')
,p_plug_display_condition_type=>'EXISTS'
,p_plug_display_when_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
