wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(238756237141331835.4001)
,p_name=>'P1922_ALLOW_FETCH_ALL_ROWS'
,p_item_sequence=>50
,p_item_plug_id=>wwv_flow_imp.id(3469784605842432.4001)
,p_use_cache_before_default=>'NO'
,p_item_default=>'N'
,p_prompt=>unistr('Permitir recuperaci\00F3n de todas las filas')
,p_source=>'ALLOW_FETCH_ALL_ROWS'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_YES_NO'
,p_display_when=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select 1 from ',
'wwv_flow_web_src_modules',
'where id = :P1922_WEB_SRC_MODULE_ID and :P1922_DATABASE_OPERATION = ''FETCH_COLLECTION''',
''))
,p_display_when_type=>'EXISTS'
,p_field_template=>wwv_flow_imp.id(561547836135222071.4001)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Especifique si los componentes de &PRODUCT_NAME. pueden recuperar todas las filas y ejecutar varias solicitudes HTTP desde esta operaci\00F3n de origen de REST. '),
'</p>',
'<p>',
unistr('   Esto se aplica a or\00EDgenes de REST que devuelven sus datos en formato de p\00E1gina, como Oracle REST Data Services. Por ejemplo, un gr\00E1fico o la vista Agrupar por de Informes interactivos tienen que acceder a todas las filas para calcular los resultad')
||unistr('os correctos. Cuando el servicio REST devuelve los datos en formato de p\00E1gina, se requieren varias solicitudes HTTP al servicio REST. '),
'</p>',
'<p>',
unistr('    Si el origen de REST solo devuelve algunas p\00E1ginas, que se pueden recuperar en unos segundos, esto se acepta en la mayor\00EDa de casos de uso. Para estos servicios, defina el atributo en <strong>Activado</strong>. Por otro lado, cuando el servicio R')
||unistr('EST devuelve miles de filas en cientos de p\00E1ginas, recuperar todas las filas llevar\00EDa demasiado tiempo. Para estos servicios, defina este atributo en <strong>Desactivado</strong>.'),
'</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'use_defaults', 'Y')).to_clob
);
