,p_item_css_classes=>'apex-button-group'
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Elija el tipo de este par\00E1metro de origen de REST. Los valores disponibles son:'),
'</p>',
'<dl>',
unistr('<dt>Patr\00F3n de URL (IN)</dt>'),
unistr('<dd>Sustituya marcadores de posici\00F3n en la URL de punto final por valores de par\00E1metro.</dd>'),
'<dt>Cadena de consulta de URL (IN)</dt>',
unistr('<dd>Agregue el nombre y el valor de par\00E1metro a la URL como cadena de consulta.</dd>'),
'<dt>Cabecera HTTP (IN, OUT)</dt>',
unistr('<dd>Env\00EDe el par\00E1metro como cabecera de solicitud HTTP, o reciba de cabeceras de respuesta.</dd>'),
'<dt>Cookie (IN, OUT)</dt>',
unistr('<dd>Env\00EDe el par\00E1metro como cookie, o reciba de cookies de respuesta.</dd>'),
'<dt>Columna de perfil de datos (OUT)</dt>',
unistr('<dd>Analice la respuesta utilizando el perfil de datos y use el valor de columna. Este tipo solo est\00E1 soportado en el tipo de proceso <strong>Llamar a API</strong>.</dd>'),
'<dt>Cuerpo de solicitud o respuesta (IN, OUT)</dt>',
unistr('<dd>Realice sustituciones de marcador de posici\00F3n en el cuerpo de solicitud con el valor de par\00E1metro. Para par\00E1metros OUT, se recuperar\00E1 la <em>respuesta completa</em>.</dd>'),
unistr('<dt>C\00F3digo de estado (OUT)</dt>'),
unistr('<dd>Reciba el c\00F3digo de estado de HTTP.</dd>'),
'<dt>Frase de motivo (OUT)</dt>',
'<dd>Reciba la frase de motivo de HTTP.</dd>',
'</dl>',
'<p>',
unistr('    Ejemplo de par\00E1metros del tipo <strong>Patr\00F3n de URL</strong>'),
'</p>',
'<ul>',
'    <li>Punto final de URL: <code>http://{servidor}:{puerto}/ords/:schema/emp/:deptno</code></li>',
unistr('    <li>Par\00E1metro 1: <em>variable de patr\00F3n de URL</em> "deptno" con el valor "10"</li>'),
unistr('    <li>Par\00E1metro 2: <em>variable de patr\00F3n de URL</em> "schema" con el valor "scott"</li>'),
'</ul>',
'<p>',
'<br>',
unistr('    <em>No</em> agregue dos puntos (:) al nombre del par\00E1metro. &PRODUCT_NAME. formar\00E1 la URL para llamar de la siguiente manera:<br>'),
'    <code>http://{servidor}:{puerto}/ords/<strong>scott</strong>/emp/<strong>10</strong></code>',
'</p>',
'<p>',
unistr('    Ejemplo de par\00E1metros del tipo <strong>Cadena de solicitud</strong>'),
'</p>',
'<ul>',
'    <li>Punto final de URL: <code>http://{servidor}:{puerto}/ords/scott/emp</code></li>',
unistr('    <li>Par\00E1metro 1: <em>variable de cadena de solicitud</em> "query_filter" con el valor "KING"</li>'),
'</ul>',
'<p>',
'<br>',
unistr('    &PRODUCT_NAME. formar\00E1 la URL para llamar de la siguiente manera:<br>'),
'    <code>http://{servidor}:{puerto}/ords/scott/emp?<strong>query_filter</strong>=<strong>KING</strong></code>',
'</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
,p_show_quick_picks=>'Y'
,p_quick_pick_label_01=>unistr('Patr\00F3n de URL')
,p_quick_pick_value_01=>'URL_PATTERN'
