wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(473241645223135113.4001)
,p_name=>'P1923_IS_QUERY_PARAM'
,p_is_required=>true
,p_item_sequence=>30
,p_item_plug_id=>wwv_flow_imp.id(1718664379469919.4001)
,p_use_cache_before_default=>'NO'
,p_item_default=>'N'
,p_prompt=>unistr('Usar para b\00FAsqueda en filas')
,p_source=>'IS_QUERY_PARAM'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_YES_NO'
,p_display_when=>'P1923_WEB_SRC_OPERATION_ID'
,p_display_when_type=>'ITEM_IS_NULL'
,p_field_template=>wwv_flow_imp.id(561547836135222071.4001)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Si est\00E1 activada la opci\00F3n <strong>Usar para b\00FAsqueda en filas</strong> en un par\00E1metro origen de datos de REST, se transferir\00E1n las consultas de <em>B\00FAsqueda en filas</em> (de informes interactivos, cuadr\00EDculas interactivas o listas de valores e')
||unistr('mergentes) al servicio web con este par\00E1metro. Esto es \00FAtil si el servicio REST soporta los par\00E1metros de <em>b\00FAsqueda</em> o <em>consulta</em>.'),
'</p>',
'<p>Ejemplo:</p>',
'<p>',
unistr('    Se llama a un punto final de servicio REST con un par\00E1metro de consulta "q", por ejemplo <code>http://{server}/path/to/service?p={search-term}</code>. El origen de datos de REST tendr\00E1 definido el par\00E1metro de cadena de consulta <strong>q</strong')
||unistr('>. Si est\00E1 activada la opci\00F3n <strong>Usar para b\00FAsqueda en filas</strong>, se transferir\00E1n los t\00E9rminos de b\00FAsqueda del informe interactivo o de la fila de cuadr\00EDcula interactiva al servicio REST como par\00E1metro <strong>q</strong>.'),
'</p>',
unistr('<p>Solo se pueden usar par\00E1metros definidos en el nivel de origen de REST para la b\00FAsqueda en filas.</p>')))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'use_defaults', 'Y')).to_clob
);
