'     then :P1923_BOOLEAN_TRUE || '','' || :P1923_BOOLEAN_FALSE',
'end'))
,p_compute_when=>'P1923_DATA_TYPE'
,p_compute_when_text=>'BOOLEAN'
,p_compute_when_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
);
