,p_validation_name=>'Value provided for Required  Parameters'
,p_validation_sequence=>40
,p_validation=>'P1923_VALUE'
,p_validation_type=>'ITEM_NOT_NULL'
,p_error_message=>'Debe proporcionarse un valor por defecto , pues el origen de REST se encuentra en uso.'
