wwv_flow_imp_page.create_page_computation(
 p_id=>wwv_flow_imp.id(2564014108654038.4001)
,p_computation_sequence=>10
,p_computation_item=>'P1925_DATA_PROFILE_FOR'
,p_computation_point=>'BEFORE_BOX_BODY'
,p_computation_type=>'FUNCTION_BODY'
,p_computation_language=>'PLSQL'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    for l_web_src in (',
'        select id ',
'          from wwv_flow_web_src_modules',
'         where flow_id           = :FB_FLOW_ID',
'           and security_group_id = :FLOW_SECURITY_GROUP_ID',
'           and data_profile_id   = :P1925_DATA_PROFILE_ID )',
'    loop',
'        return ''REST_SOURCE'';',
'    end loop;',
'',
'    for l_doc_src in (',
'        select id ',
'          from wwv_flow_document_sources',
'         where flow_id           = :FB_FLOW_ID',
'           and security_group_id = :FLOW_SECURITY_GROUP_ID',
'           and data_profile_id   = :P1925_DATA_PROFILE_ID )',
'    loop',
'        return ''DOC_SOURCE'';',
'    end loop;',
'',
'    return ''DATA_LOAD'';',
'end;'))
);
