,p_lov=>'.'||wwv_flow_imp.id(4818478622110870)||'.'
,p_lov_display_null=>'YES'
,p_lov_null_text=>'Ninguno'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071.4001)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Seleccione una regla de transformaci\00F3n sencilla para cambiar el valor cargado. Por ejemplo, si los datos de origen contienen datos de columnas en formato de may\00FAsculas y min\00FAsculas, las opciones <strong>A min\00FAsculas</strong> o <strong>A may\00FAscula')
||unistr('s</strong> permiten convertir los datos en las may\00FAsculas o min\00FAsculas que se desee.'),
'    </p>',
'<ul>',
unistr('    <li><strong>Recortar a la izquierda</strong>, <strong>Recortar a la derecha</strong> y <strong>Recortar</strong>:<br> recorta los caracteres especificados en <strong>Expresi\00F3n 1</strong> del lado izquierdo, el lado derecho o de ambos lados del va')
||'lor de datos cargado.</li>',
unistr('    <li><strong>Sustituir</strong>:<br> sustituci\00F3n simple de las incidencias de <strong>Expresi\00F3n&nbsp;1</strong> por <strong>Expresi\00F3n&nbsp;2</strong>.</li>'),
unistr('    <li><strong>A may\00FAsculas</strong>:<br> convierte el valor en may\00FAsculas.</li>'),
unistr('    <li><strong>A min\00FAsculas</strong>:<br> convierte el valor en min\00FAsculas.</li>'),
unistr('    <li><strong>Nulo si</strong>:<br> si el valor cargado es igual a la cadena especificada en <strong>Expresi\00F3n&nbsp;1</strong>, el valor se cargar\00E1 como NULL.</li>'),
unistr('    <li><strong>Expresi\00F3n regular Replace</strong>:<br> aplique la expresi\00F3n regular especificada en <strong>Expresi\00F3n&nbsp;1</strong> y sustituya todas las coincidencias por <strong>Expresi\00F3n&nbsp;2</strong>.</li>'),
unistr('    <li><strong>Expresi\00F3n regular Null If</strong>:<br> si la expresi\00F3n regular especificada en <strong>Expresi\00F3n&nbsp;1</strong> coincide, carga el valor de la columna como NULL.</li>'),
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
