'<p>',
'   Ejemplos:    ',
'</p>',
'<ul>',
unistr('    <li><code>2019-01-01T20:00:00Z</code> contiene informaci\00F3n sobre la zona horaria</li>'),
unistr('    <li><code>2019-01-01T20:00:00 Europe/Berlin</code> contiene informaci\00F3n sobre la zona horaria</li>'),
unistr('    <li><code>2019-01-01T20:00:00</code> no contiene informaci\00F3n sobre la zona horaria</li>'),
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'use_defaults', 'Y')).to_clob
