,p_plug_name=>'Servidores Remotos'
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4001)
,p_plug_display_sequence=>10
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_display_point=>'REGION_POSITION_03'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>La informaci\00F3n del servidor de origen de datos de REST se almacena como un objeto de <strong>servidor remoto</strong>. Los servidores remotos se pueden compartir en varios or\00EDgenes de datos de REST. Un cambio en las propiedades del servidor remoto')
||unistr(' afectar\00E1 a todos los or\00EDgenes de datos de REST que hagan referencia a ese objeto (por ejemplo, puede cambiar un objeto de servidor remoto de un sistema de prueba a uno de producci\00F3n).</p>'),
'',
unistr('<p>Los servidores remotos se almacenan en el nivel de espacio de trabajo y, por lo tanto, aparecen en todas las aplicaciones. Al exportar una aplicaci\00F3n, los servidores remotos utilizados se agregan al archivo de exportaci\00F3n. Al importar la aplicaci\00F3')
||unistr('n a otro espacio de trabajo, &PRODUCT_NAME. comprueba si el espacio de trabajo de destino ya contiene servidores remotos con el mismo <strong>ID est\00E1tico</strong>. Si el servidor remoto ya existe, la aplicaci\00F3n lo utiliza. De lo contrario, se crean s')
||unistr('ervidores remotos desde el archivo de importaci\00F3n en el espacio de trabajo de destino.</p>')))
,p_plug_display_condition_type=>'EXPRESSION'
,p_plug_display_when_condition=>'nvl(#OWNER#.wwv_flow_preferences.get_preference(''FP_PREF_SHOW_INFORMATION''),''YES'') = ''YES'''
,p_plug_display_when_cond2=>'PLSQL'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(249349483233883038.4001)
,p_plug_name=>'Servidores Remotos'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(646287526247383209.4001)
,p_plug_display_sequence=>20
,p_include_in_reg_disp_sel_yn=>'Y'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with data as (',
'    select s.id,',
'           s.name,',
'           s.server_type,',
'           s.base_url,',
'           s.static_id,',
'           nvl2( s.configuration_procedure, ''Y'', ''N'' ) dynamic,',
'           count(m.id)  module_references,',
'           count(ma.id) auth_references,',
'           count(f.id)  app_references',
'      from wwv_remote_servers s',
'           left outer join wwv_flow_web_src_modules m ',
'                      on (     s.security_group_id = m.security_group_id',
'                           and s.id                = m.remote_server_id )',
'           left outer join wwv_flow_web_src_modules ma ',
'                      on (     s.security_group_id = ma.security_group_id',
'                           and s.id                = ma.auth_remote_server_id )',
'           left outer join wwv_flows f ',
'                      on (     s.security_group_id = f.security_group_id',
'                           and (    s.id = f.print_remote_server_id ',
'                                 or s.id = f.file_remote_server_id ) )',
'        --',
'     where s.server_type       in ( ''WEB_SERVICE'', ''AUTHENTICATION'', ''PRINT_SERVER'', ''CLOUD_OBJECT_STORE'' )',
'       and s.security_group_id  = :FLOW_SECURITY_GROUP_ID',
'       and not exists ( select 1 ',
'                          from wwv_flow_language_map ',
'                         where translation_flow_id in ( m.flow_id, ma.flow_id, f.id ) )',
'     group by s.id, s.name, s.server_type, s.base_url, s.static_id, s.credential_id, s.configuration_procedure',
') ',
'select ',
'    id,',
'    name,',
'    server_type,',
'    base_url,',
'    static_id,',
'    dynamic,',
'    module_references + auth_references + app_references as references',
'from data',
''))
,p_plug_source_type=>'NATIVE_IR'
