wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(2000804282223106.4001)
,p_name=>'P1932_CONFIGURATION_PROCEDURE'
,p_item_sequence=>50
,p_item_plug_id=>wwv_flow_imp.id(225856843527926534.4001)
,p_use_cache_before_default=>'NO'
,p_prompt=>unistr('Procedimiento de configuraci\00F3n')
,p_source=>'CONFIGURATION_PROCEDURE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>50
,p_cMaxlength=>255
,p_field_template=>wwv_flow_imp.id(561547836135222071.4001)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Introduzca el nombre de un procedimiento que configure la URL de punto final en el tiempo de ejecuci\00F3n.'),
unistr('Esto puede ser un procedimiento almacenado o un procedimiento definido en el elemento <em>C\00F3digo PL/SQL</em>.'),
unistr('El c\00F3digo siguiente es para una aplicaci\00F3n que implementa multi-arrendamiento y soporta'),
'diferentes variaciones de <em>URL de punto final</em> para los inquilinos.',
unistr('Cambia el nombre de dominio en la URL, seg\00FAn el cliente (Las URL son, por ejemplo: '),
'https://cust-01.example.com, https://cust-02.example.com):',
'</p><pre><code>',
'procedure my_server_config(',
'    p_info   in  apex_plugin.t_remote_server_info,',
'    p_config out apex_plugin.t_remote_server_config )',
'is',
'begin',
'    if p_info.application_id = 100',
'    then',
'      p_config.base_url := ''https://#cust#.example.com'';',
'      p_config.substitutions := apex_t_varchar2();',
'      apex_string.plist_put( p_config.substitutions, ''cust'', v(''P3_CUSTOMER'') );',
'    else',
'      p_config.base_url := ''https://test.example.com'';',
'    end if;',
'end;',
'</code></pre><p>',
unistr('El procedimiento puede cambiar dos atributos del par\00E1metro de entrada/salida <code>p_config</code>,'),
'de los cuales todos son opcionales:',
'<ul>',
'    <li><code>base_url</code>:',
'    Cambia la <em>URL de punto final</em>.',
'    </li>',
'    <li><code>substitutions</code>:',
'    Asigne pares de nombre/valor usando <code>apex_t_varchar2</code>.',
'    &PRODUCT_NAME. sustituye cada <code>#NAME#</code> en la <em>URL base</em> o <em>URL de punto final</em>.',
'    </li>',
'</ul>',
'</p>',
''))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'TEXT',
  'trim_spaces', 'BOTH')).to_clob
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(2000966576223107.4001)
,p_name=>'P1932_PLSQL_CODE'
