wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(3850682801212121729.4001)
,p_name=>'P1941_WEB_SRC_TYPE'
,p_item_sequence=>40
,p_item_plug_id=>wwv_flow_imp.id(3850682090247121721.4001)
,p_item_default=>'NATIVE_HTTP'
,p_prompt=>'Tipo de origen de datos de REST'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'WEB_SOURCE_MODULE_TYPES'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select d,',
'       r',
'  from (',
'         select wwv_flow_lang.system_message(''WEB_SOURCE.''|| name_with_prefix) as d,',
'               name_with_prefix as r',
'          from wwv_flow_native_plugins',
'         where plugin_type = ''WEB SOURCE TYPE''',
'         union all',
'        select display_name || wwv_flow_lang.system_message(''PLUGIN.DISPLAY_NAME_POSTFIX'') as d,',
'               ''PLUGIN_'' || name     as r',
'          from wwv_flow_plugins',
'         where flow_id           = to_number(:FB_FLOW_ID)',
'           and security_group_id = to_number(:WORKSPACE_ID)',
'           and plugin_type       = ''WEB SOURCE TYPE''',
'       )',
' order by 1'))
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071.4001)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Determina el tipo de origen de datos de REST.',
'<ul>',
unistr('<li><strong>HTTP simple</strong> indica una fuente de datos de HTTP simple. &PRODUCT_NAME. asume que todos los datos se devuelven con la primera solicitud y que el servidor no soporta el filtrado, la ordenaci\00F3n ni ninguna otra funci\00F3n avanzada de ser')
||unistr('vicio REST en el servidor. Todos los par\00E1metros y detalles de llamada se deben configurar manualmente.</li>'),
unistr('<li><strong>Oracle REST Data Services</strong> (ORDS) indica servicios RESTful proporcionados por ORDS. Estos servicios REST siguen el <em>est\00E1ndar Oracle REST</em>, lo que significa que las operaciones GET, POST, PUT y DELETE est\00E1n estandarizadas. E')
||unistr('l filtrado y la ordenaci\00F3n en el servidor est\00E1n soportados. &PRODUCT_NAME. puede aprovechar estas funciones mediante la delegaci\00F3n de filtros y order by de informe al servicio REST.</li>'),
unistr('<li><strong>Consulta SQL activada para REST</strong> indica un origen de REST superior de una consulta SQL ejecutada en una referencia SQL activada para REST. &PRODUCT_NAME. soporta el filtrado y la paginaci\00F3n, pero ning\00FAn DML en estos puntos finales')
||'.</li>',
'<li><strong>Servicio REST de las aplicaciones de Oracle Cloud (SaaS)</strong> indica servicios web RESTful proporcionados por las aplicaciones de Oracle Cloud (SaaS). Utilice este tipo de servicio web para integrar los servicios REST de Oracle SaaS e'
||unistr('n su aplicaci\00F3n &PRODUCT_NAME. &PRODUCT_NAME. soporta la paginaci\00F3n para estos servicios.</li>'),
'<li><strong>Servicio REST de Oracle Cloud Infrastructure (OCI)</strong> indica servicios web RESTful proporcionados por Oracle Cloud Infrastructure. Utilice este tipo de servicio web para integrar los servicios REST de OCI (por ejemplo, el acceso al '
||unistr('almac\00E9n de objetos) en su aplicaci\00F3n &PRODUCT_NAME. &PRODUCT_NAME. soporta la paginaci\00F3n para estos servicios.</li>'),
unistr('<li><strong>Servicio REST de OData</strong> indica un servicio REST que implanta el protocolo Open Data (OData), un est\00E1ndar OASIS aprobado por ISO/IEC que define un juego de mejores pr\00E1cticas para la creaci\00F3n y el consumo de API RESTful. Actualmente')
||unistr(', <em>&PRODUCT_NAME. solo soporta las API de tipo <em>Fetch</em> (lectura de datos); las operaciones DML para OData todav\00EDa no est\00E1n soportadas.</em></li>'),
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
