wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3802161062901510.4001)
,p_plug_name=>unistr('Sincronizaci\00F3n de REST')
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody:a-Region--noBorder'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4001)
,p_plug_display_sequence=>40
,p_plug_display_point=>'REGION_POSITION_03'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('La <strong>sincronizaci\00F3n de REST</strong> permite mantener el contenido de una tabla local sincronizado autom\00E1ticamente con los datos de un servicio REST. La sincronizaci\00F3n se puede disparar manualmente o de forma regular mediante un trabajo de prog')
||'ramador.',
'</p>',
'<p>',
unistr('APEX puede crear la tabla local, seg\00FAn las columnas visibles en el <strong>perfil de datos</strong> del origen de datos de REST. No obstante, la tabla es un <em>objeto visible</em> del esquema de base de datos; es decir, los desarrolladores <em>puede')
||unistr('n</em> agregar \00EDndices, cambiar propiedades f\00EDsicas o, incluso, agregar m\00E1s columnas a la tabla. '),
'</p>',
'<p>',
unistr('Si la tabla <em>no</em> se sincroniza con el perfil de datos, la sincronizaci\00F3n de REST seguir\00E1 trabajando en columnas presentes en la tabla <em>y</em> en el perfil de datos (se ignorar\00E1 el resto de las columnas). No obstante, APEX genera sentencias ')
||unistr('SQL DDL para sincronizar de nuevo las columnas de tabla con el perfil de datos. Estas se pueden agregar a la aplicaci\00F3n como objetos de soporte.'),
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
