,p_process_success_message=>unistr('Desinstalaci\00F3n correcta. ')
,p_internal_uid=>9801909508671111.4001
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(17816722738661007.4001)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Delete Application'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'if :P2110_DELETE_FEEDBACK = ''Y'' then',
'    wwv_flow_imp.remove_application (',
'    p_application_id  => :FB_FLOW_ID,',
'    p_delete_feedback => true);',
'else',
'    wwv_flow_imp.remove_application (',
'    p_application_id  => :FB_FLOW_ID);',
'end if;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>unistr('No se ha podido suprimir la definici\00F3n de aplicaci\00F3n.')
,p_process_when_button_id=>wwv_flow_imp.id(37419900654747681.4001)
,p_process_when=>'APPLICATION'
,p_process_when_type=>'CONDITION1_IN_VALUE_OF_ITEM_IN_CONDITION2'
,p_process_when2=>'P2110_DEINSTALLATION_OPTIONS'
,p_process_success_message=>unistr('Se ha suprimido la definici\00F3n de aplicaci\00F3n.')
,p_internal_uid=>17816722738661007.4001
);
