,p_plug_display_sequence=>20
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_new_grid_row=>false
,p_plug_new_grid_column=>false
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select r.id,',
'       r.group_name name,',
'       r.static_id,',
'       r.group_desc description,',
'       ( select count(*)',
'           from wwv_flow_acl_group_users u',
'          where u.group_id          = r.id',
'            and u.security_group_id = r.security_group_id ) assigned_user_count,',
'       --',
'       case when r.reference_id is not null then',
'           coalesce ( to_char( master.flow_id ),',
'                       wwv_flow_lang_dev.builder_message( ''SUBSCRIBED_FROM.NONEXISTING_MASTER'' ) )',
'       end as subscribed_from,',
'       ( select case when count(*) > 0 then count(*) end',
'           from wwv_flow_fnd_user_groups sub',
'          where sub.reference_id      = r.id',
'            and sub.security_group_id = :FLOW_SECURITY_GROUP_ID',
'       ) as subscribers,',
'       case when r.reference_id is not null then',
'           case',
'               when master.version_scn = r.version_scn then',
'                   wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_UP_TO_DATE'')',
'               when master.version_scn != r.version_scn then',
'                   wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_NEEDS_REFRESH'')',
'               else',
'                   wwv_flow_lang_dev.builder_message(''WWV_FLOW_F4000_PLUGINS.SUBSCRIPTION_UNKNOWN'')',
'           end',
'       end subscription_status,',
'       --',
'       null as actions',
'  from wwv_flow_fnd_user_groups r,',
'       wwv_flow_fnd_user_groups master',
' where r.flow_id           = :FB_FLOW_ID',
'   and r.security_group_id = :FLOW_SECURITY_GROUP_ID',
'   and r.reference_id      = master.id (+)',
'   and r.security_group_id = master.security_group_id (+)'))
,p_plug_source_type=>'NATIVE_IR'
