'elsif wwv_flow_user_interface_dev.dialog_page_template_exists(',
'                     p_application_id => :FB_FLOW_ID ) then ',
'    return ''MODAL'';',
'else',
'    return ''NORMAL'';',
'end if;'))
,p_item_default_type=>'FUNCTION_BODY'
,p_item_default_language=>'PLSQL'
,p_prompt=>unistr('Modo de P\00E1gina de Pantalla')
