wwv_flow_imp_page.create_page_computation(
 p_id=>wwv_flow_imp.id(39804839969554116.4001)
,p_computation_sequence=>10
,p_computation_item=>'P2501_SHOW_DATA_SOURCE'
,p_computation_point=>'BEFORE_HEADER'
,p_computation_type=>'FUNCTION_BODY'
,p_computation_language=>'PLSQL'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_data_source varchar2(1) := ''Y'';',
'    l_standard_attributes wwv_flow_plugins.standard_attributes%type;',
'begin',
'    if   :P2500_PAGE_TYPE in (''BLANK'',''DATALOAD'',''FORMONPROC'',''DASHBOARD'',''TASKLIST'',''SEARCH'',''WORKFLOWCONSOLE'')',
'      or :P2500_PAGE_TYPE like ''TMPL\_%'' escape ''\''',
'      or :P2500_PAGE_TYPE like ''PAGEPATTERN%''',
'    then',
'        l_data_source := ''N'';      ',
'    end if;',
'    ',
'    if :P2500_PAGE_TYPE = ''PLUGIN'' then',
'        l_standard_attributes := wwv_flow_plugin_dev.get_standard_attributes (',
'                                     p_application_id => :FB_FLOW_ID,',
'                                     p_plugin_type    => ''REGION TYPE'',',
'                                     p_plugin_name    => :P2509_REGION_TYPE ); ',
'                                     ',
'        if '':''||l_standard_attributes||'':'' not like ''%:SOURCE_LOCATION:%'' then',
'            l_data_source := ''N'';    ',
'        end if;   ',
'    end if;',
'    return l_data_source;',
'end;'))
);
