,p_plug_name=>'Ayuda'
,p_region_template_options=>'#DEFAULT#:js-dialog-size480x320'
,p_plug_template=>wwv_flow_imp.id(557449278618308550.4001)
,p_plug_display_sequence=>30
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Tipo de capa de geometr\00EDa espacial que mostrar en el mapa:'),
'</p>',
'<ul>',
'    <li><strong>Puntos</strong>: los puntos (por ejemplo, ubicaciones de clientes o proveedores) se muestran como marcadores. Se puede configurar tanto la forma como el color del marcador.</li>',
unistr('    <li><strong>L\00EDneas</strong>: las l\00EDneas representan funciones como carreteras o rutas. Se puede configurar tanto el estilo como el color del trazo.</li>'),
unistr('    <li><strong>Pol\00EDgonos</strong>: los pol\00EDgonos representan \00E1reas como parcelas, estados o pa\00EDses. Se puede configurar tanto el estilo como el color del trazo y del relleno.</li>'),
unistr('    <li><strong>Mapa de calor</strong>: los mapas de calor se usan para visualizar la densidad de las funciones de punto. Cuantos m\00E1s puntos se agrupen, m\00E1s intenso ser\00E1 el color. Se suelen usar para visualizar la distribuci\00F3n espacial de poblaci\00F3n o')
||' incidentes.</li>',
unistr('    <li><strong>Pol\00EDgonos extruidos</strong>: similares a los pol\00EDgonos, pero los pol\00EDgonos se muestran como objetos extruidos tridimensionales. La altura del objeto en 3D muestra un valor de una columna.</li>'),
'</ul>',
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
