 p_id=>wwv_flow_imp.id(7202756662307250.4001)
,p_name=>'P2506_LAYER_TYPE'
,p_is_required=>true
,p_item_sequence=>10
,p_item_plug_id=>wwv_flow_imp.id(3063654112256537.4001)
,p_item_default=>'POINT'
,p_prompt=>'Tipo de capa'
,p_display_as=>'PLUGIN_COM.ORACLE.APEX.WIZARD_SELECTION'
,p_named_lov=>'MAP_REGION_LAYER_TYPE'
,p_lov=>'.'||wwv_flow_imp.id(2204527800561582)||'.'
,p_field_template=>wwv_flow_imp.id(566010921977401124.4001)
,p_item_css_classes=>'a-IconList--CreatePageDialog margin-bottom-none'
,p_item_template_options=>'#DEFAULT#:a-Form-fieldContainer--autoLabelWidth'
,p_lov_display_extra=>'NO'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'S',
  'attribute_02', 'N')).to_clob
,p_item_comment=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'    Type of the spatial geometry layer to show on the map:',
'</p>',
'<ul>',
'    <li><strong>Points</strong>: Points (e.g. customer or supplier locations) are displayed as markers. The marker shape and color is configurable.</li>',
'    <li><strong>Lines</strong>: Lines represent features like roads or paths. Stroke style and color is configurable.</li>',
'    <li><strong>Polygons</strong>: Polygons represent areas like parcels, states or countries. Style and collor are configurable for stroke and fill.</li>',
'    <li><strong>Heat Map</strong>: Heat Maps are used to visualize the density of point features. The more points are clustered together, the more intense the color gets. Typically used to visualize the spatial distribution of population or incidents'
||'.</li>',
'    <li><strong>Extruded Polygons</strong>: Similar to Polygons, but the polygons are displayed as three-dimensional, "extruded", objects. The height of the 3D object visualizes a column value.</li>',
'</ul>',
''))
);
