'  from wwv_flow_plugins',
' where flow_id           = :FB_FLOW_ID',
'   and security_group_id = :WORKSPACE_ID',
'   and plugin_type       = ''REGION TYPE''',
'   -- display plug-ins with valid source types',
'   and ( -- plug-in does not have source, then show the plug-in',
'        '':''||standard_attributes||'':'' not like ''%:SOURCE%:''',
