wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(4804520289096941.4001)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Create MD Page'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_master  wwv_flow_wizard_api.t_md;',
'    l_detail  wwv_flow_wizard_api.t_md;',
'    l_details wwv_flow_wizard_api.t_mds;',
'begin',
'    l_master.location             := :P2501_LOCATION;',
'    l_master.owner                := :P2501_TAB_OWNER;',
'    l_master.table_name           := :P2501_TAB_NAME;',
'    l_master.cols                 := :P2501_ALL_COLUMNS;',
'    l_master.pk_col               := :P2502_PK_COLUMN_1;',
'    l_master.pk_col2              := :P2502_PK_COLUMN_2;',
'    l_master.navigation_order_col := :P2502_MASTER_NAV_ORDER;',
'    l_master.primary_label_col    := :P2502_MASTER_DISP_COL1;',
'    l_master.secondary_label_col  := :P2502_MASTER_DISP_COL2;',
'    l_master.remote_server_id     := :P2501_REMOTE_SERVER_ID;',
'    l_master.web_src_module_id    := :P2501_WEB_SRC_MODULE_ID;',
'    l_master.document_source_id   := case :P2501_LOCATION ',
'                                         when ''DUALITY_VIEW''    then :P2501_DUALITY_VIEW',
'                                         when ''JSON_COLLECTION'' then :P2501_JSON_SOURCE',
'                                     end;',
'    l_master.array_column_id      := case :P2501_LOCATION',
'                                         when ''DUALITY_VIEW''    then :P2501_DV_ARRAY_COL_ID',
'                                         when ''JSON_COLLECTION'' then :P2501_JSON_SRC_ARRAY_COL_ID',
'                                         when ''WEB_SOURCE''      then :P2501_WEB_SRC_ARRAY_COL_ID',
'                                     end;  ',
'',
'    l_detail.location             := :P2515_LOCATION;',
'    l_detail.owner                := :P2515_TAB_OWNER;',
'    l_detail.table_name           := :P2515_TAB_NAME;',
'    l_detail.cols                 := :P2515_ALL_COLUMNS;',
'    l_detail.pk_col               := :P2516_PK_COLUMN_1;',
'    l_detail.pk_col2              := :P2516_PK_COLUMN_2;',
'    l_detail.fk_con               := :P2516_DETAIL_FK_CONS;',
'    l_detail.master_col           := :P2516_MASTER_COL;',
'    l_detail.detail_col           := :P2516_DETAIL_COL;',
'    l_detail.remote_server_id     := :P2515_REMOTE_SERVER_ID;',
'    l_detail.web_src_module_id    := :P2515_WEB_SRC_MODULE_ID;',
'    l_detail.document_source_id   := case :P2515_LOCATION ',
'                                         when ''DUALITY_VIEW''    then :P2515_DUALITY_VIEW',
'                                         when ''JSON_COLLECTION'' then :P2515_JSON_SOURCE',
'                                     end;',
'    l_detail.array_column_id      := case :P2515_LOCATION',
'                                         when ''DUALITY_VIEW''    then :P2515_DV_ARRAY_COL_ID',
'                                         when ''JSON_COLLECTION'' then :P2515_JSON_SRC_ARRAY_COL_ID',
'                                         when ''WEB_SOURCE''      then :P2515_WEB_SRC_ARRAY_COL_ID',
'                                     end;      ',
'',
'',
'    if :P2513_MD_TYPE = ''MD_SINGLE_PG'' then',
'    -- Stacked',
'        l_master.region_title := :P2501_PAGE_NAME;',
'        l_detail.region_title := :P2515_REGION_TITLE;',
'        wwv_flow_wizard_api.create_md_single_page (',
'            p_application_id           => :FB_FLOW_ID,',
'            p_page_id                  => :P2501_PAGE_ID,',
'            p_page_name                => :P2501_PAGE_NAME,',
'            p_page_mode                => :P2501_PAGE_MODE,',
'            --',
'            p_nav_list_id              => :P2500_NAVLIST_ID,',
'            p_nav_list_parent_item_id  => :P2501_NAVLIST_PARENT_ID,',
'            p_nav_list_child_item_name => case when :P2501_NAVLIST_OPTIONS = ''NEW'' then :P2501_PAGE_NAME end,',
'            p_nav_list_item_icon        => :P2501_PAGE_ICON,',
'            --',
'            p_breadcrumb_id            => :P2501_BREADCRUMB_ID,',
'            p_breadcrumb_name          => :P2501_PAGE_NAME,',
'            p_parent_bc_id             => :P2501_BREADCRUMB_PARENT_ID,',
'            --',
'            p_master_region            => l_master,',
'            p_detail_region            => l_detail  );',
'',
'        :FB_FLOW_PAGE_ID       := :P2501_PAGE_ID;',
'        :F4000_RUN_EDIT_PAGE   := :P2501_PAGE_ID;',
'    elsif :P2513_MD_TYPE = ''MD_EMAIL_STYLE'' then',
'    -- Side by Side',
'        l_master.page_id := wwv_flow_utilities.minimum_free_page( p_flow_id => :FB_FLOW_ID, p_start_page => :P2501_PAGE_ID );',
