wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(2702037554067618.4001)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load Search Cofig Columns Collection'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'wwv_flow_search_dev.init_column_collection (',
'    p_column_collection      => ''APEX$SEARCH_CONFIG_COLUMNS'',',
'    --',
'    p_application_id         => :FB_FLOW_ID,',
'    p_search_type            => wwv_flow_search.c_search_type_simple,',
'    --',
'    p_location               => :P3112_LOCATION,',
'    p_query_type             => case :P3112_LOCATION',
'                                    when wwv_flow_exec_api.c_location_local_db then :P3112_SOURCE_TYPE',
'                                    when wwv_flow_exec_api.c_location_remote_db then :P3112_REMOTE_SOURCE_TYPE',
'                                end,',
'    p_owner                  => case',
'                                   when :P3112_LOCATION = wwv_flow_exec_api.c_location_local_db and :P3112_SOURCE_TYPE in ( wwv_flow_exec_api.c_query_type_table, ',
'                                                                                                                            wwv_flow_exec_api.c_query_type_graph ) then',
'                                       :P3112_TABLE_OWNER',
'                                   when :P3112_LOCATION = wwv_flow_exec_api.c_location_remote_db and :P3112_REMOTE_SOURCE_TYPE = wwv_flow_exec_api.c_query_type_table then',
'                                       :P3112_REMOTE_TABLE_OWNER',
'                                end,',
'    p_table_name             => case',
'                                   when :P3112_LOCATION = wwv_flow_exec_api.c_location_local_db and :P3112_SOURCE_TYPE =  wwv_flow_exec_api.c_query_type_table then',
'                                       :P3112_TABLE_NAME',
'                                   when :P3112_LOCATION = wwv_flow_exec_api.c_location_local_db and :P3112_SOURCE_TYPE =  wwv_flow_exec_api.c_query_type_graph then',
'                                       :P3112_GRAPH_NAME',
'                                   when :P3112_LOCATION = wwv_flow_exec_api.c_location_remote_db and :P3112_REMOTE_SOURCE_TYPE = wwv_flow_exec_api.c_query_type_table then',
'                                       :P3112_REMOTE_TABLE_NAME',
'                                end,',
'    p_sql_query              => case',
'                                    when :P3112_LOCATION = wwv_flow_exec_api.c_location_local_db and :P3112_SOURCE_TYPE = wwv_flow_exec_api.c_query_type_sql_query then',
'                                        :P3112_SQL',
'                                    when :P3112_LOCATION = wwv_flow_exec_api.c_location_remote_db and :P3112_REMOTE_SOURCE_TYPE = wwv_flow_exec_api.c_query_type_sql_query then',
'                                        :P3112_REMOTE_SQL',
'                                end,',
'    p_match_clause           => case ',
'                                    when :P3112_LOCATION = wwv_flow_exec_api.c_location_local_db and :P3112_SOURCE_TYPE = wwv_flow_exec_api.c_query_type_graph then',
'                                        :P3112_PQL_MATCH_CLAUSE',
'                                end,                                ',
'    p_columns_clause         => case ',
'                                    when :P3112_LOCATION = wwv_flow_exec_api.c_location_local_db and :P3112_SOURCE_TYPE = wwv_flow_exec_api.c_query_type_graph then',
'                                        :P3112_PQL_COLUMNS_CLAUSE',
'                                end,',
'    --',
'    p_remote_server_id       => case when :P3112_LOCATION = wwv_flow_exec_api.c_location_remote_db then',
'                                    :P3112_REMOTE_SERVER_ID',
'                                end,',
'    p_web_src_module_id      => case when :P3112_LOCATION = wwv_flow_exec_api.c_location_rest_source then',
'                                    :P3112_WEB_SRC_MODULE_ID',
'                                end,',
'    p_document_source_id     => :P3112_DOCUMENT_SOURCE_ID,',
'    p_array_column_id        => :P3112_ARRAY_COLUMN_ID,',
'    --',
'    p_extended_describe      => true );'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>2702037554067618.4001
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(2832020264926540.4001)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Update APEX Dictionary Cache'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_object_type wwv_flow_tables_views_dev.object_type%type;',
'begin',
'    select object_type',
'      into l_object_type',
'      from wwv_flow_tables_views_dev',
'     where owner       = :P3112_TABLE_OWNER',
'       and object_name = :P3112_TABLE_NAME;',
'',
'    --- if table, set APEX dictionary cache',
'    if l_object_type = ''TABLE'' then',
'        wwv_dictionary_cache_dev.set_dictionary_table_cache(',
'             p_workspace_name          => htmldb_util.find_workspace( p_security_group_id => :WORKSPACE_ID ),',
'             p_schema                  => :P3112_TABLE_OWNER,',
'             p_table_name              => :P3112_TABLE_NAME,',
'             p_flow_id                 => :FB_FLOW_ID,',
'             p_cache_fk_references     => true );',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>':P3112_LOCATION = ''LOCAL'' and :P3112_SOURCE_TYPE = ''TABLE'''
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_internal_uid=>2832020264926540.4001
);
end;
