unistr('<p>Seleccione la forma en la que se rellena este par\00E1metro.</p><p>Entre las opciones disponibles se incluyen las siguientes:</p>'),
'<ul>',
unistr('    <li><strong>Valor est\00E1tico</strong>: def\00EDnalo seg\00FAn el texto introducido en el <em>valor est\00E1tico</em>.</li>'),
unistr('    <li><strong>Elemento</strong>: def\00EDnalo seg\00FAn el valor retenido en el estado de sesi\00F3n del <em>elemento</em> especificado.</li>'),
unistr('    <li><strong>Consulta SQL (devolver valor \00FAnico)</strong>: def\00EDnalo seg\00FAn el primer valor devuelto de la <em>consulta SQL</em> introducida.</li>'),
unistr('    <li><strong>Expresi\00F3n PL/SQL</strong>: def\00EDnalo seg\00FAn el valor resultante al ejecutar la <em>expresi\00F3n PL/SQL</em> introducida.</li>'),
unistr('    <li><strong>Cuerpo de la funci\00F3n PL/SQL</strong>: def\00EDnalo seg\00FAn el valor devuelto del <em>cuerpo de la funci\00F3n PL/SQL</em> introducido.</li>'),
unistr('    <li><strong>Recopilaci\00F3n (CLOB)</strong>: def\00EDnalo seg\00FAn el valor de columna de CLOB de la primera fila de la <em>recopilaci\00F3n</em> introducida.</li>'),
unistr('    <li><strong>Preferencia</strong>: def\00EDnalo seg\00FAn el valor de la <em>preferencia</em> introducida.</li>'),
unistr('    <li><strong>Nulo</strong>: def\00EDnalo en nulo si no se especifica ning\00FAn valor.</li>'),
'</ul>',
''))
);
