,p_item_source_plug_id=>wwv_flow_imp.id(1757925019180889.4001)
,p_prompt=>unistr('Prefijo de consulta de b\00FAsqueda')
,p_source=>'SEARCH_PREFIX'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>60
