,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Introduzca un prefijo que vayan a utilizar los usuarios finales en las consultas de b\00FAsquedas. Un t\00E9rmino de b\00FAsqueda con prefijo solo se utilizar\00E1 para las '),
unistr('    configuraciones de b\00FAsqueda con el mismo prefijo. Si se utiliza un prefijo en una consultad de b\00FAsqueda, pero no se define en '),
unistr('    <em>ninguna</em> configuraci\00F3n de b\00FAsqueda, se ignorar\00E1 el prefijo y se utilizar\00E1 el t\00E9rmino completo al buscar.'),
'</p>',
'<p>Ejemplos:</p>',
unistr('<p> Dos configuraciones de b\00FAsqueda: <strong>Empleados</strong> con el prefijo <strong>emp</strong>, '),
'    y <strong>Trabajos</strong> con el prefijo <strong>job</strong>.',
'</p>',
'<dl>',
'    <dt>emp:king president</dt>',
unistr('    <dd>La palabra clave <strong>king</strong> solo se buscar\00E1 en la configuraci\00F3n de b\00FAsqueda <strong>Empleados</strong>, '),
unistr('        <strong>president</strong> se buscar\00E1 en las dos.</dd>'),
'    <dt>emp:king job:president</dt>',
unistr('    <dd>La palabra clave <strong>king</strong> solo se buscar\00E1 en la configuraci\00F3n de b\00FAsqueda <strong>Empleados</strong>, '),
unistr('        <strong>president</strong> solo se buscar\00E1 en <strong>Trabajos</strong>.</dd>'),
'    <dt>emp:king depts:"new york"</dt>',
unistr('    <dd>La palabra clave <strong>king</strong> solo se buscar\00E1 en la configuraci\00F3n de b\00FAsqueda <strong>Empleados</strong>. '),
unistr('        <strong>depts:"new york"</strong> se buscar\00E1 en las dos,'),
'        porque el prefijo <strong>depts</strong> no se ha definido.</dd>',
'</dl>',
''))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
