'    p_search_type            => wwv_flow_search.c_search_type_vector,',
'    --',
'    p_location               => wwv_flow_exec_api.c_location_local_db,',
'    p_query_type             => :P3131_VECTOR_SOURCE_TYPE,',
'    p_owner                  => :P3131_VECTOR_TABLE_OWNER,',
'    p_table_name             => :P3131_VECTOR_TABLE_NAME,',
'    --',
'    p_extended_describe      => true );'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>1841652197857307.4001
);
