'       else',
'           c002',
'       end column_return,',
'      seq_id column_id',
' from wwv_flow_collections',
'where collection_name = ''APEX$SEARCH_CONFIG_COLUMNS'''))
,p_lov_display_null=>'YES'
,p_lov_null_text=>'- Seleccionar Columna -'
