wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(2317449986492645.4001)
,p_name=>'P3505_SQL'
,p_data_type=>'CLOB'
,p_item_sequence=>30
,p_item_plug_id=>wwv_flow_imp.id(2316239026492633.4001)
,p_prompt=>'Consulta SQL'
,p_display_as=>'PLUGIN_COM.ORACLE.APEX.CODE_EDITOR'
,p_cMaxlength=>32767
,p_cHeight=>14
,p_field_template=>wwv_flow_imp.id(561549716994252345.4001)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>Especifique la consulta SQL que genera una salida CSV como contexto para el servicio de IA. En la consulta, puede utilizar las siguientes variables de enlace especiales para acceder y evaluar las peticiones de datos del usuario:',
'<dl>',
'    <dt><code>APEX$AI_LAST_USER_PROMPT</code></dt>',
unistr('    <dd>Recupera las peticiones de datos que el usuario ha utilizado m\00E1s recientemente.</dd>'),
'    <dt><code>APEX$AI_ALL_USER_PROMPTS</code></dt>',
'    <dd>Recupera todas las peticiones de datos del usuario, concatenados en una sola cadena.</dd>',
'</dl>',
'</p>',
unistr('<p>Nota: El n\00FAmero de filas incluidas en la salida estar\00E1 limitado al m\00E1ximo especificado por el atributo de <em>tokens m\00E1ximos</em>, con un l\00EDmite absoluto de 10000 filas.</p>'),
'',
'<p>Ejemplo:</p>',
'<pre>',
'select e.empno as "Employee No",',
'       e.ename as "Employee Name",',
'       e.job   as "Job",',
'       e.sal   as "Salary",',
'       d.dname as "Department"',
'  from emp e',
'  left join dept d on d.deptno = e.deptno',
' order by e.ename',
'fetch first 100 rows only',
'</pre>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'SQL',
  'attribute_03', 'Y',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
);
