,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Especifique un cuerpo de funci\00F3n de PL/SQL que devuelva un objeto grande de caracteres y genere el contexto para el servicio de IA. En el c\00F3digo, puede utilizar las siguientes variables de enlace especiales para acceder y evaluar las peticiones de')
||' datos del usuario:',
'<dl>',
'    <dt><code>APEX$AI_LAST_USER_PROMPT</code></dt>',
unistr('    <dd>Recupera las peticiones de datos que el usuario ha utilizado m\00E1s recientemente.</dd>'),
'    <dt><code>APEX$AI_ALL_USER_PROMPTS</code></dt>',
'    <dd>Recupera todas las peticiones de datos del usuario, concatenados en una sola cadena.</dd>',
'</dl>',
'</p>',
'',
'<p>Ejemplo:</p>',
'<pre>',
'begin',
'    if lower( :APEX$AI_LAST_USER_PROMPT ) like ''%employee%'' then',
'        return ''Employee data'';',
'    else',
'        return ''Other data'';',
'    end if;',
'end;',
'</pre>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'PLSQL_FUNCTION_BODY',
  'attribute_02', 'VARCHAR2',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
);
