,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_escape_on_http_input=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('Especifica si la aplicaci\00F3n est\00E1 o no disponible para su uso. <p>'),
'Las opciones incluyen:<br>',
'<ul>',
unistr('<li><strong>Disponible</strong>: La aplicaci\00F3n est\00E1 disponible sin restricciones.</li>'),
unistr('<li><strong>Disponible con barra de herramientas del desarrollador</strong>: La aplicaci\00F3n est\00E1 disponible para su uso. Para los desarrolladores, la barra de herramientas del desarrollador se incluye en cada p\00E1gina. Es necesario que el desarrollador ')
||unistr('est\00E9 conectado al creador de aplicaciones en la misma sesi\00F3n del explorador.</li>'),
unistr('<li><strong>Disponible Solo para Desarrolladores</strong>: La aplicaci\00F3n est\00E1 disponible para los usuarios que tienen privilegios de desarrollador.</li>'),
unistr('<li><strong>Acceso Restringido</strong>: La aplicaci\00F3n est\00E1 disponible para los desarrolladores especificados en Limitar a Lista de Usuarios Separados por Comas.</li>'),
unistr('<li><strong>No Disponible</strong>: La aplicaci\00F3n no se puede ejecutar ni editar. Aparece el mensaje Mensaje para aplicaci\00F3n no disponible cuando los usuarios intentan acceder a la aplicaci\00F3n.</li>'),
unistr('<li><strong>No Disponible (Estado mostrado con PL/SQL)</strong>: La aplicaci\00F3n no se puede ejecutar ni editar.</li>'),
unistr('<li><strong>No Disponible (Redirigir a URL)</strong>: La aplicaci\00F3n no se puede ejecutar. El usuario se enlaza a la URL introducida en Mensaje para aplicaci\00F3n no disponible.</li>'),
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
