wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1378952136513217.4001)
,p_name=>'P4001_ORACLE_TEXT_FUNCTION'
,p_item_sequence=>150
,p_item_plug_id=>wwv_flow_imp.id(198116031744061165.4001)
,p_use_cache_before_default=>'NO'
,p_prompt=>unistr('Nombre de funci\00F3n personalizada')
,p_source=>'ORACLE_TEXT_FUNCTION'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>64
,p_cMaxlength=>500
,p_field_template=>wwv_flow_imp.id(561547836135222071.4001)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Especifique el nombre de una funci\00F3n PL/SQL personalizada que convierta la entrada del usuario final en una consulta de Oracle Text. '),
unistr('    Esta funci\00F3n toma la entrada del usuario final como VARCHAR2 y devuelve la consulta de Oracle Text como resultado.</p>'),
'<p>',
unistr('    En este ejemplo se utiliza la <em>relajaci\00F3n de consulta de Oracle Text</em>: primero, ejecuta la consulta exacta'),
unistr('    y, a continuaci\00F3n, va aumentando el nivel de <em>b\00FAsqueda parcial</em>, hasta que se devuelva la cantidad de filas'),
'    solicitada. Todo esto es totalmente transparente para el usuario final.',
'</p>',
'<pre>',
'create or replace function convert_end_user_search (',
'    p_search in varchar2 )',
'    return varchar2 ',
'is',
'    c_xml constant varchar2(32767) := ',
'        ''&lt;query&gt;&lt;textquery>&lt;progression&gt;''          ||',
'          ''&lt;seq&gt;       #SEARCH#            &lt;/seq&gt;'' ||',
'          ''&lt;seq&gt; FUZZY(#SEARCH#,80, 100,W) &lt;/seq&gt;'' ||',
'          ''&lt;seq&gt; FUZZY(#SEARCH#,50,1000,W) &lt;/seq&gt;'' ||',
'          ''&lt;seq&gt; FUZZY(#SEARCH#,20,3000,W) &lt;/seq&gt;'' ||',
'        ''&lt;/progression>&lt;/textquery>&lt;/query&gt;'';',
'',
'    l_search varchar2(32767) := p_search;',
'begin',
'    --',
'    -- remove special characters; ',
'    -- these are irrelevant for full text search',
'    --',
'    l_search := regexp_replace(',
'        srcstr  => l_search, ',
'        pattern => ''[&lt;&gt;{}/()*%&!$?.:,;\+#]'' );',
'',
'    return replace( ',
'        srcstr  => c_xml, ',
'        oldsub  => ''#SEARCH#'', ',
'        newsub  => ''{'' || l_search || ''}'' );',
'end;',
'</pre>',
'<p>',
unistr('    Para obtener m\00E1s informaci\00F3n sobre la sintaxis de las consultas de Oracle Text y la funci\00F3n de relajaci\00F3n de consultas,'),
'    consulte <a rel="noopener noreferrer" target="_blank" href="https://docs.oracle.com/en/database/oracle/oracle-database/23/ccapp/index.html">Oracle Text Application Developers Guide</a>.</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'TEXT',
  'trim_spaces', 'BOTH')).to_clob
);
