wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(4603513404.4001)
,p_name=>'F4000_P4008_SCHEME_TYPE'
,p_is_required=>true
,p_item_sequence=>60
,p_item_plug_id=>wwv_flow_imp.id(178678919656730458.4001)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Tipo de Esquema'
,p_source=>'SCHEME_TYPE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'AUTHORIZATION TYPE'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select d,',
'       r',
'  from (',
'        select wwv_flow_lang.system_message(''AUTHORIZATION_NAME.''|| name_with_prefix) as d,',
'               name_with_prefix      as r',
'          from wwv_flow_native_plugins',
'         where plugin_type = ''AUTHORIZATION TYPE''',
'         union all',
'        select display_name || wwv_flow_lang.system_message(''PLUGIN.DISPLAY_NAME_POSTFIX'') as d,',
'               ''PLUGIN_'' || name     as r',
'          from wwv_flow_plugins',
'         where flow_id           = to_number(:FB_FLOW_ID)',
'           and security_group_id = to_number(:WORKSPACE_ID)',
'           and plugin_type       = ''AUTHORIZATION TYPE''',
'       )',
' order by 1'))
,p_lov_display_null=>'YES'
,p_lov_null_text=>'- Seleccionar Tipo de Esquema -'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(452656722938220607.4001)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Seleccione la forma en la que se aplicar\00E1 este esquema de autorizaci\00F3n. Se soportan los siguientes tipos incorporados:</p>'),
'<ul>',
unistr('<li><strong>Consulta SQL Exists</strong>: consulta que hace que se apruebe el esquema de autorizaci\00F3n si devuelve al menos una fila y provoca que este falle si no devuelve ninguna</li>'),
unistr('<li><strong>Consulta SQL NOT Exists</strong>: consulta que hace que se apruebe el esquema de autorizaci\00F3n si no devuelve ninguna fila y provoca que este falle si devuelve una o m\00E1s filas</li>'),
unistr('<li><strong>Funci\00F3n PL/SQL que devuelve valor booleano</strong>: cuerpo de la funci\00F3n PL/SQL que devuelve un valor true o false. Un valor false provoca que el esquema de autorizaci\00F3n falle. Un valor true hace que se apruebe.</li>'),
unistr('<li><strong>Elemento en expresi\00F3n 1 nulo</strong>: el valor del elemento especificado en la expresi\00F3n 1 es nulo.</li>'),
unistr('<li><strong>Elemento en expresi\00F3n 1 no nulo</strong>: el valor del elemento especificado en la expresi\00F3n 1 no es nulo.</li>'),
unistr('<li><strong>Valor de preferencia en expresi\00F3n 1 equivale a expresi\00F3n 2</strong>: el valor de preferencia especificado en la expresi\00F3n 1 equivale a la expresi\00F3n 2.</li>'),
unistr('<li><strong>Valor de preferencia en expresi\00F3n 1 no equivale a expresi\00F3n 2</strong>: el valor de preferencia especificado en la expresi\00F3n 1 no equivale a la expresi\00F3n 2.</li>'),
unistr('<li><strong>Valor de elemento en expresi\00F3n 1 equivale a expresi\00F3n 2</strong>: el valor del elemento especificado en la expresi\00F3n 1 equivale a la expresi\00F3n 2.</li>'),
unistr('<li><strong>Valor de elemento en expresi\00F3n 1 no equivale a expresi\00F3n 2</strong>: el valor del elemento especificado en la expresi\00F3n 1 no equivale a la expresi\00F3n 2.</li>'),
unistr('<li><strong>Est\00E1 en rol o en grupo</strong>: comprueba los nombres de grupos o roles separados por comas proporcionados con respecto a los grupos o roles de usuario para los que se ha configurado el origen con el atributo de seguridad de aplicaci\00F3n <')
||'strong>Origen para esquemas de grupos o roles</strong>.',
unistr('<p>Si el origen est\00E1 definido en <em>Asignaciones de rol de usuario de control de acceso</em>, el proceso de autorizaci\00F3n solo tendr\00E1 en cuenta los roles ACL otorgados del usuario.</p>'),
unistr('<p>De lo contrario, comprobar\00E1 si los grupos est\00E1n activados como grupos din\00E1micos para la sesi\00F3n (consulte APEX_AUTHORIZATION.ENABLE_DYNAMIC_GROUPS). Si la aplicaci\00F3n utiliza un esquema de autenticaci\00F3n configurado con Real Security Application (RAS')
||unistr('), esta comprobaci\00F3n incluir\00E1 los roles de sesi\00F3n de RAS. Si se utiliza la autenticaci\00F3n de cuentas de Oracle APEX, esta comprobaci\00F3n incluye tambi\00E9n los grupos de espacios de trabajo que se otorgan al usuario. Si se utiliza la autenticaci\00F3n de base ')
||unistr('de datos, esta comprobaci\00F3n tambi\00E9n incluye los roles de base de datos que se otorgan al usuario.</p>'),
unistr('<p>El esquema de autorizaci\00F3n es correcto si se otorga al usuario cualquiera de los roles o grupos designados.</p>'),
'</li>',
unistr('<li><strong>No est\00E1 en el grupo</strong>: el grupo no est\00E1 activado o no se ha otorgado al usuario. Consulte <strong>Est\00E1 en el grupo</strong> para obtener m\00E1s informaci\00F3n.</li>'),
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
