,p_validation_type=>'NOT_EXISTS'
,p_error_message=>unistr('Este esquema de autorizaci\00F3n sigue en uso y no se puede suprimir. Haga clic en el enlace <strong>Utilizaci\00F3n</strong> debajo de <strong>Tareas</strong> para ver los datos de uso.')
