wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(8389505844522205.4001)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'update parent list'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'update wwv_flow_list_items',
'set list_id = :P4053_LIST_ID',
'where list_id = :P4053_OLD_LIST_ID',
'and flow_id = :FB_FLOW_ID',
'and security_group_id = :WORKSPACE_ID',
'and id in (',
'    select id',
'    from wwv_flow_list_items',
'    where flow_id = :FB_FLOW_ID',
'      and security_group_id = :WORKSPACE_ID',
'    start with id = :P4053_ID',
'    connect by prior id = parent_list_item_id ',
');',
'',
'if :P4053_PARENT_LIST_ITEM_ID=0 then',
'    update wwv_flow_list_items',
'       set parent_list_item_id = NULL',
'     where id = :P4053_ID',
'       and flow_id = :FB_FLOW_ID',
'       and security_group_id = :WORKSPACE_ID;',
'else',
'    update wwv_flow_list_items',
'       set parent_list_item_id = :P4053_PARENT_LIST_ITEM_ID',
'     where id = :P4053_ID',
'       and flow_id = :FB_FLOW_ID',
'       and security_group_id = :WORKSPACE_ID;',
'end if;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Fallo al actualizar la lista principal para los elementos de lista actuales y los elementos de sublista asociados.',
'',
''))
,p_process_when_button_id=>wwv_flow_imp.id(8435422523631181.4001)
,p_process_success_message=>unistr('La actualizaci\00F3n de la lista principal para los elementos de lista actuales y los elementos de sublista asociados se ha realizado correctamente.')
,p_internal_uid=>8389505844522205.4001
);
end;
