 p_id=>wwv_flow_imp.id(21185764186624645.4001)
,p_name=>'P4081_RETURN_COLUMN'
,p_is_required=>true
,p_item_sequence=>10
,p_item_plug_id=>wwv_flow_imp.id(104836580260625037.4001)
,p_prompt=>'Devolver Columna'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select column_name d, ',
'       column_name r',
'  from table( wwv_flow_exec_dev.get_query_columns(',
'                  p_location                => :P4080_LOCATION,',
'                  p_query_type              => case :P4080_LOCATION ',
'                                                   when ''LOCAL'' then :P4080_SOURCE_TYPE',
'                                                   when ''REMOTE'' then :P4080_REMOTE_SOURCE_TYPE',
'                                               end,',
'                  p_owner                   => case :P4080_LOCATION ',
'                                                   when ''LOCAL'' then :P4080_TABLE_OWNER',
'                                                   when ''REMOTE'' then :P4080_REMOTE_TABLE_OWNER',
'                                               end,       ',
'                  p_table_name              => case :P4080_LOCATION ',
