 p_id=>wwv_flow_imp.id(17314311266994460.4001)
,p_name=>'P4303_PROTECTION_LEVEL'
,p_source_data_type=>'VARCHAR2'
,p_item_sequence=>50
,p_item_plug_id=>wwv_flow_imp.id(17312310527965891.4001)
,p_item_source_plug_id=>wwv_flow_imp.id(454431825.4001)
,p_item_default=>'I'
,p_prompt=>unistr('Protecci\00F3n de Estado de la Sesi\00F3n')
,p_source=>'PROTECTION_LEVEL'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'ITEM PROTECTION LEVEL D'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'for c1 in (select nvl(PAGE_PROTECTION_ENABLED_Y_N,''N'') p from wwv_flows where id = :FB_FLOW_ID) loop',
'    if c1.p = ''Y'' then',
'       return  ''select wwv_flow_lang.system_message(''''UNRESTRICTED'''') d, ''''N'''' r',
'                  from sys.dual union all',
'                select wwv_flow_lang.system_message(''''CHECKSUM_REQUIRED_APPLICATION'''') d, ''''B'''' r',
'                  from sys.dual union all',
'                select wwv_flow_lang.system_message(''''CHECKSUM_REQUIRED_USER'''') d, ''''P'''' r',
'                  from sys.dual union all               ',
'                select wwv_flow_lang.system_message(''''CHECKSUM_REQUIRED_SESSION'''') d, ''''S'''' r',
'                  from sys.dual union all               ',
'                select wwv_flow_lang.system_message(''''RESTRICTED_NO_SET_FROM_BROWSER'''') d, ''''I'''' r',
'                  from sys.dual'';',
'    else',
'       return  ''select wwv_flow_lang.system_message(''''UNRESTRICTED'''') d, ''''N'''' r',
'                  from sys.dual union all ',
'                select wwv_flow_lang.system_message(''''RESTRICTED_NO_SET_FROM_BROWSER'''') d, ''''I'''' r',
'                  from sys.dual'';',
'    end if;',
'end loop;'))
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071.4001)
,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_lov_display_extra=>'NO'
,p_escape_on_http_input=>'N'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('Seleccione Protecci\00F3n de Estado de la Sesi\00F3n para este elemento:'),
'<ul>',
unistr('<li><strong>No Restringido</strong>: El elemento se puede definir transfiriendo el nombre o el valor del elemento en una direcci\00F3n URL o en una pantalla. No se necesita total de control en la direcci\00F3n URL.</li><br />       '),
unistr('<li><strong>Restringido: No se puede definir desde el explorador</strong>. El elemento no se puede modificar a trav\00E9s de la direcci\00F3n URL o POSTDATA. Utilice esta opci\00F3n cuando desee restringir la manera en que se puede definir el valor del elemento ')
||unistr('para procesos internos, c\00E1lculos, etc. Siempre se tiene en cuenta este atributo, aplicable s\00F3lo a elementos que no se pueden utilizar como elementos de entrada de datos, incluso si la protecci\00F3n de estado de la sesi\00F3n est\00E1 desactivada. Este atributo ')
||unistr('se puede utilizar para elementos de aplicaci\00F3n o para elementos de p\00E1gina con cualquiera de estos tipos "Mostrar como":'),
'<br />',
'<ul>',
unistr('<li>S\00F3lo Visualizaci\00F3n (No guarda el estado)</li>'),
'<li>Campo de Texto (Desactivado, no guarda el estado)</li>                          ',
unistr('<li>Parar e Iniciar Tabla HTML (Muestra s\00F3lo etiquetas)</li>'),
'</li></ul>',
unistr('<li><strong>Total de Control Necesario: Nivel de Aplicaci\00F3n</strong>: El elemento se puede definir transfiriendo el nombre o el valor del elemento en una direcci\00F3n URL si tambi\00E9n se proporciona un total de control espec\00EDfico del espacio de trabajo y ')
||unistr('la aplicaci\00F3n. Utilice esta opci\00F3n cuando desee que el elemento se pueda definir s\00F3lo mediante direcciones URL con totales de control generados por cualquier usuario que ejecute la misma aplicaci\00F3n en el espacio de trabajo actual pero en otra sesi\00F3n.')
||'</li>',
unistr('<li><strong>Total de Control Necesario: Nivel de Usuario</strong>: El elemento se puede definir transfiriendo el nombre o el valor del elemento en una direcci\00F3n URL si tambi\00E9n se proporciona un total de control espec\00EDfico del espacio de trabajo, la a')
||unistr('plicaci\00F3n y el usuario. Utilice esta opci\00F3n cuando desee que el elemento se pueda definir s\00F3lo mediante direcciones URL con totales de control generados por el mismo usuario designado que ejecute la misma aplicaci\00F3n en el espacio de trabajo actual pe')
||unistr('ro en otra sesi\00F3n.</li>      '),
unistr('<li><strong>Total de Control Necesario: Nivel de Sesi\00F3n</strong>: El elemento se puede definir transfiriendo el nombre o el valor del elemento en una direcci\00F3n URL si tambi\00E9n se proporciona un total de control espec\00EDfico de la sesi\00F3n actual. Utilice ')
||unistr('esta opci\00F3n cuando desee que el elemento se pueda definir s\00F3lo mediante direcciones URL con totales de control generados en la sesi\00F3n actual.</li>'),
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
