wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(203351726181564628.4001)
,p_name=>'P4307_GRID_TEMPLATE'
,p_item_sequence=>400
,p_item_plug_id=>wwv_flow_imp.id(131914703603.4001)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Plantilla de Contenedor'
,p_source=>'GRID_TEMPLATE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'PLUGIN_COM.ORACLE.APEX.CODE_EDITOR'
,p_cSize=>90
,p_cMaxlength=>4000
,p_cHeight=>15
,p_tag_attributes=>'onchange="htmldb_item_change(this)"'
,p_field_template=>wwv_flow_imp.id(561549716994252345.4001)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Especifica la marca para iniciar un nuevo dise\00F1o. Debe incluir al menos #ROWS# en esta plantilla. Se permiten las siguientes cadenas de sustituci\00F3n en la plantilla de contenedor:</p>'),
'<ul>',
unistr('<li><strong>#USED_COLUMNS_NUMBER#</strong>: N\00FAmero de columnas utilizadas. Por ejemplo: 1, 2, 3, ...</li>'),
unistr('<li><strong>#USED_COLUMNS_ALPHA#</strong>: Car\00E1cter alfab\00E9tico que representa el n\00FAmero de columnas utilizadas. Por ejemplo: a, b, c, ...</li>'),
unistr('<li><strong>#USED_COLUMNS_ALPHA_MINUS#</strong>: Car\00E1cter alfab\00E9tico que representa el n\00FAmero de columnas utilizadas que se reducen en una columna de cuadr\00EDcula. Por ejemplo, dos columnas de cuadr\00EDcula devolver\00E1n "a".</li>'),
unistr('<li><strong>#USED_COLUMNS_WORD#</strong>: Palabra que representa el n\00FAmero de columnas utilizadas. Por ejemplo: uno, dos, tres, ...</li>'),
unistr('<li><strong>#USED_COLUMNS_PLURAL#</strong>: Se sustituye por "s" si el n\00FAmero de columnas de cuadr\00EDcula es mayor que uno. Util\00EDcelo si el dise\00F1o necesita un nombre de clase "column" para una columna y "columns" si se especifican varias columnas. Por ')
||'ejemplo: class="#USED_COLUMNS_WORD# column#USED_COLUMNS_PLURAL#"</li>',
'<li><strong>#ROWS#</strong>: Sustituido por "Plantilla de Fila".</li>',
'</ul>',
'<p>',
'Ejemplo:',
'<pre>',
'&lt;div class="ui-grid-#USED_COLUMNS_ALPHA_MINUS#"&gt;#ROWS#&lt;/div&gt;',
'</pre>',
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'HTMLMIXED',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
);
