wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(203353124660580498.4001)
,p_name=>'P4307_GRID_COLUMN_TEMPLATE'
,p_item_sequence=>420
,p_item_plug_id=>wwv_flow_imp.id(131914703603.4001)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Plantilla de Columna'
,p_source=>'GRID_COLUMN_TEMPLATE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'PLUGIN_COM.ORACLE.APEX.CODE_EDITOR'
,p_cSize=>90
,p_cMaxlength=>4000
,p_cHeight=>15
,p_tag_attributes=>'onchange="htmldb_item_change(this)"'
,p_field_template=>wwv_flow_imp.id(561549716994252345.4001)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Especifica la marca para iniciar una nueva columna de dise\00F1o. Debe incluir al menos #CONTENT# en esta plantilla. Se permiten las siguientes cadenas de sustituci\00F3n en la plantilla de columna:</p>'),
'<ul>',
unistr('<li><strong>#COLUMN_NUMBER#</strong>: N\00FAmero de la columna. Por ejemplo: 1, 2, 3, ...</li>'),
unistr('<li><strong>#COLUMN_ALPHA#</strong>: Car\00E1cter alfab\00E9tico que representa la columna. Por ejemplo: a, b, c, ...</li>'),
'<li><strong>#COLUMN_WORD#</strong>: Palabra que representa la columna. Por ejemplo: uno, dos, tres, ...</li>',
unistr('<li><strong>#COLUMN_PLURAL#</strong>: Se sustituye por "s" si la columna es mayor que uno. Util\00EDcela si el dise\00F1o necesita un nombre de clase "column" para la primera columna y "columns" para las siguientes columnas. Por ejemplo: class="#COLUMN_WORD#')
||' column#COLUMN_PLURAL#"</li>',
unistr('<li><strong>#COLUMN_SPAN_NUMBER#</strong>: N\00FAmero de la ampliaci\00F3n de columna. Por ejemplo: 1, 2, 3, ...</li>'),
unistr('<li><strong>#COLUMN_SPAN_ALPHA#</strong>: Car\00E1cter alfab\00E9tico que representa la ampliaci\00F3n de columna . Por ejemplo: a, b, c, ...</li>'),
unistr('<li><strong>#COLUMN_SPAN_WORD#</strong>: Palabra que representa la ampliaci\00F3n de columna. Por ejemplo: uno, dos, tres, ...</li>'),
unistr('<li><strong>#COLUMN_SPAN_PLURAL#</strong>: Se sustituye por "s" si la ampliaci\00F3n de columna es mayor que uno. Util\00EDcela si el dise\00F1o necesita un nombre de clase "column" para la ampliaci\00F3n de una columna y "columns" si se especifican varias columnas.')
||' Por ejemplo: class="#COLUMN_SPAN_WORD# column#COLUMN_SPAN_PLURAL#"</li>',
unistr('<li><strong>#CSS_CLASSES#</strong>: se sustituye por el valor especificado como "Clases CSS de Columna". Esto permite personalizar a\00FAn m\00E1s una columna con clases CSS.</li>'),
unistr('<li><strong>#ATTRIBUTES#</strong>: Se sustituye por el valor especificado como "Atributos de Columna". Esto permite personalizar a\00FAn m\00E1s una columna.</li>'),
unistr('<li><strong>#FIRST_LAST_COLUMN_ATTRIBUTES#</strong>: Se sustituye por el valor especificado en "Atributos de Primera Columna" y "Atributos de \00DAltima Columna", dependiendo de si es la primera o la \00FAltima columna.</li>'),
unistr('<li><strong>#CONTENT#</strong>: Se sustituye por las regiones, elementos de p\00E1gina o botones que aparecen en la columna.</li>'),
'</ul>',
'<p>',
'Ejemplo:',
'<pre>',
'&lt;div class="#COLUMN_SPAN_WORD# column#COLUMN_SPAN_PLURAL# #CSS_CLASSES#"&gt;#CONTENT#&lt;/div&gt;',
'</pre>',
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'HTMLMIXED',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
);
