,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('Las opciones de marco del explorador de nivel de plantilla de p\00E1gina se muestran a continuaci\00F3n, junto con el valor actual para cada una.'),
unistr('Marque la casilla situada junto a un modo de p\00E1gina para utilizar este atributo y controlar si el explorador puede mostrar las p\00E1ginas de la aplicaci\00F3n dentro de un marco.'),
unistr('El valor actual ser\00E1 el valor por defecto para cada di\00E1logo modal y no modal que utilice esta plantilla de p\00E1gina.'),
'<p/>',
'<p>',
unistr('Esta opci\00F3n de visualizaci\00F3n de p\00E1ginas en marcos puede ser utilizada de forma indebida mediante ataques de "clickjacking" (secuestro de clic).'),
unistr('En este caso, el usuario no autorizado utiliza varias capas para enga\00F1ar a un usuario para que haga clic en un bot\00F3n o enlace a otra p\00E1gina cuando en realidad intentaba hacer clic en la p\00E1gina del nivel superior.'),
unistr('Es decir, el usuario no autorizado secuestra los clics (o las pulsaciones de teclas) que van a la p\00E1gina y las redirecciona a otra.'),
'<p/>',
'<p>',
unistr('&PRODUCT_NAME. embebe los di\00E1logos modales en iframes.'),
unistr('Si define el atributo de seguridad de la aplicaci\00F3n <em>Marco de explorador</em> en "Denegar",'),
unistr('al marcar <em>Permitir embeber en marco</em> para "Di\00E1logo modal" se utilizar\00E1 "Permitir del mismo origen" para las p\00E1ginas de di\00E1logo que utilizan esta plantilla. '),
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'number_of_columns', '1')).to_clob
,p_multi_value_type=>'SEPARATED'
,p_multi_value_separator=>':'
);
