'',
'<UL>',
'',
unistr('<LI>CURRENT_PAGE_NOT_EQUALS_CONDITION: el separador s\00F3lo aparecer\00E1 si la p\00E1gina actual no es la p\00E1gina especificada en el campo Condici\00F3n de Visualizaci\00F3n.</LI>'),
'',
unistr('<LI>CURRENT_PAGE_EQUALS_CONDITION: el separador s\00F3lo aparecer\00E1 si la p\00E1gina actual es la p\00E1gina especificada en el campo Condici\00F3n de Visualizaci\00F3n.</LI>'),
'',
unistr('<LI>CURRENT_PAGE_NOT_IN_CONDITION: el separador s\00F3lo aparecer\00E1 si la p\00E1gina actual no est\00E1 en la lista de p\00E1ginas especificadas en el campo Condici\00F3n de Visualizaci\00F3n (lista de p\00E1ginas separadas por comas).</LI>'),
'',
unistr('<LI>CURRENT_PAGE_IN_CONDITION: el separador s\00F3lo aparecer\00E1 si la p\00E1gina actual est\00E1 en la lista de p\00E1ginas especificadas en el campo Condici\00F3n de Visualizaci\00F3n (lista de p\00E1ginas separadas por comas).</LI>'),
'',
unistr('<LI>USER_IS_NOT_PUBLIC_USER: el separador s\00F3lo aparecer\00E1&nbsp;si el usuario actual no es el usuario p\00FAblico. No se necesita ninguna entrada en el campo Condici\00F3n de Visualizaci\00F3n.</LI>'),
'',
unistr('<LI>USER_IS_PUBLIC_USER: el separador s\00F3lo aparecer\00E1&nbsp;si el usuario actual es el usuario p\00FAblico. No se necesita ninguna entrada en el campo Condici\00F3n de Visualizaci\00F3n.</LI>'),
'',
unistr('<LI>EXISTS: el separador s\00F3lo aparecer\00E1 si la consulta del campo Condici\00F3n de Visualizaci\00F3n devuelve al menos una fila.</LI>'),
'',
unistr('<LI>ITEM_IS_NOT_NULL: el separador s\00F3lo aparecer\00E1 si el elemento identificado en el campo Condici\00F3n de Visualizaci\00F3n no es nulo.</LI>'),
'',
unistr('<LI>ITEM_IS_NULL:&nbsp;el separador s\00F3lo aparecer\00E1 si el elemento identificado en el campo Condici\00F3n de Visualizaci\00F3n es nulo.</LI>'),
'',
unistr('<LI>NOT_EXISTS: el separador s\00F3lo aparecer\00E1 si la consulta del campo Condici\00F3n de Visualizaci\00F3n no devuelve filas.</LI>'),
'',
unistr('<LI>PLSQL_EXPRESSION: el separador s\00F3lo aparecer\00E1 si la expresi\00F3n PL/SQL del campo Condici\00F3n de Visualizaci\00F3n se eval\00FAa como verdadera.</LI>'),
'',
