 p_id=>wwv_flow_imp.id(1434158563533350901.4001)
,p_name=>'P4404_COPY_FROM'
,p_is_required=>true
,p_item_sequence=>10
,p_item_plug_id=>wwv_flow_imp.id(1434158319547350901.4001)
,p_prompt=>unistr('Copiar de Aplicaci\00F3n')
,p_display_as=>'NATIVE_SELECT_LIST'
