' where f.security_group_id = :WORKSPACE_ID',
'   and exists ( select 1',
'                  from wwv_flow_plugins a',
'                 where ( a.flow_id, a.security_group_id ) in',
'                         ( ( f.id, :WORKSPACE_ID ),',
'                           ( ( select wwv_flow_theme_manager.get_central_application_id(',
'                                 p_application_id => f.id,',
'                                 p_theme_id       => f.theme_id ) from sys.dual ),',
'                             ( select wwv_flow_theme_manager.get_central_workspace_id(',
'                                 p_application_id => f.id,',
'                                 p_theme_id       => f.theme_id ) from sys.dual ) ) ) )',
'   and not exists ( select 1',
'                      from wwv_flow_language_map t',
'                     where t.translation_flow_id = f.id ',
'                       and t.security_group_id = :WORKSPACE_ID )',
' order by f.id'))
,p_lov_display_null=>'YES'
,p_lov_null_text=>unistr('- Seleccionar Aplicaci\00F3n -')
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(452656722938220607.4001)
,p_item_template_options=>'#DEFAULT#'
