wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(1340559765582198307.4001)
,p_name=>'Crear Plugin'
,p_template=>wwv_flow_imp.id(42025417508627628.4001)
,p_display_sequence=>20
,p_include_in_reg_disp_sel_yn=>'Y'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_item_display_point=>'BELOW'
,p_source_type=>'NATIVE_TABFORM'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with central_theme as (',
'    select wwv_flow_theme_manager.get_central_application_id( :P4404_COPY_FROM ) as application_id,',
'           wwv_flow_theme_manager.get_central_workspace_id( :P4404_COPY_FROM )   as workspace_id',
'      from sys.dual',
')',
'',
'select a.id,',
'       a.plugin_type,',
'       a.display_name,',
'       case when a.reference_id is not null then ''Y'' end as is_subscribed,',
'       case',
'         when a.reference_id is null and :P4404_COPY_FROM = :FB_FLOW_ID then wwv_flow_lang.system_message( ''F4000.P158.COPY_OF'', a.display_name )',
'         else display_name',
'       end as to_display_name,',
'       case',
'         when :P4404_COPY_FROM = :FB_FLOW_ID then ''N''',
'         when a.reference_id is not null       then ''Y''',
'         else ''SUBSCRIBE''',
'       end as action',
'  from wwv_flow_plugins a,',
'       central_theme ct',
' where ( a.flow_id, a.security_group_id ) in',
'       (',
'        ( :P4404_COPY_FROM, :WORKSPACE_ID ),',
'        ( ct.application_id, ct.workspace_id  )',
'       )',
'   and (',
'       -- Don''t show subscribed plug-ins, because they can''t be copied',
'          (   :P4404_COPY_FROM = :FB_FLOW_ID',
'          and (    reference_id is null',
'                or theme_id is not null )',
'          )',
'       -- Don''t show plug-ins which have already been copied from another application',
'       or (   :P4404_COPY_FROM <> :FB_FLOW_ID',
'              -- Same internal name',
'              and not exists ( select 1',
'                                 from wwv_flow_plugins b',
'                                where b.flow_id           = :FB_FLOW_ID',
'                                  and b.security_group_id = :WORKSPACE_ID',
'                                  and b.plugin_type       = a.plugin_type',
'                                  and b.name              = a.name',
'                                  and b.theme_id          is null',
'                             )',
'              -- Same internal name when removing the theme prefix',
'              and not exists ( select 1',
'                                 from wwv_flow_plugins b',
'                                where b.flow_id                 = :FB_FLOW_ID',
'                                  and b.security_group_id       = :WORKSPACE_ID',
'                                  and b.name                    = regexp_replace( a.name, ''^THEME_[[:digit:]]+\$'' )',
'                                  and a.theme_id                is not null',
'                                  and :P4406_COPY_TO_THEME_ID   is null',
'                             )',
'              -- Same internal name and theme',
'              and not exists ( select 1',
'                                 from wwv_flow_plugins b',
'                                where b.flow_id                 = :FB_FLOW_ID',
'                                  and b.security_group_id       = :WORKSPACE_ID',
'                                  and b.name                    = a.name',
'                                  and a.theme_id                = :P4406_COPY_TO_THEME_ID',
'                             )',
'          )',
'       )',
'   and ( ',
'        -- Only theme related plug-ins',
'            (      :P4406_COPY_FROM_THEME_ID is not null ',
'               and theme_id = :P4406_COPY_FROM_THEME_ID )',
'          or (     :P4406_COPY_FROM_THEME_ID is null ',
'               and theme_id is null )',
'        )',
'   and ( plugin_type = nvl( :P4406_PLUGIN_TYPE, plugin_type ) )',
' order by plugin_type, display_name'))
,p_header=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Identifique el plugin que desea copiar y seleccione la opci\00F3n de copia. Entre las opciones de copia se incluyen:</p>'),
'<ul>',
unistr('    <li><strong>S\00ED.</strong> Copiar el plugin.</li>'),
'    <li><strong>No.</strong> No copiar este plugin.</li>',
unistr('    <li><strong>Copiar y Suscribir.</Strong> La suscripci\00F3n a un plugin incluye una copia del mismo en la aplicaci\00F3n y define la referencia maestra del plugin.</li>'),
'</ul>',
''))
,p_ajax_enabled=>'Y'
,p_fixed_header=>'NONE'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(123728124628276646.4001)
,p_query_num_rows=>999
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_show_nulls_as=>'-'
,p_query_no_data_found=>unistr('No hay ning\00FAn plugin disponible o ya se han copiado todos.')
,p_csv_output=>'N'
