wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3053446993523770.4001)
,p_plug_name=>'Ayuda - Espacios'
,p_region_template_options=>'#DEFAULT#:js-dialog-size720x480'
,p_plug_template=>wwv_flow_imp.id(557449278618308550.4001)
,p_plug_display_sequence=>220
,p_plug_display_point=>'REGION_POSITION_05'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<ul>',
unistr('    <li>Si el componente de plantilla se utiliza en una regi\00F3n, mostrado como parcial, &PRODUCT_NAME. solo representar\00E1 los espacios de la plantilla parcial. Los efectos secundarios implican que no se puede refrescar de forma din\00E1mica y que no permit')
||'e la carga lenta.</li>',
unistr('    <li>Si el componente de plantilla se utiliza en una regi\00F3n, mostrado como informe, &PRODUCT_NAME. solo representar\00E1 los espacios de la plantilla de contenedor de informe. La plantilla de contenedor de informe est\00E1 alrededor de la plantilla de cue')
||'rpo de informe.</li>',
unistr('    <li>No es posible representar espacios en las filas de informe o columnas de informes interactivos, ya que el contenido de los espacios no est\00E1 dise\00F1ado para repetirse en la representaci\00F3n de la p\00E1gina.</li>'),
unistr('    <li>Existe la posibilidad de comprobar la existencia de contenido de espacios, de manera que podemos representar un marcado adicional si el espacio est\00E1 en uso. Ejemplo:'),
'        <pre><code>',
'            &lt;div class="outer-div"&gt;',
'            {if SLOT_A/}',
'            &lt;div class="inner-div"&gt;#SLOT_A#&lt;/div&gt;',
'            {endif/}',
'            &lt;/div&gt;',
'        </code></pre>',
'    </li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
