wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(48467930491898431.4001)
,p_name=>'Atributos Personalizados'
,p_region_name=>'CUST_ATTRIBUTES'
,p_template=>wwv_flow_imp.id(174794400314076650.4001)
,p_display_sequence=>100
,p_include_in_reg_disp_sel_yn=>'Y'
,p_region_template_options=>'#DEFAULT#:a-Region--noPadding'
,p_component_template_options=>'#DEFAULT#:a-Report--inline:a-Report--stretch'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select a.id,',
'       a.attribute_scope,',
'       a.display_sequence,',
'       a.static_id,',
'       a.prompt,',
'       a.is_required,',
'       a.default_value,',
'       a.attribute_type,',
'       case when dg.title is not null then dg.title || '' - '' end ||',
'       d.prompt as depending_on_prompt,',
'       ag.title as attribute_group_title',
'  from wwv_flow_plugin_attributes  a,',
'       wwv_flow_plugin_attributes  d,',
'       wwv_flow_plugin_attr_groups ag,',
'       wwv_flow_plugin_attr_groups dg',
' where a.plugin_id              = :P4410_ID',
'   and a.security_group_id      in ( :WORKSPACE_ID, 11, 12 )',
'   and d.id (+)                 = a.depending_on_attribute_id',
'   and ag.plugin_id         (+) = :P4410_ID',
'   and ag.security_group_id (+) in ( :WORKSPACE_ID, 11, 12 )',
'   and ag.id                (+) = a.attribute_group_id',
'   and dg.id                (+) = d.attribute_group_id',
'   and dg.security_group_id (+) = d.security_group_id',
' order by a.attribute_scope,',
'          ag.display_sequence asc nulls first,',
'          ag.id,',
'          a.display_sequence  asc,',
'          a.id'))
,p_display_when_condition=>'P4410_ID'
,p_display_condition_type=>'ITEM_IS_NOT_NULL'
,p_ajax_enabled=>'Y'
,p_fixed_header=>'NONE'
,p_lazy_loading=>false
