wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(2832908358618431.4001)
,p_name=>'P4410_TMPL_COMPONENT_TYPES'
,p_item_sequence=>150
,p_item_plug_id=>wwv_flow_imp.id(4004640729629327.4001)
,p_use_cache_before_default=>'NO'
