,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'YES'
,p_help_text=>unistr('<p>Utilice este campo para basar este plugin en un plugin existente en esta aplicaci\00F3n u otra aplicaci\00F3n del espacio de trabajo.</p>')
