,p_item_plug_id=>wwv_flow_imp.id(439386704233826730.4001)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Atributos:'
,p_source=>'P4410_STANDARD_ATTRIBUTES'
,p_source_type=>'ITEM'
,p_display_as=>'NATIVE_CHECKBOX'
,p_named_lov=>'PLUGIN.REGION_ATTRIBUTES'
,p_lov=>'.'||wwv_flow_imp.id(439394121736945367)||'.'
,p_field_template=>wwv_flow_imp.id(561547836135222071.4001)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('Para los plugins de tipo Regi\00F3n, seleccione lo siguiente para activar opciones como se describe aqu\00ED:'),
'</p>',
'<p>',
'<ul>',
unistr('<li>El origen de regi\00F3n es una sentencia SQL: el origen de regi\00F3n es una sentencia SQL. Si se activa, se puede especificar un n\00FAmero m\00EDnimo y m\00E1ximo de columnas que puede devolver la consulta y se muestran ejemplos de SQL para ayudar al usuario.</li>'),
unistr('<li>El origen de regi\00F3n es texto sin formato: el origen de regi\00F3n es texto sin formato.</li>'),
unistr('<li>Origen de regi\00F3n necesario: si el origen de regi\00F3n es una sentencia SQL, este atributo hace que \00E9ste sea un valor necesario.</li>'),
unistr('<li>Tiene atributo "Elementos de p\00E1gina que ejecutar": si el origen de regi\00F3n es una sentencia SQL, este atributo permite especificar los elementos de p\00E1gina que se deben definir en el estado de la sesi\00F3n al ejecutar una llamada Ajax para esa regi\00F3n.')
||'</li>',
unistr('<li>Tiene atributo "N\00FAmero de filas recuperadas": la regi\00F3n tiene los campos N\00FAmero de filas recuperadas en la secci\00F3n Avanzado al editar la regi\00F3n.</li>'),
unistr('<li>Tiene atributo "Mensaje No se ha encontrado ning\00FAn dato": la regi\00F3n tiene el campo Mensaje No se ha encontrado ning\00FAn dato en la secci\00F3n Avanzado al editar la regi\00F3n.</li>'),
unistr('<li>Tiene atributo "Caracteres especiales de escape": la regi\00F3n tiene el campo Caracteres especiales de escape en la secci\00F3n Seguridad cuando se edita la regi\00F3n.</li>'),
unistr('<li>Tiene "Columnas de regi\00F3n": la regi\00F3n permite especificar atributos personalizados adicionales para cada columna de la sentencia SQL de origen de la regi\00F3n.</li>'),
unistr('<li>Tiene atributo de columna "Cabecera": las columnas de la regi\00F3n tienen el campo Cabecera en la secci\00F3n Cabecera cuando se edita la columna.</li>'),
unistr('<li>Tiene atributo de columna "Alineaci\00F3n de cabecera": las columnas de la regi\00F3n tienen el campo Alineaci\00F3n en la secci\00F3n Cabecera cuando se edita la columna.</li>'),
unistr('<li>Tiene atributo de columna "Alineaci\00F3n": las columnas de la regi\00F3n tienen el campo Alineaci\00F3n de columna en la secci\00F3n Dise\00F1o cuando se edita la columna.</li>'),
unistr('<li>Tiene atributo de columna "Clases CSS": las columnas de la regi\00F3n tienen el campo Clases CSS en la secci\00F3n Apariencia cuando se edita la columna.</li>'),
unistr('<li>Tiene atributo de columna "Atributos personalizados": las columnas de la regi\00F3n tienen el campo Atributos personalizados en la secci\00F3n Avanzado cuando se edita la columna.</li>'),
unistr('<li>Tiene atributo de columna "Caracteres especiales de escape": las columnas de la regi\00F3n tienen el campo Caracteres especiales de escape en la secci\00F3n Seguridad cuando se edita la columna.</li>'),
unistr('<li>Tiene el atributo "C\00F3digo JavaScript de inicializaci\00F3n": el campo C\00F3digo JavaScript de inicializaci\00F3n est\00E1 disponible para la acci\00F3n.</li>'),
unistr('<li>Soporta b\00FAsqueda por facetas/filtros inteligentes: la regi\00F3n se puede conectar a una regi\00F3n de b\00FAsqueda por facetas o filtro inteligente. La opci\00F3n "El origen de regi\00F3n es una sentencia SQL" es necesaria.</li>'),
'</ul>',
'</p>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'number_of_columns', '1')).to_clob
,p_multi_value_type=>'SEPARATED'
,p_multi_value_separator=>':'
);
