unistr('<li>Para bot\00F3n: La acci\00F3n din\00E1mica soporta la selecci\00F3n de un bot\00F3n como elemento afectado.</li>'),
unistr('<li>Para regi\00F3n: La acci\00F3n din\00E1mica soporta la selecci\00F3n de una regi\00F3n como elemento afectado.</li>'),
