'with central_theme as (',
'    select wwv_flow_theme_manager.get_central_application_id( :FB_FLOW_ID, :P4410_THEME_ID ) as application_id,',
'           wwv_flow_theme_manager.get_central_theme_id( :FB_FLOW_ID, :P4410_THEME_ID )       as theme_id,',
'           wwv_flow_theme_manager.get_central_workspace_id( :FB_FLOW_ID, :P4410_THEME_ID )   as workspace_id',
'      from sys.dual',
')',
'select 1',
'  from wwv_theme_template_components tc,',
'       central_theme ct',
' where ( tc.flow_id, tc.theme_id, tc.security_group_id ) in',
'       (',
'        ( :FB_FLOW_ID, :P4410_THEME_ID, :WORKSPACE_ID ),',
'        ( ct.application_id, ct.theme_id, ct.workspace_id )',
'       )',
'   and tc.display_name  = :P4410_DISPLAY_NAME',
'   and tc.id           != :P4410_ID'))
,p_validation_type=>'NOT_EXISTS'
,p_error_message=>'#LABEL# must be unique.'
,p_validation_condition=>'P4410_PLUGIN_TYPE'
,p_validation_condition2=>'TEMPLATE COMPONENT'
,p_validation_condition_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
,p_associated_item=>wwv_flow_imp.id(27903506683734563.4001)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
