'begin',
'    -- delete all "Report" and "Report Group" attributes if the template component does not',
'    -- support "Multiple (Report)"',
'    if   :P4410_TMPL_COMPONENT_TYPES not like ''%REPORT%''',
'      or :P4410_TMPL_COMPONENT_TYPES is null',
'    then',
'        delete wwv_flow_plugin_attributes',
'         where plugin_id         = :P4410_ID',
'           and security_group_id = :WORKSPACE_ID',
'           and attribute_scope   in ( ''REPORT'', ''REPORT_GROUP'' );',
'    end if;',
'end;'))
