,p_item_sequence=>80
,p_item_plug_id=>wwv_flow_imp.id(20555148356507447.4001)
,p_item_source_plug_id=>wwv_flow_imp.id(14905826791797203.4001)
,p_prompt=>'Suscribirse desde'
,p_source=>'REFERENCE_ID'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_POPUP_LOV'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select b.flow_id ||'' ''||f.name||'' - ''|| b.display_name d,',
'       b.id r',
'  from wwv_flow_plugin_settings_dev b,',
'       wwv_flows f',
' where b.flow_id          != nvl(:FB_FLOW_ID,0)',
'   and b.flow_id           = f.id',
'   and f.build_status      not in (''RUN_ONLY'',''RUN_AND_HIDDEN'')',
'   and b.security_group_id = :WORKSPACE_ID',
'   and f.security_group_id = :WORKSPACE_ID',
'   -- limit to current plugin and plugin type',
'   and ((    b.plugin      = :P4446_PLUGIN',
'         and b.plugin_type = :P4446_PLUGIN_TYPE )',
'         -- always show selected master record',
'          or b.id = :P4446_REFERENCE_ID_INIT )',
'order by 1'))
,p_lov_display_null=>'YES'
,p_lov_null_text=>unistr('- Ninguna suscripci\00F3n -')
,p_lov_cascade_parent_items=>'P4446_PLUGIN,P4446_PLUGIN_TYPE,P4446_REFERENCE_ID_INIT'
,p_ajax_optimize_refresh=>'Y'
,p_cSize=>50
,p_field_template=>wwv_flow_imp.id(561547836135222071.4001)
,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_lov_display_extra=>'NO'
,p_help_text=>unistr('Seleccione un componente maestro desde el que suscribirse. Cuando seleccione un componente maestro y haga clic en el bot\00F3n <strong>Aplicar cambios</strong>, la configuraci\00F3n del componente se refrescar\00E1 autom\00E1ticamente a partir del maestro selecciona')
||unistr('do.<br /><br />Si la configuraci\00F3n del componente ya est\00E1 suscrita, haga clic en el bot\00F3n <strong>Refrescar configuraci\00F3n de componente</strong> para refrescar la configuraci\00F3n del componente a partir del componente maestro.')
