unistr('Tambi\00E9n puede activar roles a trav\00E9s de una llamada a <em>apex_authorization.enable_dynamic_groups</em>, p. ej., en un procedimiento posterior a la autenticaci\00F3n.')))
,p_encrypt_session_state_yn=>'N'
