wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(346057922272119929.4001)
,p_name=>'P4495_POST_AUTH_PROCESS'
,p_item_sequence=>260
,p_item_plug_id=>wwv_flow_imp.id(345924009281078364.4001)
,p_use_cache_before_default=>'NO'
,p_prompt=>unistr('Nombre del Procedimiento Posterior a la Autenticaci\00F3n')
,p_source=>'POST_AUTH_PROCESS'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_TEXT_FIELD'
,p_cSize=>64
,p_cMaxlength=>255
,p_field_template=>wwv_flow_imp.id(561547836135222071.4001)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('Especifique el nombre del procedimiento que ejecutar\00E1 el procedimiento de conexi\00F3n (API de conexi\00F3n) de &PRODUCT_NAME. despu\00E9s'),
unistr('del paso de autenticaci\00F3n (verificaci\00F3n de credenciales de conexi\00F3n). El procedimiento de conexi\00F3n ejecutar\00E1 este c\00F3digo despu\00E9s'),
unistr('de verificar las credenciales del usuario, pero antes de registrar el usuario en la sesi\00F3n y redireccionar a la'),
unistr('p\00E1gina de aplicaci\00F3n deseada. El procedimiento se puede definir en el atributo C\00F3digo PL/SQL o en la propia base de datos.</p>'),
'',
'<p>Por ejemplo, para transformar el nombre de usuario autenticado <code>JOHNDOE@EXAMPLE.COM</code> en',
unistr('<code>JOHNDOE</code>, defina el procedimiento <code>my_post_auth</code> en el atributo C\00F3digo PL/SQL:</p>'),
'<pre>',
'procedure my_post_auth',
'is',
'begin',
'  apex_custom_auth.set_user (',
'    p_user => regexp_replace(:APP_USER, ''@.*'', null) );',
'end my_post_auth;',
'</pre>',
'',
unistr('<p>A continuaci\00F3n, haga referencia a este procedimiento en el atributo Nombre de procedimiento de autenticaci\00F3n:</p>'),
'<pre>',
'my_post_auth',
'</pre>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'disabled', 'N',
  'send_on_page_submit', 'N',
  'submit_when_enter_pressed', 'N',
  'subtype', 'TEXT',
  'trim_spaces', 'NONE')).to_clob
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(346898909384210784.4001)
,p_name=>'P4495_SCHEME_TYPE'
,p_is_required=>true
,p_item_sequence=>40
,p_item_plug_id=>wwv_flow_imp.id(345889721617072434.4001)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Tipo de Esquema'
,p_source=>'SCHEME_TYPE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'AUTHENTICATION_SCHEME_TYPE'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select d,',
'       r',
'  from (',
'        select wwv_flow_lang.system_message(''AUTHENTICATION_NAME.''|| name_with_prefix) as d,',
'               name_with_prefix      as r',
'          from wwv_flow_native_plugins',
'         where plugin_type = ''AUTHENTICATION TYPE''',
'         union all',
'        select display_name || wwv_flow_lang.system_message(''PLUGIN.DISPLAY_NAME_POSTFIX'') as d,',
'               ''PLUGIN_'' || name     as r',
'          from wwv_flow_plugins',
'         where flow_id           = to_number(:FB_FLOW_ID)',
'           and security_group_id = to_number(:WORKSPACE_ID)',
'           and plugin_type       = ''AUTHENTICATION TYPE''',
'       )',
' order by 1'))
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(452656722938220607.4001)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'YES'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Seleccione c\00F3mo se aplicar\00E1 este esquema de autenticaci\00F3n. Est\00E1n soportados los siguientes tipos incorporados (se pueden ampliar con plugins):</p>'),
'<ul>',
unistr('    <li><strong>Inicio de sesi\00F3n de extensi\00F3n de creador</strong>: permite integrar esta aplicaci\00F3n con el entorno de desarrollo de APEX.</li>'),
unistr('    <li><strong>Personalizado</strong>: permite crear un esquema de autenticaci\00F3n personalizado desde cero, lo que le permite tener un control total sobre su interfaz de autenticaci\00F3n.</li>'),
unistr('    <li><strong>Cuentas de base de datos</strong>: este esquema de autenticaci\00F3n necesita que exista un usuario de base de datos (esquema) en la base de datos local. Al utilizar este m\00E9todo, el nombre de usuario y la contrase\00F1a de la cuenta de base d')
||'e datos se utilizan para autenticar el usuario.</li>',
unistr('    <li><strong>Variable de cabecera HTTP</strong>: autenticaci\00F3n externa, en la que el nombre de usuario se almacena en una variable de cabecera HTTP definida por el servidor web.</li>'),
unistr('    <li><strong>Extensi\00F3n a aplicaci\00F3n interna</strong>: utilice este esquema para las extensiones a aplicaciones internas.</li>'),
unistr('    <li><strong>Directorio LDAP</strong>: autenticaci\00F3n de usuario/contrase\00F1a con una solicitud de autenticaci\00F3n a un servidor LDAP.</li>'),
unistr('    <li><strong>Sin autenticaci\00F3n</strong>: adopta el usuario de base de datos actual.</li>'),
unistr('    <li><strong>Credenciales de puertas abiertas</strong> permite a cualquier usuario acceder a la aplicaci\00F3n mediante una p\00E1gina de conexi\00F3n que capture un nombre de usuario.</li>'),
unistr('    <li><strong>Cuentas de Oracle APEX</strong>: las credenciales de cuenta de &PRODUCT_NAME. son cuentas de usuario internas creadas y gestionadas en el repositorio de usuarios de &PRODUCT_NAME.. Al utilizar este m\00E9todo, la aplicaci\00F3n se autentica c')
||'on estas cuentas.</li>',
unistr('    <li><strong>Conexi\00F3n de SAML</strong>: soporta la autenticaci\00F3n con proveedores de identidad de SAML2.</li>'),
unistr('    <li><strong>Inicio de sesi\00F3n en medios sociales</strong>: soporta la autenticaci\00F3n con los proveedores de identidad Google, Facebook, OpenID Connect gen\00E9rico y OAuth2 gen\00E9rico.</li>'),
'</ul>'))
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
