,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('Seleccione <strong>Activado</strong> para activar el cambio del esquema de autenticaci\00F3n por defecto a este esquema en la sesi\00F3n de &PRODUCT_NAME. actual. Seleccione <strong>Desactivado</strong> si el esquema de autenticaci\00F3n no se debe activar en ti')
||unistr('empo de ejecuci\00F3n.'),
'</p><p>',
unistr('Si se activa, el esquema de autenticaci\00F3n de la sesi\00F3n actual se puede cambiar transfiriendo <strong>APEX_AUTHENTICATION=scheme name</strong> en un par\00E1metro de solicitud de URL.'),
'</p>',
'<h3>Ejemplo</h3>',
'<p>',
unistr('El desarrollador agrega un bot\00F3n con la etiqueta "Conectar con OAuth2" a la p\00E1gina de conexi\00F3n de la aplicaci\00F3n, lo que redirige a'),
'<pre>',
'f?p=&amp;APP_ID.:1:&amp;APP_SESSION.:APEX_AUTHENTICATION=OAuth2-Scheme',
'</pre>',
unistr('donde "OAuth2-Scheme" es el nombre del esquema de autenticaci\00F3n. Al procesar la solicitud (y asumiendo que "Cambiar en sesi\00F3n" est\00E1 activado), &PRODUCT_NAME. registra el esquema en la sesi\00F3n y lo utiliza para todas las solicitudes futuras.'),
'</p>',
'<p>',
'<strong>NOTA:</strong>',
unistr('Si la aplicaci\00F3n tiene un <em>procedimiento de configuraci\00F3n de autenticaci\00F3n</em>,'),
unistr('no es posible cambiar la autenticaci\00F3n mediante la URL.'),
'No obstante, este atributo debe definirse de todas formas.',
'</p>'))
,p_encrypt_session_state_yn=>'N'
