wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(3620655869.4001)
,p_name=>'F4000_P4653_TEMPLATE'
,p_item_sequence=>80
,p_item_plug_id=>wwv_flow_imp.id(164213211890458701.4001)
,p_use_cache_before_default=>'NO'
,p_prompt=>'Plantilla'
,p_source=>'TEMPLATE'
,p_source_type=>'DB_COLUMN'
,p_display_as=>'PLUGIN_COM.ORACLE.APEX.CODE_EDITOR'
,p_cSize=>80
,p_cMaxlength=>32767
,p_cHeight=>16
,p_tag_attributes=>'onchange="htmldb_item_change(this)"'
,p_field_template=>wwv_flow_imp.id(561549638722251517.4001)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<div class="htmldbInfoBodyP">Las plantillas de regi\00F3n proporcionan la apariencia de una parte de una p\00E1gina denominada regi\00F3n. Utilice cadenas de sustituci\00F3n para indicar la existencia y la ubicaci\00F3n de un componente dentro de la regi\00F3n.</div>'),
unistr('<div class="htmldbInfoBodyP">#BODY# es la \00FAnica cadena de sustituci\00F3n necesaria. Identifica el lugar donde se coloca el origen de la regi\00F3n. Todas las dem\00E1s cadenas de sustituci\00F3n son opcionales.</div>'),
unistr('<div class="htmldbInfoBodyP">Las siguientes son cadenas de sustituci\00F3n v\00E1lidas:'),
'<ul class="noIndent">',
'<li>#TITLE#</li>',
'<li>#PAGE_TITLE#</li>',
'<li>#EXPAND#</li>',
'<li>#CHANGE#</li>',
'<li>#BODY#</li>',
'<li>#SUB_REGION_HEADERS#</li>',
'<li>#SUB_REGIONS#</li>',
'<li>#FORM_OPEN#</li> ',
'<li>#FORM_CLOSE#</li>',
'<li>#REGION_ID#</li>',
'<li>#REGION_STATIC_ID#</li>',
'<li>#REGION_CSS_CLASSES#</li>',
'<li>#REGION_ATTRIBUTES#</li>',
'<li>#REGION_HEADER#</li>',
'<li>#REGION_FOOTER#</li>',
'<li>#REGION_IMAGE#</li>',
'<li>#REGION_IMAGE_URL#</li>',
'<li>#REGION_IMAGE_ALT_TEXT#</li>',
'<li>#REGION_IMAGE_ATTRIBUTES#</li>',
'<li>#REGION_LANDMARK_ATTRIBUTES#</li>',
'</ul>',
'</div>',
unistr('<div class="htmldbInfoBodyP">Tambi\00E9n puede utilizar las siguientes cadenas de sustituci\00F3n para especificar espacios de botones dentro de esta regi\00F3n:</div>'),
'<ul class="noIndent">',
'<li>#EDIT#</li>',
'<li>#CLOSE#</li>',
'<li>#CREATE#</li>',
'<li>#CREATE2#</li>',
'<li>#EXPAND#</li>',
'<li>#HELP#</li>',
'<li>#DELETE#</li>',
'<li>#COPY#</li>',
'<li>#NEXT#</li>',
'<li>#PREVIOUS#</li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'HTMLMIXED',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
);
