wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(73941510767235924.4001)
,p_validation_name=>'unique template name'
,p_validation_sequence=>40
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with central_theme as (',
'    select wwv_flow_theme_manager.get_central_application_id( :FB_FLOW_ID, :P4653_THEME ) as application_id,',
'           wwv_flow_theme_manager.get_central_theme_id( :FB_FLOW_ID, :P4653_THEME )       as theme_id,',
'           wwv_flow_theme_manager.get_central_workspace_id( :FB_FLOW_ID, :P4653_THEME )   as workspace_id',
'      from sys.dual',
')',
'',
'select 1',
'  from wwv_flow_page_plug_templates ppt,',
'       central_theme ct',
' where ( ppt.flow_id, ppt.theme_id, ppt.security_group_id ) in',
'       (',
'        ( :FB_FLOW_ID, :P4653_THEME, :WORKSPACE_ID ),',
'        ( ct.application_id, ct.theme_id, ct.workspace_id )',
'       )',
'   and ppt.page_plug_template_name = :F4000_P4653_REGION_TEMPL_NAME',
'   and ppt.id                     != :F4000_P4653_ID'))
,p_validation_type=>'NOT_EXISTS'
,p_error_message=>unistr('#LABEL# debe ser un valor \00FAnico.')
,p_when_button_pressed=>wwv_flow_imp.id(3612655867.4001)
,p_associated_item=>wwv_flow_imp.id(3619655869.4001)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
