,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>Seleccione un principal de navegaci\00F3n para la nueva p\00E1gina. Al crear un nuevo elemento de navegaci\00F3n, el nuevo elemento enlaza a'),
