);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3185079872144510.4001)
,p_plug_name=>'Acerca de las copias de trabajo'
,p_region_css_classes=>'padding-left-md padding-right-md'
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody:a-Region--noBorder:a-Region--hideHeader'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4001)
,p_plug_display_sequence=>10
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<h3>Consejos</h3>',
'<ul>',
'    <li>Los desarrolladores pueden utilizar diferentes copias de trabajo. Para evitar que se sobrescriban o se produzcan errores al fusionar:',
'        <ul>',
unistr('            <li>Bloquee una p\00E1gina en la aplicaci\00F3n principal antes de modificarla en una copia de trabajo</li>'),
unistr('            <li>Reserve rangos de p\00E1gina para las p\00E1ginas nuevas que cree cada desarrollador</li>'),
'            <li>Acuerde los nombres de componentes compartidos que agregue cada desarrollador</li>',
'        </ul>',
'    </li>',
'    <li>Exporte una copia de trabajo cuando sea necesario utilizando los <em>ID originales</em> para mantener el enlace con la principal</li>',
unistr('    <li><em>Desenlace</em> una copia de trabajo de la principal mediante la tarea <em>Copiar aplicaci\00F3n</em></li>'),
unistr('    <li>Suprima las copias de trabajo <em>antes</em> de suprimir una aplicaci\00F3n</li>'),
'</ul>',
'<h3>Tipos de componentes no soportados</h3>',
unistr('<p>Estos tipos de componentes a\00FAn no est\00E1n soportados para la fusi\00F3n <em>autom\00E1tica</em>:'),
unistr('   Traducciones, temas, plantillas de tema, objetos de soporte, propiedades de aplicaci\00F3n, separadores (heredados) y'),
'   componentes de nivel de espacio de trabajo, como grupos de aplicaciones, credenciales o servidores remotos. Puede fusionar la copia de trabajo y,',
unistr('   a continuaci\00F3n, aplicar manualmente las adiciones o cambios a estos tipos de componentes.'),
'</p>',
'<h3>Limitaciones</h3>',
'<p>Las copias de trabajo tienen las limitaciones siguientes:</p>',
'<ul>',
'    <li>No puede crear una copia de trabajo de una copia de trabajo</li>',
unistr('    <li>Las p\00E1ginas o los componentes compartidos de copias de trabajo suprimidos deben suprimirse <em>manualmente</em> en la principal</li>'),
'    <li>Es posible que los componentes que <em>falten</em> se hayan eliminado en la copia de trabajo o solo existan en la principal</li>',
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
end;
