,p_process_name=>'Initialize Hidden Items'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'',
'    select to_char( last_updated_on, ''YYYY.MM.DD HH24:MI:SS'' ), ',
'           last_updated_by, ',
'           decode( ',
'               last_updated_on, ',
'               null, ''u-hidden'' )',
'      into :P5335_LEFT_UPDATED_ON, ',
'           :P5335_LEFT_UPDATED_BY, ',
'           :P5335_LEFT_UPDATED_DISP_CLS',
'      from wwv_flow_steps',
'     where flow_id            = :FB_FLOW_ID',
'       and id                 = :P5335_EXPORT_PAGE_ID',
'       and security_group_id  = :WORKSPACE_ID;',
'',
'    select to_char( last_updated_on, ''YYYY.MM.DD HH24:MI:SS'' ), ',
'           last_updated_by, ',
'           decode( ',
'               last_updated_on, ',
