'           from wwv_flow_appl_export_comps c',
'          where c.workspace_id   = :WORKSPACE_ID',
'            and c.application_id = :FB_FLOW_ID',
'            and c.type_name      = s.component_type',
'            and c.id             = s.component_id ) component,',
'       ( select sc.subscription_status',
'           from wwv_flow_subscribed_comp_dev sc',
'          where sc.component_type = s.component_type',
'            and sc.component_id   = s.component_id',
'            and sc.application_id = :FB_FLOW_ID ) subscription_status',
'  from wwv_flow_comp_grp_components s',
