wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(4800456594119504.4001)
,p_plug_name=>'Automatizaciones'
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4001)
,p_plug_display_sequence=>70
,p_plug_display_point=>'REGION_POSITION_03'
,p_plug_item_display_point=>'BELOW'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('Las <strong>automatizaciones</strong> inician un juego secuencial de procesos. Se utilizan para supervisar datos y, posteriormente, realizar la acci\00F3n adecuada (por ejemplo, la aprobaci\00F3n autom\00E1tica de solicitudes espec\00EDficas y el env\00EDo de alertas de')
||unistr(' correo electr\00F3nico).'),
'</p>',
'<p>',
unistr('Las <strong>acciones de automatizaci\00F3n</strong> se disparan una vez por cada fila devuelta por el origen de automatizaci\00F3n. Una acci\00F3n puede hacer referencia a los valores de cada columna para cada fila usando la sintaxis de variable de enlace.</p>'),
'<p>',
unistr('Despu\00E9s de <em>importar</em> una aplicaci\00F3n, se <em>desactivar\00E1n</em> las automatizaciones para evitar que se ejecuten varias a la vez. La automatizaci\00F3n debe estar activada, en esta p\00E1gina o con el paquete <strong>APEX_AUTOMATION</strong>.</p>'),
unistr('<p><a target="_blank" href="&SYSTEM_HELP_URL.">M\00E1s informaci\00F3n ...</a></p>'),
''))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
