,p_validation_condition2=>'PLSQL'
,p_validation_condition_type=>'EXPRESSION'
,p_associated_item=>wwv_flow_imp.id(2503723575513160.4001)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(1402989705294846.4001)
,p_validation_name=>'Minimum Execution Cadence met'
,p_validation_sequence=>130
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    return wwv_flow_automation_dev.get_execution_cadence_minutes( ',
'               p_calendaring_expression => :P7021_POLLING_INTERVAL ) >= to_number( :P7021_MIN_CADENCE );',
'exception',
'    when others then',
'        -- syntax errors in the calendaring expression are catched in the',
'        -- "Polling Interval is Valid" validation',
'        return true;',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>'Las automatizaciones no se pueden ejecutar con una frecuencia superior a cada &P7021_MIN_CADENCE!HTML. minutos.'
,p_validation_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
':REQUEST              in ( ''SAVE'', ''CREATE'', ''PLAY'' ) and ',
':P7021_POLLING_STATUS =  ''ACTIVE'' and ',
':P7021_TRIGGER_TYPE   =  ''POLLING'' and ',
'wwv_flow_platform.get_preference(''BACKGROUND_MIN_EXECUTION_CADENCE'') is not null'))
,p_validation_condition2=>'PLSQL'
,p_validation_condition_type=>'EXPRESSION'
,p_associated_item=>wwv_flow_imp.id(2503723575513160.4001)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
