wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1409356763910720.4001)
,p_name=>'P7022_ACTION_TYPE'
,p_source_data_type=>'VARCHAR2'
,p_is_required=>true
,p_item_sequence=>50
,p_item_plug_id=>wwv_flow_imp.id(1410170163910728.4001)
,p_item_source_plug_id=>wwv_flow_imp.id(1410170163910728.4001)
,p_item_default=>'NATIVE_PLSQL'
,p_prompt=>'Tipo'
,p_source=>'ACTION_TYPE'
,p_source_type=>'REGION_SOURCE_COLUMN'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select d,',
'       r',
'  from (',
'         select wwv_flow_lang.system_message(''PROCESS.''|| name_with_prefix) as d,',
'               name_with_prefix as r',
'          from wwv_flow_native_plugins',
'         where plugin_type               = ''PROCESS TYPE''',
'           and supported_component_types like ''%APEX_APPL_AUTOMATION_ACTIONS%''',
'           and ( ( select wwv_flow_f4000_util.is_cloud',
'                     from sys.dual ) = ''Y''',
'                  or name != ''GEOCODING'' )',
'         union all',
'        select display_name || wwv_flow_lang.system_message(''PLUGIN.DISPLAY_NAME_POSTFIX'') as d,',
'               ''PLUGIN_'' || name     as r',
'          from wwv_flow_plugins',
'         where flow_id                   = to_number(:FB_FLOW_ID)',
'           and security_group_id         = to_number(:WORKSPACE_ID)',
'           and plugin_type               = ''PROCESS TYPE''',
'           and supported_component_types like ''%APEX_APPL_AUTOMATION_ACTIONS%''',
'       )',
' order by 1'))
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(452656722938220607.4001)
,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_lov_display_extra=>'NO'
,p_help_text=>unistr('Seleccione el tipo de acci\00F3n.')
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1409543908910722.4001)
,p_name=>'P7022_REMOTE_PLSQL_CODE'
,p_item_sequence=>20
,p_item_plug_id=>wwv_flow_imp.id(90116067165448609.4001)
,p_prompt=>unistr('C\00F3digo PL/SQL (se ejecuta en el servicio de SQL activado para REST)')
,p_display_as=>'PLUGIN_COM.ORACLE.APEX.CODE_EDITOR'
,p_cSize=>80
,p_cMaxlength=>32767
,p_cHeight=>10
,p_field_template=>wwv_flow_imp.id(561549638722251517.4001)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Proporcione el c\00F3digo PL/SQL que se va a ejecutar. Los valores de las columnas de la consulta de automatizaci\00F3n est\00E1n disponibles como variables de enlace, por nombre de columna, por ejemplo <strong>:EMPNO</strong>, <strong>:ENAME</strong>, etc. ')
||unistr('Adem\00E1s, APEX proporciona las siguientes variables de enlace gen\00E9ricas:'),
'</p>',
'<ul>',
'    <li><strong>APEX$AUTOMATION_ROW_PK</strong>: si se ha definido una columna de clave primaria, esta variable de enlace contiene el valor de la clave primaria.</li>',
unistr('  <li><strong>APEX$AUTOMATION_ROW_NUM</strong>: para las automatizaciones basadas en una consulta, esta variable de enlace contiene el n\00FAmero de fila actual.</li>'),
unistr(' <li><strong>APEX$AUTOMATION_ERROR_ROWS</strong>: para las automatizaciones basadas en una consulta, esta variable de enlace contiene el n\00FAmero de filas en las que las acciones han producido errores.</li>'),
unistr('      <li><strong>APEX$AUTOMATION_LASTRUN_ISO</strong>: contiene el registro de hora de la ejecuci\00F3n de la automatizaci\00F3n <em>anterior</em>, con el formato <strong>AAAA-MM-DD"T"HH24:MI:SS.FF3TZH:TZM</strong>.</li>      '),
'</ul>',
'<p style="padding-top: 10px">',
unistr('    Tenga en cuenta que el paquete <strong>APEX_AUTOMATION</strong> podr\00EDa no estar disponible en el servicio SQL activado para REST. Para agregar mensajes al log de ejecuci\00F3n (<strong>LOG_WARN</strong>, <strong>LOG_INFO</strong>, <strong>LOG_ERROR</')
||unistr('strong>), cree <em>otra</em> acci\00F3n que se ejecute en la <em>base de datos local.</em>'),
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'PLSQL',
  'attribute_02', 'VARCHAR2',
  'attribute_03', 'Y',
  'attribute_04', 'Y',
  'attribute_05', 'P7022_REMOTE_SERVER_ID',
  'attribute_07', 'N')).to_clob
);
