,p_autocomplete_on_off=>'OFF'
,p_group_id=>wwv_flow_imp.id(91429205691059841)
,p_step_template=>wwv_flow_imp.id(386677207130845076.4001)
,p_page_template_options=>'#DEFAULT#'
);
wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(496821048397304133.4001)
,p_plug_name=>'Historial de &P7100_SOURCE_TYPE_TITLE_SIN.'
,p_region_template_options=>'#DEFAULT#:a-Region--noPadding'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(646287526247383209.4001)
,p_plug_display_sequence=>20
,p_include_in_reg_disp_sel_yn=>'Y'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select t.flow_user developer, ',
'       t.audit_date,',
'       decode(audit_action,',
'              ''I'',i.a,',
'              ''D'',d.a,',
'              u.a) action,',
'       SCN,',
'       audit_comment,',
'       FLOW_TABLE_PK component_key,',
'       t.object_name component_name',
'  from wwv_flow_builder_audit_trail t,',
'       (select wwv_flow_lang.system_message(''F4350.CREATE'') a from dual) i,',
'       (select wwv_flow_lang.system_message(''F4350.DELETE'') a from dual) d,',
'       (select wwv_flow_lang.system_message(''F4350.CHANGE'') a from dual) u',
' where t.flow_ID = :FB_FLOW_ID and',
