wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(3435840249106110.4001)
,p_name=>unistr('Uso de Cach\00E9')
,p_parent_plug_id=>wwv_flow_imp.id(2225959451748413.4001)
,p_template=>wwv_flow_imp.id(174794400314076650.4001)
,p_display_sequence=>10
,p_region_template_options=>'#DEFAULT#:a-Region--noPadding'
,p_component_template_options=>'#DEFAULT#:a-BadgeList--fixed:a-BadgeList--large'
,p_display_point=>'SUB_REGIONS'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select case when cache_type = ''ALL_USERS'' then nvl(cache_entry_count,0) else 0 end as ALL_USERS_COUNT,',
'       case when cache_type = ''USER''      then nvl(cache_entry_count,0) else 0 end as BY_USER_COUNT,',
'       case when cache_type = ''SESSION''   then nvl(cache_entry_count,0) else 0 end as BY_SESSION_COUNT',
'  from (',
'        select case when user_name is     null and session_id is null then ''ALL_USERS''',
'                    when user_name is not null and session_id is null then ''USER''',
'                    when session_id is not null                       then ''SESSION''',
'               end as cache_type,',
'               count(*) as cache_entry_count',
'          from wwv_flow_content_cache1$',
'         where security_group_id = :FLOW_SECURITY_GROUP_ID',
'           and flow_id           = :FB_FLOW_ID',
'           and component_id      = :P7110_ID',
'         group by user_name, session_id )',
'',
''))
,p_display_when_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select 1',
'  from wwv_flow_content_cache1$',
' where security_group_id = :FLOW_SECURITY_GROUP_ID',
'   and flow_id           = :FB_FLOW_ID',
'   and component_id      = :P7110_ID'))
,p_display_condition_type=>'EXISTS'
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(1041640454953406573.4001)
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_plug_query_strip_html=>'N'
);
