wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(2787302350432735.4001)
,p_plug_name=>unistr('Acerca de: or\00EDgenes JSON')
,p_title=>'Acerca de'
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody:a-Region--sideRegion:a-Region--noBorder'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4001)
,p_plug_display_sequence=>30
,p_plug_display_point=>'REGION_POSITION_03'
,p_plug_item_display_point=>'BELOW'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Los <strong>or\00EDgenes JSON</strong> de &PRODUCT_NAME. consisten en informaci\00F3n de la persona responsable y el nombre '),
unistr('    de una tabla de base de datos, que puede ser una <em>tabla de recopilaci\00F3n de JSON</em> o una tabla plana con columnas que contienen '),
unistr('    datos de JSON. Las <em>tablas de recopilaci\00F3n de JSON</em> est\00E1n disponibles en Oracle Database 23ai o posterior. Adem\00E1s,'),
'    se mantiene un <strong>perfil de datos</strong> que asigna',
'    atributos JSON a <em>columnas</em> para su consumo por parte de los componentes de &PRODUCT_NAME..',
'</p>',
'<p> ',
'    Puede definir un origen JSON mediante el uso de la base de datos local y un servicio',
unistr('    de SQL activado para REST. Despu\00E9s de seleccionar la tabla y la columna que se van a utilizar, &PRODUCT_NAME. determina el perfil de datos'),
'    a partir de los datos reales, o a partir de un archivo de <em>esquema JSON</em> cargado.',
'</p>',
'<p>',
unistr('    Una vez creado, el origen JSON estar\00E1 disponible para componentes de p\00E1gina como <em>informes</em>, <em>gr\00E1ficos</em> y '),
unistr('    <em>formularios</em>, entre otros, as\00ED como para componentes compartidos como <em>listas de valores</em>, <em>automatizaciones</em>'),
unistr('    u otros. El paquete PL/SQL APEX_EXEC permite un acceso program\00E1tico.'),
'</p>',
unistr('<p><a target="_blank" href="&SYSTEM_HELP_URL.">M\00E1s informaci\00F3n...</a></p>')))
,p_plug_display_condition_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
,p_plug_display_when_condition=>'P7100_SOURCE_TYPE'
,p_plug_display_when_cond2=>'JSON_TABLE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_plug(
