,p_lov_display_null=>'YES'
,p_lov_null_text=>unistr('Sin almacenamiento en cach\00E9')
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(561547836135222071.4001)
,p_item_template_options=>'#DEFAULT#'
,p_is_persistent=>'N'
,p_lov_display_extra=>'NO'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Seleccione el modo en el que el motor de &PRODUCT_NAME. puede almacenar en cach\00E9 respuestas de origen de REST en el servidor. Si se puede utilizar el almacenamiento en cach\00E9, el componente se representar\00E1 en funci\00F3n de los resultados almacenados ')
||unistr('en cach\00E9 en lugar de recuperarlos del servicio web de nuevo. Solo se almacenar\00E1n en cach\00E9 las solicitudes HTTP "GET", que reducir\00E1n las solicitudes HTTP caras. Esta funci\00F3n no est\00E1 relacionada con las capacidades de almacenamiento en cach\00E9 del explor')
||'ador.</p>',
'<p>',
'    Las opciones disponibles incluyen:',
'</p>',
'<ul>',
unistr('    <li><strong>Desactivado</strong>: el contenido no se almacena en cach\00E9 ni se recupera del origen de REST para cada solicitud.</li>'),
unistr('    <li><strong>Para todos los usuarios</strong>: el contenido se almacena en cach\00E9 y todos los usuarios lo utilizan.</li>'),
unistr('    <li><strong>Por usuario</strong>: el contenido se almacena en cach\00E9 espec\00EDficamente para cada usuario.</li>'),
unistr('    <li><strong>Por sesi\00F3n</strong>: el contenido se almacena en cach\00E9 espec\00EDficamente para cada sesi\00F3n.</li>'),
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
