wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(2131150797906342.4001)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Consolidate Items'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    :P7120_SRC_OWNER := case :P7120_LOCATION',
'                            when ''LOCAL''  then :P7120_LOCAL_OWNER',
'                            when ''REMOTE'' then :P7120_REMOTE_OWNER',
'                        end;',
'    :P7120_SRC_NAME  := case :P7120_LOCATION',
'                            when ''LOCAL'' then',
'                                case when :P7120_SOURCE_TYPE = ''DUALITY_VIEW'' ',
'                                     then :P7120_LOCAL_DUALITY_VIEW',
'                                     when :P7120_SOURCE_TYPE = ''JSON_TABLE'' and :P7120_DOC_SOURCE_TYPE = ''JSON_TABLE''',
'                                     then :P7120_LOCAL_JSON_TABLE',
'                                     when :P7120_SOURCE_TYPE = ''JSON_TABLE'' and :P7120_DOC_SOURCE_TYPE = ''JSON_COLLECTION''',
'                                     then :P7120_LOCAL_JSON_COLLECTION',
'                                end',
'                            when ''REMOTE'' then',
'                                case when :P7120_SOURCE_TYPE = ''DUALITY_VIEW'' ',
'                                     then :P7120_REMOTE_DUALITY_VIEW',
'                                     when :P7120_SOURCE_TYPE = ''JSON_TABLE'' and :P7120_DOC_SOURCE_TYPE = ''JSON_TABLE''',
'                                     then :P7120_REMOTE_JSON_TABLE',
'                                     when :P7120_SOURCE_TYPE = ''JSON_TABLE'' and :P7120_DOC_SOURCE_TYPE = ''JSON_COLLECTION''',
'                                     then :P7120_REMOTE_JSON_COLLECTION',
'                                end',
'                        end;',
'    :P7120_SRC_TYPE  := case when :P7120_SOURCE_TYPE = ''DUALITY_VIEW''',
'                             then wwv_flow_exec_doc_src.c_doc_source_duality_view',
'                             when :P7120_SOURCE_TYPE = ''JSON_TABLE'' and :P7120_DOC_SOURCE_TYPE = ''JSON_TABLE''',
'                             then wwv_flow_exec_doc_src.c_doc_source_json_column',
'                             when :P7120_SOURCE_TYPE = ''JSON_TABLE'' and :P7120_DOC_SOURCE_TYPE = ''JSON_COLLECTION''',
'                             then wwv_flow_exec_doc_src.c_doc_source_collection',
'                        end;',
'end;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(2140726147932534.4001)
,p_internal_uid=>2131150797906342.4001
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(2131594320906346.4001)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Discover into Collection'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_json_schemas         wwv_flow_t_clob := wwv_flow_t_clob();',
'    l_uploaded_json_schema blob;',
'begin',
'    wwv_flow_collection.create_or_truncate_collection( ''DATA_PROFILE'' );',
'',
'    if :P7120_UPLOAD_JSON_SCHEMA is not null then',
'',
'        select blob_content',
'          into l_uploaded_json_schema',
'          from wwv_flow_temp_files',
'         where name = :P7120_UPLOAD_JSON_SCHEMA;',
'',
'        l_json_schemas.extend( 1 );',
'        l_json_schemas( 1 ) := wwv_flow_utilities.blob_to_clob(',
'                                   p_blob       => l_uploaded_json_schema,',
'                                   p_cache      => true,',
'                                   p_dur        => sys.dbms_lob.call );',
'',
'    end if;',
'',
'    wwv_flow_doc_src_dev.discover(',
'        p_source_type       => :P7120_SRC_TYPE,',
'        p_location          => :P7120_LOCATION,',
'        p_remote_server_id  => :P7120_REMOTE_SERVER_ID,',
'        p_object_owner      => :P7120_SRC_OWNER,',
'        p_object_name       => :P7120_SRC_NAME,',
'        p_json_schemas      => l_json_schemas );',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(2140726147932534.4001)
,p_process_when=>':P7120_DOC_SOURCE_TYPE = ''JSON_COLLECTION'' or :P7120_SOURCE_TYPE = ''DUALITY_VIEW'''
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_internal_uid=>2131594320906346.4001
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(4482251583841405.4001)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load Columns into Collection'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    if     :P7120_DOC_SOURCE_TYPE = ''JSON_TABLE'' ',
'       and :P7120_LOCATION = ''REMOTE'' ',
'       and :P7120_REMOTE_JSON_TABLE is not null ',
'    then',
'        select json_arrayagg( json_object( key ''d'' value d, key ''r'' value r ) returning clob) ',
'          into :P7120_COLUMNS_JSON',
'          from (',
'                 select column_value d, column_value r',
'                   from table( wwv_flow_remote_server_dev.get_available_objects( ',
'                                   p_remote_server_id   => :P7120_REMOTE_SERVER_ID, ',
'                                   p_object_type        => ''COLUMNS'',',
'                                   p_owner              => :P7120_REMOTE_OWNER,',
'                                   p_filter             => :p$_search_string,',
'                                   p_parent_object_name => :P7120_REMOTE_JSON_TABLE ))',
'                  order by 1 );',
'    elsif  :P7120_DOC_SOURCE_TYPE = ''JSON_TABLE'' ',
'       and :P7120_LOCATION = ''LOCAL'' ',
'       and :P7120_LOCAL_JSON_TABLE is not null ',
'    then',
'        select json_arrayagg( json_object( key ''d'' value d, key ''r'' value r ) returning clob ) ',
'          into :P7120_COLUMNS_JSON',
'          from (',
'                 select column_name_esc d,',
'                        column_name r',
'                   from wwv_flow_table_columns_dev',
'                  where owner = (select coalesce( :P7120_LOCAL_OWNER, wwv_flow_wizard_api.get_flow_owner(:FB_FLOW_ID)) ',
'                                   from sys.dual )',
'                    and table_name = :P7120_LOCAL_JSON_TABLE',
'                    and data_type in ( ''JSON'', ''CLOB'', ''BLOB'', ''VARCHAR2'' )',
'                  order by case when data_type = ''JSON'' then 1 ',
'                                when data_type = ''CLOB'' then 2',
'                                when data_type = ''VARCHAR2'' then 3',
'                                else 4 ',
'                           end asc, column_name asc );',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(2140726147932534.4001)
,p_process_when=>':P7120_DOC_SOURCE_TYPE = ''JSON_TABLE'''
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_internal_uid=>4482251583841405.4001
);
end;
