wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(1803566355407926.4001)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'DONE'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_message varchar2(1000);',
'    l_count   number;',
'begin',
'    -- clear out the exec id so the page knows to hide the progress bar.',
'    :P8115_EXEC_ID := NULL;',
'',
'    if :P8115_STATE = ''FAILED'' then',
'        l_message := :P8115_MESSAGE;',
'    -- set the success message depending upon the Options and Scope selected on page 8116',
'    elsif :P8116_OPTIONS = ''ERRORS'' then ',
'        -- just looking for errors         ',
'        if :P8116_SCOPE = ''PAGE'' then',
'            select count(*)',
'              into l_count',
'              from wwv_used_db_object_comp_props',
'             where flow_id = :FB_FLOW_ID',
'               and security_group_id = :WORKSPACE_ID',
'               and error_message is not null',
'               and page_id = :P8116_PAGE_ID',
'               and rownum = 1;',
'',
'            -- only inform the user if no errors were found so they know things were checked',
'            if l_count = 0 then ',
'                l_message := wwv_flow_lang.system_message(''DEP.NO_ERRORS_PAGE'', :P8116_PAGE_ID);',
'            end if;',
'        else',
'            -- see if any errors were found for the entire application. If not then infomr the user.',
'            select count(*)',
'              into l_count',
'              from wwv_used_db_object_comp_props',
'             where flow_id = :FB_FLOW_ID',
'               and security_group_id = :WORKSPACE_ID',
'               and error_message is not null',
'               and rownum = 1;',
'',
'            -- only inform the user if no errors were found so they know things were checked',
'            if l_count = 0 then ',
'                l_message := wwv_flow_lang.system_message(''DEP.NO_ERRORS'');',
'            end if;               ',
'        end if;',
'    else',
'        -- scan the entire app',
'        if :P8116_SCOPE = ''PAGE'' then ',
'            select count(*) ',
'              into l_count',
'              from wwv_used_db_obj_dependencies',
'             where flow_id = :FB_FLOW_ID',
'               and security_group_id = :WORKSPACE_ID',
'               and page_id = :P8116_PAGE_ID',
'               and rownum = 1;',
'',
'            if l_count = 0 then ',
'                l_message := wwv_flow_lang.system_message(''DEP.NO_DEPENDENCIES_PAGE'', :P8116_PAGE_ID);',
'            end if;                      ',
'        else',
'            select count(*) ',
'              into l_count',
'              from wwv_flow_used_db_objects',
'             where flow_id = :FB_FLOW_ID',
'               and security_group_id = :WORKSPACE_ID',
'               and usage_count > 0',
'               and rownum = 1;',
'',
'            if l_count = 0 then ',
'                l_message := wwv_flow_lang.system_message(''DEP.NO_DEPENDENCIES'');',
'            end if;                  ',
'        end if;',
'    end if;',
'',
'    wwv_flow.g_print_success_message := l_message;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'DONE'
,p_process_when_type=>'REQUEST_EQUALS_CONDITION'
,p_internal_uid=>1803566355407926.4001
);
