wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(3201962690436619.4001)
,p_plug_name=>'Definiciones de tarea'
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody'
,p_plug_template=>wwv_flow_imp.id(174794400314076650.4001)
,p_plug_display_sequence=>10
,p_plug_display_point=>'REGION_POSITION_03'
,p_plug_item_display_point=>'BELOW'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'    Las <strong>definiciones de tarea</strong> especifican las propiedades de una tarea humana.',
unistr('    Se utilizan para crear instancias de tarea y, a continuaci\00F3n, realizar acciones'),
unistr('    pertinentes (como aprobar o rechazar las instancias de tarea). Tambi\00E9n se pueden'),
'    reclamar, liberar, delegar o cancelar tareas.',
'</p>',
'<p>',
unistr('    Los <strong>participantes de una definici\00F3n de tarea</strong> son los participantes de'),
'    una tarea humana que pueden intervenir en la tarea. Los participantes pueden ser del tipo',
'    <strong>propietario potencial</strong> o <strong>administrador de negocio',
'    </strong>.',
'</p>',
'<p>',
unistr('    Los <strong>par\00E1metros de definici\00F3n de tarea</strong> especifican los par\00E1metros de una'),
'    tarea humana. Suelen ser atributos de un sistema de registros',
unistr('    para el que se ha definido la tarea. Constituyen la carga \00FAtil de la tarea.'),
'</p>',
'<p>',
unistr('    Las <strong>acciones de definici\00F3n de tarea</strong> se disparan cuando tienen lugar eventos'),
'    en la tarea. Entre los eventos se incluyen los siguientes:',
'</p>',
'<ul>',
'    <li><strong>Reclamar</strong></li>',
'    <li><strong>Completar</strong></li>',
'    <li><strong>Delegar</strong></li>',
'    <li><strong>Actualizar comentario</strong></li>',
'    <li><strong>Actualizar prioridad</strong></li>',
unistr('    <li><strong>Actualizar par\00E1metro</strong></li>'),
'    <li><strong>Liberar</strong></li>',
'    <li><strong>Cancelar</strong></li>',
'    <li><strong>Crear</strong></li>',
unistr('    <li><strong>Solicitar informaci\00F3n</strong></li>'),
unistr('    <li><strong>Enviar informaci\00F3n</strong></li>'),
'    <li><strong>Antes de la caducidad</strong></li>',
'    <li><strong>Caducidad</strong></li>',
'</ul>',
'<p>',
unistr('    <a target="_blank" href="&SYSTEM_HELP_URL.">M\00E1s informaci\00F3n...</a>'),
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
