,p_cHeight=>10
,p_field_template=>wwv_flow_imp.id(561549638722251517.4001)
,p_item_template_options=>'#DEFAULT#'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    Proporcione el c\00F3digo PL/SQL que se va a ejecutar. Los valores de las columnas de la consulta de acci\00F3n de definici\00F3n de tarea est\00E1n disponibles como variables de enlace, por nombre de columna, por ejemplo <strong>:EMPNO</strong>, <strong>:ENAME<')
||unistr('/strong>, etc. Adem\00E1s, APEX proporciona las siguientes variables de enlace gen\00E9ricas:'),
'</p>',
'<ul>',
'    <li><strong>APEX$TASK_PK</strong>: si se ha definido una columna de clave primaria, esta variable de enlace contiene el valor de la clave primaria.</li>',
unistr('    <li><strong>APEX$TASK_ID</strong>: esta variable de enlace contiene el ID de la tarea para la que se ha definido esta acci\00F3n.</li>'),
unistr('    <li><strong>APEX$TASK_SUBJECT</strong>: esta variable de enlace contiene el asunto de la tarea para la que se ha definido esta acci\00F3n</li>'),
unistr('    <li><strong>APEX$TASK_STATE</strong>: esta variable de enlace contiene el estado actual de la tarea para la que se ha definido esta acci\00F3n.</li>'),
unistr('    <li><strong>APEX$TASK_OUTCOME</strong>: esta variable de enlace contiene el resultado de la tarea para la que se ha definido esta acci\00F3n. Esta variable solo se rellena en tareas con estado <strong>Completado</strong>.</li>'),
unistr('    <li><strong>APEX$TASK_CREATED_ON</strong>: contiene el registro de hora de la creaci\00F3n de la tarea, en el formato <strong>AAAA-MM-DD"T"HH24:MI:SS.FF3TZH:TZM</strong>.</li>        '),
unistr('    <li><strong>APEX$TASK_INITIATOR</strong>: contiene el usuario que ha iniciado la tarea. Este valor se establece por defecto como el usuario que inici\00F3 sesi\00F3n, si no se especific\00F3 de manera expl\00EDcita como parte del tipo de proceso de p\00E1gina <stron')
||unistr('g>Tarea humana - Creaci\00F3n</strong>.</li>        '),
unistr('    <li><strong>APEX$TASK_DUE_ON</strong>: contiene el registro de hora de cu\00E1ndo vence la tarea, en el formato <strong>AAAA-MM-DD"T"HH24:MI:SS.FF3TZH:TZM</strong>.</li>        '),
unistr('    <li><strong>APEX$TASK_OWNER</strong>: contiene el usuario a quien est\00E1 asignada la tarea actualmente.</li>'),
unistr('    <li> Los par\00E1metros de la definici\00F3n de la tarea tambi\00E9n est\00E1n disponibles como variables de enlace.</li>'),
'</ul>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_01', 'PLSQL',
  'attribute_02', 'VARCHAR2',
  'attribute_03', 'Y',
  'attribute_04', 'Y',
  'attribute_07', 'N')).to_clob
);
