,p_name=>'P9506_ACTION_TYPE'
,p_source_data_type=>'VARCHAR2'
,p_is_required=>true
,p_item_sequence=>60
,p_item_plug_id=>wwv_flow_imp.id(3379750715607841.4001)
,p_item_source_plug_id=>wwv_flow_imp.id(3379750715607841.4001)
,p_item_default=>'NATIVE_PLSQL'
,p_prompt=>'Tipo'
