'  (select wwv_flow_lang.system_message(''WORKFLOW_VERSION'') a from sys.dual) t',
'where  ',
'  t.flow_ID = :FB_FLOW_ID and',
'  t.security_group_id = :flow_security_group_id and',
'  t.flow_table = ''WWV_FLOW_WORKFLOW_VERSIONS''',
'union  ',
'select ',
