,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'try {',
'    apex.message.clearErrors();',
'    let errorsArray = [],',
'        objectType;',
'',
'    checkItemAndAddError( "P9801_BASE_URL", apex.lang.getMessage( "APEX.AI.TEST_CONNECTION_BASE_URL_VALIDATION" ), errorsArray );',
'    if( apex.item( "P9801_APIKEY_CREDENTIAL_ID" ).isEmpty() ){',
'        checkItemAndAddError( "P9801_API_KEY", apex.lang.getMessage( "APEX.AI.TEST_CONNECTION_APIKEY_VALIDATION" ), errorsArray );',
'    }',
'    if( !apex.item( "P9801_BASE_URL" ).getValue().toLowerCase().includes( ".openai.azure." ) ){',
'        checkItemAndAddError( "P9801_AI_MODEL_NAME", apex.lang.formatMessageNoEscape( "APEX.AI.TEST_CONNECTION_MODEL_VALIDATION" ), errorsArray );',
'    }    ',
'    if( errorsArray.length > 0 ){',
'        apex.message.showErrors( errorsArray );',
'        apex.da.cancel();',
'    }',
'} catch ( pError ) {',
'    apex.message.showErrors([',
'        {',
'            type: "error",',
'            location: "page",',
'            message: pError,',
'            unsafe: true',
'        }',
'    ]);',
'    apex.da.cancel();',
'}'))
,p_client_condition_type=>'JAVASCRIPT_EXPRESSION'
,p_client_condition_expression=>wwv_flow_string.join(wwv_flow_t_varchar2(
'apex.item( "P9801_AI_PROVIDER_TYPE" ).getValue() === "OPENAI"',
'    || apex.item( "P9801_AI_PROVIDER_TYPE" ).getValue() === "COHERE"'))
