'        checkItemAndAddError( "P9811_OCI_PRIVATE_KEY", apex.lang.getMessage( "APEX.AI.TEST_CONNECTION_OCI.PRIVATEKEY_VALIDATION" ), errorsArray );',
'        checkItemAndAddError( "P9811_OCI_TENANCY_ID", apex.lang.getMessage( "APEX.AI.TEST_CONNECTION_OCI.TENANCY_VALIDATION" ), errorsArray );',
'        checkItemAndAddError( "P9811_OCI_FINGERPRINT", apex.lang.getMessage( "APEX.AI.TEST_CONNECTION_OCI.FINGERPRINT_VALIDATION" ), errorsArray );',
'    }',
'    if( errorsArray.length > 0 ){',
'        apex.message.showErrors( errorsArray );',
'        apex.da.cancel();',
'    }',
'} catch ( pError ) {',
'    apex.message.showErrors([',
'        {',
'            type: "error",',
