'            message: pError,',
'            unsafe: false',
'        }',
'    ]);',
'    apex.da.cancel();',
'}'))
,p_client_condition_type=>'EQUALS'
,p_client_condition_element=>'P9811_AI_PROVIDER_TYPE'
,p_client_condition_expression=>'OCI_GENAI'
);
