,p_action_sequence=>40
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'try {',
'    apex.message.clearErrors();',
'    apex.server.process(',
'        ''TestGenAIVectorConn'',',
'        {',
'            x01: apex.item( "P9811_NAME" ).getValue(),',
'            x02: apex.item( "P9811_STATIC_ID" ).getValue(),',
'            x03: apex.item( "P9811_BASE_URL" ).getValue(),',
'            x04: apex.item( "P9811_APIKEY_CREDENTIAL_ID" ).getValue(),',
'            x05: apex.item( "P9811_AI_PROVIDER_TYPE" ).getValue(),',
'            x06: apex.item( "P9811_AI_MODEL_NAME" ).getValue(),',
'            x07: apex.item( "P9811_AI_HTTP_HEADERS" ).getValue(),',
'            x08: apex.item( "P9811_AI_ATTRIBUTES" ).getValue(),',
'            x09: apex.item( "P9811_API_KEY" ).getValue(),',
'            x10: apex.item( "P9811_OCI_USER_ID" ).getValue(),',
'            x11: apex.item( "P9811_OCI_TENANCY_ID" ).getValue(),',
'            x12: apex.item( "P9811_OCI_PRIVATE_KEY" ).getValue(),',
'            x13: apex.item( "P9811_OCI_FINGERPRINT" ).getValue(),',
'            x14: apex.item( "P9811_OCI_CREDENTIAL_ID" ).getValue(),',
'            x15: apex.item( "P9811_OCI_MODEL_ID" ).getValue(), ',
'        },',
'        {   ',
'            loadingIndicator: "body",',
'            loadingIndicatorPosition: "centered",',
'            success: function( data ){',
'                if ( data.status != 200 ) {',
'                    apex.message.showErrors([',
'                        {',
'                            type: "error",',
'                            location: "page",',
'                            message: apex.lang.formatMessageNoEscape( "APEX.AI.TEST_CONNECTION_ERROR", data.message),',
'                            unsafe: false',
'                        }',
'                    ]);',
